/// DBG (`CRATONVM_DBG_IMSE`): dump the complete `ReentrantReadWriteLock$Sync`
/// read-hold bookkeeping at the moment an `IllegalMonitorStateException` is
/// thrown from `tryReleaseShared` — names WHICH invariant broke (firstReader
/// identity, cachedHoldCounter tid/count, or the current thread's `readHolds`
/// ThreadLocalMap entry) for the ES `testAllEqual` hold-count-loss face.
fn dump_imse_holdcount_state(shared: &SharedVm, thread: &JvmThread, exc: ObjectRef) {
    let exc_class = {
        let cm = shared.classes.class_manager.read();
        cm.get_class(shared.mem.heap.class_id_of(exc))
            .map(|c| c.name.to_string())
            .unwrap_or_default()
    };
    if !exc_class.contains("IllegalMonitorStateException") {
        return;
    }
    // Find the tryReleaseShared frame; local 0 is the Sync receiver.
    let sync = thread.frames.iter().rev().find_map(|f| {
        if f.method_name() == "tryReleaseShared" && f.class_name().contains("ReadWriteLock") {
            match f.get_local(0) {
                Value::Object(Some(o)) => Some(o),
                _ => None,
            }
        } else {
            None
        }
    });
    let Some(sync) = sync else {
        eprintln!("[imse] IllegalMonitorStateException thrown but no tryReleaseShared frame");
        return;
    };
    let cm = shared.classes.class_manager.read();
    let field = |obj: ObjectRef, name: &str| -> Value {
        let cid = shared.mem.heap.class_id_of(obj);
        match crate::vm::vm_exec::resolve_field_index_in_hierarchy(cid, name, &cm.class_store) {
            Some(idx) => shared.mem.heap.get_field(obj, idx),
            None => Value::Uninitialized,
        }
    };
    let me = thread.java_thread_obj;
    let first_reader = field(sync, "firstReader");
    let first_count = field(sync, "firstReaderHoldCount");
    let cached = field(sync, "cachedHoldCounter");
    let read_holds = field(sync, "readHolds");
    eprintln!(
        "[imse] tid={} me={:?} sync={:p} firstReader={:?} firstReaderHoldCount={:?}",
        thread.thread_id.0,
        me.map(|o| o.as_ptr()),
        sync.as_ptr(),
        first_reader,
        first_count,
    );
    if let Value::Object(Some(rh)) = cached {
        eprintln!(
            "[imse]   cachedHoldCounter={:p} count={:?} tid={:?}",
            rh.as_ptr(),
            field(rh, "count"),
            field(rh, "tid"),
        );
    } else {
        eprintln!("[imse]   cachedHoldCounter={cached:?}");
    }
    // Walk the CURRENT thread's ThreadLocalMap for the readHolds entry.
    let Value::Object(Some(read_holds)) = read_holds else {
        eprintln!("[imse]   readHolds={read_holds:?} (field missing?)");
        return;
    };
    let Some(me) = me else {
        eprintln!("[imse]   no java_thread_obj for current thread");
        return;
    };
    let tl_map = field(me, "threadLocals");
    let Value::Object(Some(tl_map)) = tl_map else {
        eprintln!(
            "[imse]   readHolds={:p} but thread has NO threadLocals map",
            read_holds.as_ptr()
        );
        return;
    };
    let table = field(tl_map, "table");
    let Value::Object(Some(table)) = table else {
        eprintln!(
            "[imse]   threadLocals map {:p} has NO table",
            tl_map.as_ptr()
        );
        return;
    };
    let len = shared.mem.heap.array_length(table);
    let mut found = false;
    for i in 0..len {
        let Ok(Value::Object(Some(entry))) = shared.mem.heap.get_array_element(table, i) else {
            continue;
        };
        // Entry extends WeakReference<ThreadLocal>; referent is field 0.
        let referent = shared.mem.heap.get_field(entry, 0);
        let is_ours =
            matches!(referent, Value::Object(Some(r)) if r.as_ptr() == read_holds.as_ptr());
        if is_ours {
            found = true;
            let value = field(entry, "value");
            let vdesc = if let Value::Object(Some(hc)) = value {
                format!(
                    "HoldCounter@{:p} count={:?} tid={:?}",
                    hc.as_ptr(),
                    field(hc, "count"),
                    field(hc, "tid"),
                )
            } else {
                format!("{value:?}")
            };
            eprintln!(
                "[imse]   readHolds={:p}: table[{i}] entry={:p} value={vdesc}",
                read_holds.as_ptr(),
                entry.as_ptr(),
            );
        }
    }
    if !found {
        eprintln!(
            "[imse]   readHolds={:p}: NO ThreadLocalMap entry in current thread's table (len={len}) — the entry is GONE",
            read_holds.as_ptr(),
        );
    }
}

/// G13-1 (2026-08-17) — the Path B interface-substitution table, and the
/// property that makes an ARRAY receiver a refusal rather than a guess.
///
/// These live inline rather than in `interpreter/tests.rs` because this lane
/// owns exactly one file. They are pure-function tests: nothing here builds a
/// VM, so they run in milliseconds and cannot flake.
#[cfg(test)]
mod g13_array_receiver_tests {
    use super::canonical_concrete_for_interface;

    /// The six names Path B substitutes for, pinned. If a lane adds a seventh,
    /// this test is where it has to say so — and the array refusal at the call
    /// site picks it up automatically, because it reads the same function.
    #[test]
    fn the_substituted_interfaces_are_exactly_these_six() {
        let mapped: Vec<(&str, &str)> = [
            "java/util/Set",
            "java/util/Collection",
            "java/lang/Iterable",
            "java/util/List",
            "java/util/Map",
            "java/util/Iterator",
        ]
        .into_iter()
        .map(|i| (i, canonical_concrete_for_interface(i)))
        .collect();
        assert_eq!(
            mapped,
            vec![
                ("java/util/Set", "java/util/HashSet"),
                ("java/util/Collection", "java/util/HashSet"),
                ("java/lang/Iterable", "java/util/ArrayList"),
                ("java/util/List", "java/util/ArrayList"),
                ("java/util/Map", "java/util/HashMap"),
                ("java/util/Iterator", "java/util/HashMap$KeyItr"),
            ]
        );
    }

    /// The load-bearing absence. An array type implements `Cloneable` and
    /// `java.io.Serializable` and nothing else (JLS 4.10.3). If either ever
    /// gained a canonical mapping, "canonical is non-empty AND receiver is an
    /// array" would stop being a proof of `IncompatibleClassChangeError` — so
    /// the refusal's soundness is asserted here, not just commented.
    #[test]
    fn the_two_interfaces_an_array_really_implements_are_never_substituted() {
        assert_eq!(canonical_concrete_for_interface("java/lang/Cloneable"), "");
        assert_eq!(canonical_concrete_for_interface("java/io/Serializable"), "");
    }

    /// The refusal must not swallow ordinary `Object` methods on an array.
    /// `clone`/`hashCode`/`getClass` on an `Object[]` are legal and reach the
    /// no-`Code` arm through `java/lang/Object`, which maps to nothing — so
    /// the array check cannot fire for them.
    #[test]
    fn object_and_unrelated_types_are_not_substituted() {
        for name in [
            "java/lang/Object",
            "java/util/Map$Entry",
            "java/util/SequencedCollection",
            "java/net/http/HttpRequest",
            "java/util/stream/Stream",
            "",
        ] {
            assert_eq!(
                canonical_concrete_for_interface(name),
                "",
                "{name} must not be substituted"
            );
        }
    }

    /// The exact triple this record was written about:
    /// `java/util/Map.isEmpty()Z` on an `Object[]` receiver. `java/util/Map`
    /// is substituted, so an array receiver at that site is refused.
    ///
    /// MEASURED counterpart: `[CANONICAL] java/util/Map java/util/HashMap
    /// isEmpty 1` — the only row the whole 105-class corpus produces, in
    /// either policy mode.
    #[test]
    fn the_map_is_empty_triple_is_the_substituted_one() {
        assert_eq!(
            canonical_concrete_for_interface("java/util/Map"),
            "java/util/HashMap"
        );
        assert!(!canonical_concrete_for_interface("java/util/Map").is_empty());
    }
}

/// Interpreter round i1, lane L1: the raw-bytecode fast path, run end to end.
///
/// Each test hands a synthetic frame to `execute_prebuilt_frame`, so the bytes
/// go through the real dispatch loop — preamble, fast-path `match`, fusions,
/// return arm — exactly as a Java method would. Every sequence below is
/// covered by fast-path arms only, so no class metadata is needed.
#[cfg(test)]
mod l1_dispatch_tests {
    use super::*;
    use crate::threading::jvm_thread::ThreadId;

    fn run_with(
        name: &str,
        desc: &str,
        code: Vec<u8>,
        max_stack: u16,
        max_locals: u16,
        setup: impl FnOnce(&mut Frame),
    ) -> MethodCallResult {
        // Beyond the type-map store's addressable id range, so no verifier
        // maps can exist for it and the per-method fast-path gate admits it.
        run_in_class(
            ClassId::new(0x00F1_0001),
            name,
            desc,
            code,
            max_stack,
            max_locals,
            setup,
        )
    }

    fn run_in_class(
        class_id: ClassId,
        name: &str,
        desc: &str,
        code: Vec<u8>,
        max_stack: u16,
        max_locals: u16,
        setup: impl FnOnce(&mut Frame),
    ) -> MethodCallResult {
        // Heap-pinned like every other test that builds one: nothing may move
        // the VM after construction.
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        run_on(
            &shared, class_id, name, desc, code, max_stack, max_locals, setup,
        )
    }

    /// [`run_in_class`] on a caller-built VM, for a test that arms VM state
    /// (a debugger request, a channel) before the method runs.
    #[allow(clippy::too_many_arguments)]
    fn run_on(
        shared: &SharedVm,
        class_id: ClassId,
        name: &str,
        desc: &str,
        code: Vec<u8>,
        max_stack: u16,
        max_locals: u16,
        setup: impl FnOnce(&mut Frame),
    ) -> MethodCallResult {
        let mut thread = JvmThread::new(ThreadId(0), "l1-dispatch-test");
        let mut frame = Frame::new(
            class_id,
            "cratonvm/test/L1Dispatch".to_string(),
            name.to_string(),
            desc.to_string(),
            None,
            code,
            Vec::new(),
            max_stack,
            max_locals,
            &[],
        );
        setup(&mut frame);
        execute_prebuilt_frame(shared, &mut thread, frame)
    }

    fn run(name: &str, desc: &str, code: Vec<u8>, max_stack: u16, max_locals: u16) -> Value {
        match run_with(name, desc, code, max_stack, max_locals, |_| {}) {
            Ok(Some(v)) => v,
            other => panic!("{name}: expected a value return, got {other:?}"),
        }
    }

    fn int(name: &str, code: Vec<u8>, max_stack: u16, max_locals: u16) -> i32 {
        match run(name, "()I", code, max_stack, max_locals) {
            Value::Int(v) => v,
            other => panic!("{name}: expected an int, got {other:?}"),
        }
    }

    fn long(name: &str, code: Vec<u8>) -> i64 {
        match run(name, "()J", code, 4, 0) {
            Value::Long(v) => v,
            other => panic!("{name}: expected a long, got {other:?}"),
        }
    }

    /// A double whose NaN payload collides with the SUB_INT tag space, held in
    /// a local WITHOUT the `LKIND_DOUBLE` mark (`set_local_compact` never
    /// writes it). `dload_0` must hand it to `dreturn` bit for bit — the same
    /// answer the wide `dload 0` spelling always gave.
    #[test]
    fn dload_n_is_bit_exact_like_wide_dload() {
        const BITS: u64 = 0xFFFC_0000_0000_0005;
        for (name, code) in [
            ("dloadShort", vec![0x26, 0xaf]),      // dload_0; dreturn
            ("dloadWide", vec![0x18, 0x00, 0xaf]), // dload 0; dreturn
        ] {
            let r = run_with(name, "()D", code, 2, 2, |f| {
                f.set_local_compact(0, CompactValue::from_bits(BITS));
            });
            match r {
                Ok(Some(Value::Double(d))) => {
                    assert_eq!(d.to_bits(), BITS, "{name} must not reinterpret the payload")
                }
                other => panic!("{name}: expected a double, got {other:?}"),
            }
        }
    }

    /// JVMS idiv/irem: `MIN / -1` overflows to MIN and `MIN % -1` is 0, with no
    /// exception; int and long shift distances are masked to 5 and 6 bits.
    #[test]
    fn integer_division_and_shift_edges() {
        // iconst_1; bipush 31; ishl  => Integer.MIN_VALUE
        let min = [0x04, 0x10, 31, 0x78];
        let mut idiv = min.to_vec();
        idiv.extend([0x02, 0x6c, 0xac]); // iconst_m1; idiv; ireturn
        assert_eq!(int("idivMinByMinusOne", idiv, 2, 0), i32::MIN);
        let mut irem = min.to_vec();
        irem.extend([0x02, 0x70, 0xac]); // iconst_m1; irem; ireturn
        assert_eq!(int("iremMinByMinusOne", irem, 2, 0), 0);
        // iconst_1; bipush 33; ishl => 1 << (33 & 31)
        assert_eq!(int("ishlMasked", vec![0x04, 0x10, 33, 0x78, 0xac], 2, 0), 2);
        // lconst_1; bipush 65; lshl => 1L << (65 & 63)
        assert_eq!(long("lshlMasked", vec![0x0a, 0x10, 65, 0x79, 0xad]), 2);
        // lconst_1; lconst_0; lcmp
        assert_eq!(int("lcmpGreater", vec![0x0a, 0x09, 0x94, 0xac], 4, 0), 1);
        // (1L << 32) + 1; l2i => 1
        let l2i = vec![0x0a, 0x10, 32, 0x79, 0x0a, 0x61, 0x88, 0xac];
        assert_eq!(int("l2iTruncates", l2i, 4, 0), 1);
    }

    /// fcmpl/dcmpl answer -1 on NaN, fcmpg/dcmpg answer 1; f2i of NaN is 0 and
    /// d2l / d2i saturate at the infinities (JVMS §2.8.3).
    #[test]
    fn float_compare_and_convert_edges() {
        // fconst_0; fconst_0; fdiv => NaN
        let fnan = [0x0b, 0x0b, 0x6e];
        let mut fcmpl = fnan.to_vec();
        fcmpl.extend([0x0c, 0x95, 0xac]); // fconst_1; fcmpl; ireturn
        assert_eq!(int("fcmplNaN", fcmpl, 2, 0), -1);
        let mut fcmpg = fnan.to_vec();
        fcmpg.extend([0x0c, 0x96, 0xac]);
        assert_eq!(int("fcmpgNaN", fcmpg, 2, 0), 1);
        let mut f2i = fnan.to_vec();
        f2i.extend([0x8b, 0xac]);
        assert_eq!(int("f2iNaN", f2i, 2, 0), 0);
        // dconst_0; dconst_0; ddiv => NaN
        let dnan = [0x0e, 0x0e, 0x6f];
        let mut dcmpl = dnan.to_vec();
        dcmpl.extend([0x0f, 0x97, 0xac]);
        assert_eq!(int("dcmplNaN", dcmpl, 4, 0), -1);
        let mut dcmpg = dnan.to_vec();
        dcmpg.extend([0x0f, 0x98, 0xac]);
        assert_eq!(int("dcmpgNaN", dcmpg, 4, 0), 1);
        // dconst_1; dconst_0; ddiv => +inf; d2l
        assert_eq!(
            long("d2lPosInf", vec![0x0f, 0x0e, 0x6f, 0x8f, 0xad]),
            i64::MAX
        );
        // dconst_1; dneg; dconst_0; ddiv => -inf; d2i
        let d2i = vec![0x0f, 0x77, 0x0e, 0x6f, 0x8e, 0xac];
        assert_eq!(int("d2iNegInf", d2i, 4, 0), i32::MIN);
    }

    /// JVMS §6.5 `ireturn` narrows to a `boolean`/`byte`/`char`/`short`
    /// declared return type, as the baseline JIT does; `int` is untouched.
    #[test]
    fn ireturn_narrows_to_the_declared_return_type() {
        let ret = |name: &str, desc: &str, code: Vec<u8>| match run(name, desc, code, 2, 0) {
            Value::Int(v) => v,
            other => panic!("{name}: expected an int, got {other:?}"),
        };
        // iconst_2; ireturn
        assert_eq!(ret("narrowZ", "()Z", vec![0x05, 0xac]), 0);
        assert_eq!(ret("narrowI", "()I", vec![0x05, 0xac]), 2);
        // sipush 384; ireturn => (byte) 384 == -128
        assert_eq!(ret("narrowB", "()B", vec![0x11, 0x01, 0x80, 0xac]), -128);
        // iconst_m1; ireturn => (char) -1 == 65535
        assert_eq!(ret("narrowC", "()C", vec![0x02, 0xac]), 65535);
        // iconst_1; bipush 16; ishl; iconst_m1; iadd => 65535; (short) == -1
        let s = vec![0x04, 0x10, 16, 0x78, 0x02, 0x60, 0xac];
        assert_eq!(ret("narrowS", "()S", s), -1);
        assert_eq!(narrow_ireturn(3, b'Z'), 1);
        assert_eq!(narrow_ireturn_value(Value::Long(7), b'Z'), Value::Long(7));
    }

    /// The pure saturation helpers the conversion arms share with the decoded
    /// path.
    #[test]
    fn conversion_helpers_follow_jvms() {
        assert_eq!(float_to_int(f32::NAN), 0);
        assert_eq!(float_to_int(f32::INFINITY), i32::MAX);
        assert_eq!(float_to_int(f32::NEG_INFINITY), i32::MIN);
        assert_eq!(float_to_int(-1.9), -1);
        assert_eq!(float_to_long(f32::NAN), 0);
        assert_eq!(float_to_long(1e30), i64::MAX);
        assert_eq!(double_to_int(f64::NAN), 0);
        assert_eq!(double_to_int(2147483647.9), i32::MAX);
        assert_eq!(double_to_int(-2147483648.9), i32::MIN);
        assert_eq!(double_to_long(f64::NAN), 0);
        assert_eq!(double_to_long(-1e300), i64::MIN);
        assert_eq!(double_to_long(9.2e18), 9_200_000_000_000_000_000);
    }

    /// `swap`, `dup`, the `f*` local arms and wide `istore`/`iload` now copy raw
    /// slots instead of decoding to `Value`; the answers must not move.
    #[test]
    fn slot_copy_arms_keep_their_answers() {
        // iconst_1; iconst_2; swap; isub => 2 - 1
        assert_eq!(int("swapInts", vec![0x04, 0x05, 0x5f, 0x64, 0xac], 2, 0), 1);
        // iconst_5; dup; iadd
        assert_eq!(int("dupInt", vec![0x08, 0x59, 0x60, 0xac], 2, 0), 10);
        // fconst_2; fstore_1; fload_1; fload_1; fmul; freturn
        let fl = vec![0x0d, 0x44, 0x23, 0x23, 0x6a, 0xae];
        match run("floatLocals", "()F", fl, 2, 2) {
            Value::Float(f) => assert_eq!(f, 4.0),
            other => panic!("floatLocals: expected a float, got {other:?}"),
        }
        // bipush 7; istore 1; iload 1; ireturn (explicit-index forms)
        assert_eq!(
            int("wideIndexInt", vec![0x10, 7, 0x36, 1, 0x15, 1, 0xac], 1, 2),
            7
        );
    }

    /// The `iload; iload; iadd`, `iload; iload; if_icmplt` (with its back
    /// edge) and `iload; iconst_1; iadd; istore` fusions, in one counted loop:
    /// `int s = 0; for (int i = 0; i < 10; i++) s += i; return s;`, plus a
    /// branch-free increment.
    #[test]
    fn superinstruction_fusions_compute_the_unfused_answer() {
        let sum = vec![
            0x03, 0x3b, // 0: iconst_0; istore_0        i = 0
            0x03, 0x3c, // 2: iconst_0; istore_1        s = 0
            0x10, 10, 0x3d, // 4: bipush 10; istore_2   n = 10
            0x1b, 0x1a, 0x60, 0x3c, // 7: iload_1; iload_0; iadd; istore_1
            0x84, 0, 1, // 11: iinc 0 1
            0x1a, 0x1c, 0xa1, 0xff, 0xf7, // 14: iload_0; iload_2; if_icmplt -9 (-> 7)
            0x1b, 0xac, // 19: iload_1; ireturn
        ];
        assert_eq!(int("fusedCountedLoop", sum, 2, 3), 45);
        // iconst_0; istore_0; iload_0; iconst_1; iadd; istore_0; iload_0; ireturn
        let inc = vec![0x03, 0x3b, 0x1a, 0x04, 0x60, 0x3b, 0x1a, 0xac];
        assert_eq!(int("fusedIncrement", inc, 2, 1), 1);
    }

    // ── Interpreter round i1, wave 2 (lane L1) ──────────────────────────

    /// `<prologue>; <group>; if_icmp<op> +5; iconst_0; ireturn; iconst_1;
    /// ireturn`: answers 1 iff the fused (or unfused) branch was taken.
    fn branch_answer(name: &str, prologue: &[u8], group: &[u8], op: u8, max_locals: u16) -> i32 {
        let mut code = prologue.to_vec();
        code.extend_from_slice(group);
        code.extend_from_slice(&[op, 0x00, 0x05, 0x03, 0xac, 0x04, 0xac]);
        int(name, code, 2, max_locals)
    }

    /// Every `if_icmp<cond>` fused behind every second-operand shape the
    /// fusion admits — `iload_N`, `iload n`, `bipush`, `sipush`, `iconst_*` —
    /// and behind an `iload n` first operand, against the plain predicate.
    #[test]
    fn compare_and_branch_fusions_match_every_condition() {
        let ops: [(u8, fn(i32, i32) -> bool); 6] = [
            (0x9f, |a: i32, b: i32| a == b),
            (0xa0, |a: i32, b: i32| a != b),
            (0xa1, |a: i32, b: i32| a < b),
            (0xa2, |a: i32, b: i32| a >= b),
            (0xa3, |a: i32, b: i32| a > b),
            (0xa4, |a: i32, b: i32| a <= b),
        ];
        let pairs: [(i8, i8); 4] = [(-5, 7), (7, -5), (3, 3), (-128, 127)];
        for (op, pred) in ops {
            for (a, b) in pairs {
                let (ab, bb) = (a as u8, b as u8); // Cast: test operand bytes
                let want = pred(i32::from(a), i32::from(b)) as i32;
                // iload_0; iload_1
                let p = [0x10, ab, 0x3b, 0x10, bb, 0x3c];
                assert_eq!(branch_answer("iloadIload", &p, &[0x1a, 0x1b], op, 2), want);
                // iload_0; bipush b
                let p = [0x10, ab, 0x3b];
                assert_eq!(
                    branch_answer("iloadBipush", &p, &[0x1a, 0x10, bb], op, 1),
                    want
                );
                // iload 4; iload 5
                let p = [0x10, ab, 0x36, 4, 0x10, bb, 0x36, 5];
                let g = [0x15, 4, 0x15, 5];
                assert_eq!(branch_answer("iloadNIloadN", &p, &g, op, 6), want);
                // iload 4; iload_1
                let p = [0x10, ab, 0x36, 4, 0x10, bb, 0x3c];
                assert_eq!(
                    branch_answer("iloadNIload1", &p, &[0x15, 4, 0x1b], op, 5),
                    want
                );
            }
            for (a, b) in [(-300i32, 300i32), (1000, 1000), (1000, -300)] {
                // iload_0; sipush b (a set through sipush too)
                let [ah, al] = (a as i16).to_be_bytes(); // Cast: test operand bytes
                let [bh, bl] = (b as i16).to_be_bytes(); // Cast: test operand bytes
                let p = [0x11, ah, al, 0x3b];
                let got = branch_answer("iloadSipush", &p, &[0x1a, 0x11, bh, bl], op, 1);
                assert_eq!(got, pred(a, b) as i32, "sipush op=0x{op:x} a={a} b={b}");
            }
            for k in -1i32..=5 {
                // iload_0; iconst_k, with local 0 = 2
                let konst = (0x03 + k) as u8; // Cast: iconst_m1..iconst_5 opcode
                let got = branch_answer("iloadIconst", &[0x05, 0x3b], &[0x1a, konst], op, 1);
                assert_eq!(got, pred(2, k) as i32, "iconst op=0x{op:x} k={k}");
            }
        }
    }

    /// javac's top-tested counted loop, unchanged from what `javac` emits for
    /// `int s = 0; for (int i = 0; i < n; i++) s += i; return s;`: the
    /// `iload; iload; if_icmpge` test fuses, as does the `iinc; goto` step,
    /// and the `goto` is the back edge. Then the same loop with its counter
    /// and sum in locals 4 and 5 and a `bipush` bound.
    #[test]
    fn javac_shaped_counted_loops_fuse_and_keep_their_answer() {
        let low = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        assert_eq!(int("javacLoopLowLocals", low, 2, 3), 45);
        let high = vec![
            0x03, 0x36, 4, // 0: iconst_0; istore 4          i = 0
            0x03, 0x36, 5, // 3: iconst_0; istore 5          s = 0
            0x15, 4, 0x10, 10, 0xa2, 0x00, 16, // 6: iload 4; bipush 10; if_icmpge +16 (-> 26)
            0x15, 5, 0x15, 4, 0x60, 0x36, 5, // 13: iload 5; iload 4; iadd; istore 5
            0x84, 4, 1, // 20: iinc 4 1
            0xa7, 0xff, 0xef, // 23: goto -17 (-> 6)
            0x15, 5, 0xac, // 26: iload 5; ireturn
        ];
        assert_eq!(int("javacLoopHighLocals", high, 2, 6), 45);
    }

    /// A branch that lands INSIDE a fusable group runs the rest of it unfused:
    /// the `goto` enters `iload_0; iload_1; if_icmpge` at its `iload_1`, with
    /// the first operand already on the stack.
    #[test]
    fn branch_into_a_fused_group_runs_it_unfused() {
        let code = vec![
            0x05, 0x3c, // 0: iconst_2; istore_1
            0x06, // 2: iconst_3
            0xa7, 0x00, 0x04, // 3: goto +4 (-> 7)
            0x1a, // 6: iload_0 (the group's first bytecode, skipped)
            0x1b, // 7: iload_1
            0xa2, 0x00, 0x05, // 8: if_icmpge +5 (-> 13): 3 >= 2
            0x03, 0xac, // 11: iconst_0; ireturn
            0x04, 0xac, // 13: iconst_1; ireturn
        ];
        assert_eq!(int("midGroupTarget", code, 2, 2), 1);
    }

    /// `wide iinc` on the fast path: a 16-bit constant each way, and a local
    /// past 255 whose load and store stay on the decoded `wide` forms.
    #[test]
    fn wide_iinc_takes_sixteen_bit_constants_and_indices() {
        let code = vec![
            0x03, 0x3b, // iconst_0; istore_0
            0xc4, 0x84, 0x00, 0x00, 0x03, 0xe8, // wide iinc 0 +1000
            0xc4, 0x84, 0x00, 0x00, 0xff, 0x9c, // wide iinc 0 -100
            0x1a, 0xac, // iload_0; ireturn
        ];
        assert_eq!(int("wideIincConstant", code, 1, 1), 900);
        let code = vec![
            0x03, 0xc4, 0x36, 0x01, 0x2c, // iconst_0; wide istore 300
            0xc4, 0x84, 0x01, 0x2c, 0x00, 0x07, // wide iinc 300 7
            0xc4, 0x15, 0x01, 0x2c, // wide iload 300
            0xac, // ireturn
        ];
        assert_eq!(int("wideIincIndex", code, 1, 301), 7);
    }

    /// `astore n` / `aload n` move a null reference verbatim, and
    /// `ifnull` / `ifnonnull` read it as null through the compact test.
    #[test]
    fn explicit_index_reference_locals_and_null_tests() {
        for (op, want) in [(0xc6u8, 1), (0xc7u8, 0)] {
            let code = vec![
                0x01, 0x3a, 4, // 0: aconst_null; astore 4
                0x19, 4, // 3: aload 4
                op, 0x00, 0x05, // 5: ifnull / ifnonnull +5 (-> 10)
                0x03, 0xac, // 8: iconst_0; ireturn
                0x04, 0xac, // 10: iconst_1; ireturn
            ];
            assert_eq!(int("nullLocal", code, 1, 5), want, "opcode 0x{op:x}");
        }
        // if_acmpeq / if_acmpne on two nulls, decided on the raw slots.
        for (op, want) in [(0xa5u8, 1), (0xa6u8, 0)] {
            let code = vec![
                0x01, 0x01, // 0: aconst_null; aconst_null
                op, 0x00, 0x05, // 2: if_acmpeq / if_acmpne +5 (-> 7)
                0x03, 0xac, // 5: iconst_0; ireturn
                0x04, 0xac, // 7: iconst_1; ireturn
            ];
            assert_eq!(int("acmpNulls", code, 2, 0), want, "opcode 0x{op:x}");
        }
        let mut mixed = crate::runtime::ValueStack::new(2);
        mixed.push_compact(CompactValue::null());
        mixed.push_int_unchecked(0);
        assert_eq!(
            acmp_on_raw_slots(&mixed),
            None,
            "a non-reference slot keeps the `Value` path"
        );
    }

    /// The per-method admission: a method whose verifier maps carry a
    /// `FastPathVeto` runs on the bounds-checked decoded path, so a
    /// `max_stack` overrun is an error return and not a panic inside an
    /// unchecked push; a method with no maps keeps the fast path.
    #[test]
    fn a_vetoed_method_runs_on_the_decoded_path() {
        // Inside the type-map store's addressable range (< 2^22) and far
        // above any id a unit-test VM mints.
        let vetoed = ClassId::new(0x003F_F001);
        let maps = cratonvm_classloading::MethodTypeMapsBuilder::new(0, 1).finish(false);
        assert!(!maps.safe_for_fast_path(), "an incomplete walk is a veto");
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        shared.classes.type_maps.publish(
            vetoed,
            cratonvm_classloading::ClassTypeMaps::new(vec![(
                Arc::from("vetoed"),
                Arc::from("()I"),
                Some(maps),
            )]),
        );
        // 40 x iconst_1; ireturn — forty pushes against max_stack 1. The
        // overrun must exceed the frame's operand-stack padding
        // (`max(max_stack, 16) + 8` slots, frame.rs) or it is absorbed and the
        // method legitimately returns.
        let mut code = vec![0x04u8; 40];
        code.push(0xac);
        let frame_in = |cid: ClassId| {
            Frame::new(
                cid,
                "cratonvm/test/L1Dispatch".to_string(),
                "vetoed".to_string(),
                "()I".to_string(),
                None,
                code.clone(),
                Vec::new(),
                1,
                0,
                &[],
            )
        };
        let probe = frame_in(vetoed);
        assert!(
            !frame_fast_path_admitted(&shared, &probe),
            "the veto closes the fast path"
        );
        assert!(
            !frame_fast_path_admitted(&shared, &probe),
            "and the memo keeps the answer"
        );
        let unmapped = frame_in(ClassId::new(0x00F1_0001));
        assert!(
            frame_fast_path_admitted(&shared, &unmapped),
            "no maps: unchanged"
        );

        match run_on(&shared, vetoed, "vetoed", "()I", code.clone(), 1, 0, |_| {}) {
            Ok(v) => panic!("an overrunning method must not return normally: {v:?}"),
            Err(e) => {
                let text = format!("{e:?}");
                assert!(
                    !text.contains("_unchecked") && !text.contains("index out of bounds"),
                    "the overrun reached an unchecked push: {text}"
                );
            }
        }
    }

    /// Wave 6: a method with no verifier maps is admitted to the fast path
    /// only when every local its code touches lies inside its frame, short
    /// forms included — `iload_3` in a one-slot frame used to index the
    /// locals `Vec` out of bounds (the short forms carry no `max_locals`
    /// guard) and now runs on the decoded path. Well-formed code, and a jump
    /// into an operand byte, are the two other sides of the proof.
    #[test]
    fn an_unproven_method_whose_locals_overrun_runs_on_the_decoded_path() {
        let unmapped = ClassId::new(0x00F1_0001);
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        // Distinct names: the padded code (and so the memo key) is shared per
        // `(class, name, descriptor, body)`.
        let admitted = |name: &str, code: &[u8], max_locals: u16| {
            let frame = Frame::new(
                unmapped,
                "cratonvm/test/L1Dispatch".to_string(),
                name.to_string(),
                "()I".to_string(),
                None,
                code.to_vec(),
                Vec::new(),
                2,
                max_locals,
                &[],
            );
            frame_fast_path_admitted(&shared, &frame)
        };
        let iload_3 = [0x1du8, 0xac]; // iload_3; ireturn
        assert!(
            !admitted("i6LocalsOverrun", &iload_3, 1),
            "iload_3 in one slot"
        );
        assert!(
            admitted("i6LocalsFit", &iload_3, 4),
            "iload_3 in four slots"
        );
        // lconst_0; lstore_3; iconst_0; ireturn — the long takes slots 3 and 4.
        let lstore_3 = [0x09u8, 0x42, 0x03, 0xac];
        assert!(
            !admitted("i6Cat2Overrun", &lstore_3, 4),
            "lstore_3 in four slots"
        );
        assert!(
            admitted("i6Cat2Fit", &lstore_3, 5),
            "lstore_3 in five slots"
        );
        // bipush 0x1d; goto -1: the jump lands on the operand, an `iload_3`.
        let into_operand = [0x10u8, 0x1d, 0xa7, 0xff, 0xff];
        assert!(
            !admitted("i6IntoOperand", &into_operand, 4),
            "jump into an operand"
        );

        // And it runs: the decoded `iload` reads an out-of-range local as
        // uninitialized instead of panicking.
        let _ = run_with("i6LocalsOverrunRuns", "()I", iload_3.to_vec(), 2, 1, |_| {});
    }

    // ── Interpreter round i1, wave 3 (lane L1) ──────────────────────────

    /// An `Object`-tagged slot whose payload never crossed an `ObjectRef`
    /// constructor in this process: `to_value` decodes it as a `long`. Built
    /// from raw bits (sub-tag `SUB_OBJECT` = 2 at bit 47, the NaN-box prefix
    /// taken from `CompactValue::null()`), so building it records nothing.
    /// Each caller passes its own address: the first `ObjectRef` built from
    /// one records it for the rest of the process.
    fn unrecorded_ref(addr: u64) -> CompactValue {
        let prefix = CompactValue::null().raw_bits() & !(0x7u64 << 47);
        let cv = CompactValue::from_bits(prefix | (2u64 << 47) | addr);
        assert_eq!(
            cv.tag(),
            CompactTag::Object,
            "test precondition: object tag"
        );
        assert_eq!(cv.as_object_ptr(), Some(addr), "test precondition: payload");
        assert!(
            matches!(cv.to_value(), Value::Long(_)),
            "test precondition: {addr:#x} must be unrecorded"
        );
        cv
    }

    /// A fresh VM in which the per-method fast-path gate is closed for
    /// `class_id`'s `name`+`desc`, so the method runs on the decoded path (see
    /// `a_vetoed_method_runs_on_the_decoded_path`). The maps go into THAT VM's
    /// type-map store: a `ClassId` means nothing in another VM.
    fn vetoed_vm(class_id: ClassId, name: &str, desc: &str) -> Arc<SharedVm> {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let maps = cratonvm_classloading::MethodTypeMapsBuilder::new(0, 1).finish(false);
        // Asserted: the store is first-writer-wins per class, so a second
        // veto for the same id in one VM would silently publish nothing.
        assert!(shared.classes.type_maps.publish(
            class_id,
            cratonvm_classloading::ClassTypeMaps::new(vec![(
                Arc::from(name),
                Arc::from(desc),
                Some(maps),
            )]),
        ));
        shared
    }

    fn returned_ref(name: &str, r: MethodCallResult) -> u64 {
        match r {
            Ok(Some(Value::Object(Some(o)))) => o.as_ptr() as u64, // Cast: address compare
            other => panic!("{name}: expected a reference return, got {other:?}"),
        }
    }

    /// `areturn`, `aload n`, `astore_<n>` and the decoded `Aload` / `Astore` /
    /// `Areturn` arms pass a reference with no recorded provenance through as
    /// that reference. `areturn` (and, on the decoded path, all three) used to
    /// decode it context-free as a `long` and return null.
    #[test]
    fn reference_arms_keep_an_unrecorded_reference() {
        let desc = "()Ljava/lang/Object;";
        let cases: [(&str, Vec<u8>, u64); 3] = [
            // aload_0; areturn
            ("areturnShort", vec![0x2a, 0xb0], 0x0000_5A5A_0001_0000),
            // aload 4; areturn
            ("areturnWide", vec![0x19, 4, 0xb0], 0x0000_5A5A_0002_0000),
            // aload_0; astore_1; aload_1; areturn
            (
                "areturnViaLocal",
                vec![0x2a, 0x4c, 0x2b, 0xb0],
                0x0000_5A5A_0003_0000,
            ),
        ];
        for (name, code, addr) in cases {
            let cv = unrecorded_ref(addr);
            let r = run_with(name, desc, code, 2, 5, |f| {
                f.set_local_compact(0, cv);
                f.set_local_compact(4, cv);
            });
            assert_eq!(returned_ref(name, r), addr, "{name}");
        }
        // The decoded path: aload_0; astore 4; aload 4; areturn.
        let decoded = ClassId::new(0x003F_F002);
        let shared = vetoed_vm(decoded, "decodedRefs", desc);
        let addr = 0x0000_5A5A_0004_0000;
        let cv = unrecorded_ref(addr);
        let code = vec![0x2a, 0x3a, 4, 0x19, 4, 0xb0];
        let r = run_on(&shared, decoded, "decodedRefs", desc, code, 2, 5, |f| {
            f.set_local_compact(0, cv);
        });
        assert_eq!(returned_ref("decodedRefs", r), addr);
    }

    /// The operand decode the reference arms share: a plain object slot is a
    /// reference, a KIND_LONG-marked slot with the same bits is not (it keeps
    /// the validated coerce), and null stays null.
    #[test]
    fn reference_operand_decode_honours_the_kind_mark() {
        let addr = 0x0000_5A5A_0005_0000;
        let cv = unrecorded_ref(addr);
        assert!(
            ref_slot_object(cv, crate::runtime::ValueStack::KIND_MARK_LONG).is_none(),
            "a long-marked slot is not a reference"
        );
        let r = ref_slot_object(cv, 0).expect("a plain object slot is a reference");
        assert_eq!(r.as_ptr() as u64, addr); // Cast: address compare
        assert!(ref_slot_object(CompactValue::null(), 0).is_none());
        assert_eq!(
            stack_slot_value(
                CompactValue::long(7),
                crate::runtime::ValueStack::KIND_MARK_LONG
            ),
            Value::Long(7)
        );
        let mut stack = crate::runtime::ValueStack::new(2);
        assert!(
            plain_ref_on_top(&stack).is_none(),
            "empty stack: no operand"
        );
        stack.push_int_unchecked(0);
        assert!(
            plain_ref_on_top(&stack).is_none(),
            "an int is not a reference"
        );
    }

    /// An int-tagged zero in a reference local (the "native returned 0 for
    /// null" shape) reads as null through every spelling of `aload` and is
    /// stored as null through every spelling of `astore`. `aload_3` used to
    /// push it as an int, which `ifnull` calls non-null, while `aload 3` read
    /// null.
    #[test]
    fn an_int_zero_reference_local_is_null_in_every_spelling() {
        let tail = [0xc6u8, 0x00, 0x05, 0x03, 0xac, 0x04, 0xac]; // ifnull +5; 0; 1
        let mut short = vec![0x2d]; // aload_3
        short.extend_from_slice(&tail);
        let mut wide = vec![0x19, 3]; // aload 3
        wide.extend_from_slice(&tail);
        for (name, code) in [("int0Short", short), ("int0Wide", wide)] {
            let r = run_with(name, "()I", code, 1, 4, |f| {
                f.set_local_compact(3, CompactValue::int(0));
            });
            assert!(
                matches!(r, Ok(Some(Value::Int(1)))),
                "{name}: expected null, got {r:?}"
            );
        }
        // iconst_0; astore_1 / astore 4; aload_1 / aload 4; ifnull
        let mut via_short = vec![0x03, 0x4c, 0x2b];
        via_short.extend_from_slice(&tail);
        let mut via_wide = vec![0x03, 0x3a, 4, 0x19, 4];
        via_wide.extend_from_slice(&tail);
        assert_eq!(int("int0StoreShort", via_short, 1, 5), 1);
        assert_eq!(int("int0StoreWide", via_wide, 1, 5), 1);
    }

    /// `newarray` on the raw-bytecode arm and on the decoded arm runs one
    /// body (`op_newarray`), and `athrow` of null fails the same way on both
    /// (`op_athrow`) — never with a normal return.
    #[test]
    fn newarray_and_athrow_share_one_body_on_both_paths() {
        // bipush 5; newarray int; arraylength; ireturn
        let code = vec![0x10, 5, 0xbc, 10, 0xbe, 0xac];
        assert_eq!(int("newarrayFast", code.clone(), 1, 0), 5);
        let decoded = ClassId::new(0x003F_F003);
        let shared = vetoed_vm(decoded, "newarrayDecoded", "()I");
        let r = run_on(
            &shared,
            decoded,
            "newarrayDecoded",
            "()I",
            code,
            1,
            0,
            |_| {},
        );
        assert!(matches!(r, Ok(Some(Value::Int(5)))), "decoded: {r:?}");
        // aconst_null; athrow
        let throw_null = vec![0x01, 0xbf];
        let fast = run_with("athrowNull", "()V", throw_null.clone(), 1, 0, |_| {});
        assert!(fast.is_err(), "athrow of null must not return: {fast:?}");
        // A second VM: in the old process-wide store this second veto for the
        // same class id was dropped (first writer wins), so this half of the
        // test ran on the fast path.
        let shared = vetoed_vm(decoded, "athrowDecoded", "()V");
        let slow = run_on(
            &shared,
            decoded,
            "athrowDecoded",
            "()V",
            throw_null,
            1,
            0,
            |_| {},
        );
        assert!(
            slow.is_err(),
            "decoded athrow of null must not return: {slow:?}"
        );
    }

    /// A JDWP breakpoint on the `if_icmpge` INSIDE javac's fusable loop test
    /// (`iload_2; iload_0; if_icmpge`) fires once per execution of that pc —
    /// eleven times for a ten-trip loop — because an armed breakpoint turns
    /// fusion off; and the loop's answer does not move.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn a_breakpoint_inside_a_fused_group_fires_every_time() {
        use crate::debug::events::{EventKind, EventModifier, SuspendPolicy};
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let cid = ClassId::new(0x00F1_0003);
        let method_id = crate::debug::jdwp_method_id("bpLoop", "()I");
        let _ = shared.debug.debug_state.lock().events.set_event_request(
            EventKind::Breakpoint,
            SuspendPolicy::None,
            vec![EventModifier::LocationOnly {
                class_id: u64::from(cid.as_u32()),
                method_id,
                offset: 9,
            }],
        );
        crate::debug::publish_debugger_gates(&shared, &shared.debug.debug_state.lock());
        let (tx, rx) = std::sync::mpsc::channel();
        *shared.debug.debug_event_tx.lock().unwrap() = Some(tx);
        let code = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        // Wave 7: the gate is per method — the same loop in a method with no
        // breakpoint runs without the suspend point and keeps its answer; the
        // breakpoint's own method still reports.
        assert!(!shared
            .debug
            .debugger_gates
            .concerns_method(cid.as_u32(), "bpLoopOther", "()I"));
        let r = run_on(
            &shared,
            cid,
            "bpLoopOther",
            "()I",
            code.clone(),
            2,
            3,
            |_| {},
        );
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "unconcerned: {r:?}");
        assert_eq!(rx.try_iter().count(), 0, "no event outside the method");
        let r = run_on(&shared, cid, "bpLoop", "()I", code, 2, 3, |_| {});
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "answer: {r:?}");
        let hits: Vec<_> = rx.try_iter().collect();
        assert_eq!(hits.len(), 11, "one event per execution of pc 9: {hits:?}");
        assert!(hits
            .iter()
            .all(|e| e.kind == EventKind::Breakpoint && e.offset == 9 && e.method_id == method_id));
    }

    // ── Interpreter round i1, wave 4 (lane L1) ──────────────────────────

    /// Run a caller (`areturn` at pc 0) over a callee (`aload_0; areturn`,
    /// local 0 = a reference to `addr`) in one dispatch loop, with a JVMTI
    /// `MethodExit` listener recording, per exit, whether the returned
    /// reference sat in a GC root while the callback ran: the parent's
    /// operand-stack top (a stackless return) or `native_pin_roots` (the
    /// outermost return, and the decoded `areturn`). Returns the records and
    /// the reference the loop returned. Runs on `shared` (see [`vetoed_vm`]).
    fn method_exit_root_census(
        shared: Arc<SharedVm>,
        callee_class: ClassId,
        callee: &str,
        addr: u64,
    ) -> (Vec<bool>, u64) {
        use crate::runtime::jvmti::{self, EventCallbacks, EventMode, JvmtiEventKind};
        let _lock = jvmti::jvmti_registry_test_lock();
        let vm = shared.vm_identity;
        jvmti::install_manager_for_vm(vm, Arc::new(jvmti::JvmtiEventManager::new_for_vm(vm)));
        let desc = "()Ljava/lang/Object;";
        let frame = |cid: ClassId, name: &str, code: Vec<u8>| {
            Frame::new(
                cid,
                "cratonvm/test/L1Dispatch".to_string(),
                name.to_string(),
                desc.to_string(),
                None,
                code,
                Vec::new(),
                1,
                1,
                &[],
            )
        };
        let mut thread = JvmThread::new(ThreadId(0), "l1-return-roots");
        thread
            .frames
            .push(frame(ClassId::new(0x00F1_0004), "rootCaller", vec![0xb0]));
        let mut callee_frame = frame(callee_class, callee, vec![0x2a, 0xb0]);
        callee_frame.set_local_compact(0, unrecorded_ref(addr));
        thread.frames.push(callee_frame);
        let records = Arc::new(std::sync::Mutex::new(Vec::new()));
        let seen = Arc::clone(&records);
        // Test-only: the callback reads the thread through its address. The
        // loop holds only shared borrows of it while `MethodExit` runs.
        let tp: *mut JvmThread = &mut thread;
        let tp_addr = tp as usize; // Cast: address carried into the callback
        let mgr = jvmti::manager_for_vm(vm).expect("row was just installed");
        mgr.set_event_notification_mode(EventMode::Enable, JvmtiEventKind::MethodExit, None)
            .expect("enable MethodExit");
        mgr.set_event_callbacks(EventCallbacks {
            method_exit: Some(Box::new(move |_, _, _, _| {
                // SAFETY: `tp_addr` is the live test thread; see above.
                let t = unsafe { &*(tp_addr as *const JvmThread) }; // Cast: see above
                let n = t.frames.len();
                let in_parent = n >= 2
                    && plain_ref_on_top(&t.frames[n - 2].stack)
                        .is_some_and(|r| r.as_ptr() as u64 == addr); // Cast: address compare
                let pinned = t.native_pin_roots.iter().any(|r| r.as_ptr() as u64 == addr); // Cast: address compare
                seen.lock().unwrap().push(in_parent || pinned);
            })),
            ..Default::default()
        })
        .expect("install callbacks");
        // SAFETY: `tp` is `&mut thread`; nothing else writes through it.
        let r = execute_frame_from_index(&shared, unsafe { &mut *tp }, 0);
        // The callback holds the thread's address: switch it off before the
        // thread goes out of scope.
        let _ =
            mgr.set_event_notification_mode(EventMode::Disable, JvmtiEventKind::MethodExit, None);
        jvmti::forget_vm_jvmti_state(vm);
        let got = returned_ref(callee, r);
        let recs = records.lock().unwrap().clone();
        (recs, got)
    }

    /// A returned reference is in a GC root while JVMTI `MethodExit` runs —
    /// on the fast path's stackless and outermost returns and on the decoded
    /// `areturn` — and still comes back intact. It used to live only in a
    /// Rust local across that callback (and across `FramePop` and the
    /// synchronized-monitor release), so a collection an agent triggered
    /// there left the caller holding a stale address.
    #[test]
    fn a_returned_reference_is_rooted_while_method_exit_runs() {
        let addr = 0x0000_5A5A_0006_0000;
        let plain = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let (recs, got) =
            method_exit_root_census(plain, ClassId::new(0x00F1_0005), "rootCallee", addr);
        assert_eq!(got, addr);
        assert_eq!(recs, vec![true, true], "callee exit, then caller exit");
        // The callee on the decoded path (its gate vetoed).
        let decoded = ClassId::new(0x003F_F004);
        let shared = vetoed_vm(decoded, "rootCalleeDecoded", "()Ljava/lang/Object;");
        let addr = 0x0000_5A5A_0007_0000;
        let (recs, got) = method_exit_root_census(shared, decoded, "rootCalleeDecoded", addr);
        assert_eq!(got, addr);
        assert_eq!(
            recs,
            vec![true, true],
            "decoded callee exit, then caller exit"
        );
    }

    /// `pop_root_frames_keeping_result` pops orphans and the root frame, and
    /// hands back a reference result unchanged (no `FramePop` listener: no
    /// pin taken, none leaked).
    #[test]
    fn popping_the_root_frames_keeps_the_result() {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let mut thread = JvmThread::new(ThreadId(0), "l1-root-pop");
        for name in ["base", "root", "orphan"] {
            thread.frames.push(Frame::new(
                ClassId::new(0x00F1_0006),
                "cratonvm/test/L1Dispatch".to_string(),
                name.to_string(),
                "()V".to_string(),
                None,
                vec![0xb1],
                Vec::new(),
                1,
                0,
                &[],
            ));
        }
        let addr = 0x0000_5A5A_0008_0000;
        let r = ref_local_object(unrecorded_ref(addr)).expect("a plausible reference");
        let mut result: MethodCallResult = Ok(Some(Value::Object(Some(r))));
        let pins = thread.native_pin_roots.len();
        pop_root_frames_keeping_result(&shared, &mut thread, 1, &mut result);
        assert_eq!(thread.frames.len(), 1, "the orphan and the root are popped");
        assert_eq!(thread.native_pin_roots.len(), pins, "no pin left behind");
        assert_eq!(returned_ref("rootPop", result), addr);
    }

    /// Wave 4 fusions keep the unfused answers: `iload_X; iload_Y; iadd;
    /// istore_Z` (into another local, and back into an operand), and
    /// `aload_N; arraylength` — whose null receiver must still throw from the
    /// `arraylength`, never return.
    #[test]
    fn wave4_fusions_keep_the_unfused_answers() {
        // bipush 3; istore_0; bipush 4; istore_1;
        // iload_0; iload_1; iadd; istore_2; iload_2; ireturn
        let code = vec![
            0x10, 3, 0x3b, 0x10, 4, 0x3c, 0x1a, 0x1b, 0x60, 0x3d, 0x1c, 0xac,
        ];
        assert_eq!(int("iaddIntoLocal", code, 2, 3), 7);
        // ... iload_0; iload_1; iadd; istore_0 (into an operand local)
        let code = vec![
            0x10, 3, 0x3b, 0x10, 4, 0x3c, 0x1a, 0x1b, 0x60, 0x3b, 0x1a, 0xac,
        ];
        assert_eq!(int("iaddIntoOperand", code, 2, 2), 7);
        // ... iload_0; iload_1; iadd; ireturn (no store: the sum is pushed)
        let code = vec![0x10, 3, 0x3b, 0x10, 4, 0x3c, 0x1a, 0x1b, 0x60, 0xac];
        assert_eq!(int("iaddPushed", code, 2, 2), 7);
        // bipush 5; newarray int; astore_1; aload_1; arraylength; ireturn
        let code = vec![0x10, 5, 0xbc, 10, 0x4c, 0x2b, 0xbe, 0xac];
        assert_eq!(int("aloadArraylength", code, 1, 2), 5);
        // aconst_null; astore_1; aload_1; arraylength; ireturn
        let code = vec![0x01, 0x4c, 0x2b, 0xbe, 0xac];
        let r = run_with("aloadArraylengthNull", "()I", code, 1, 2, |_| {});
        assert!(r.is_err(), "arraylength of null must throw: {r:?}");
    }

    /// The opcode-pair census counts a dispatch only as the fall-through
    /// successor of the previous one in the same activation: not across a
    /// frame switch, not after a taken branch.
    #[test]
    fn the_opcode_pair_census_counts_fall_through_pairs_only() {
        use cratonvm_reader::quickened::opcode_pair_census_top;
        let count = |a: u8, b: u8| {
            opcode_pair_census_top(256 * 256)
                .into_iter()
                .find(|r| r.0 == a && r.1 == b)
                .map_or(0, |r| r.2)
        };
        let code = [0u8; 4];
        let p = code.as_ptr();
        // monitorenter (1 byte) at pc 10, monitorexit at pc 11: a pair.
        let c = note_opcode_pair(OpcodePairCursor::NONE, 0, p, 10, 0xc2);
        let c = note_opcode_pair(c, 0, p, 11, 0xc3);
        // monitorexit then monitorenter, but in another frame: no pair.
        let c = note_opcode_pair(c, 1, p, 12, 0xc2);
        // ... and at a pc that is not the successor (a taken branch): none.
        let _ = note_opcode_pair(c, 1, p, 40, 0xc3);
        assert_eq!(count(0xc2, 0xc3), 1, "the one fall-through pair");
        assert_eq!(count(0xc3, 0xc2), 0, "a frame switch breaks the pair");
    }

    /// A `SUSPEND_EVENT_THREAD` breakpoint parks the thread before the
    /// bytecode runs, with its frames and locals published to the JDWP
    /// state, until the debugger resumes it; the bytecode then runs once and
    /// the method's answer is unchanged. A request on an overload with the
    /// same name and bytecode index does not match (method ids hash the
    /// descriptor).
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn a_suspending_breakpoint_parks_the_thread_until_resumed() {
        use crate::debug::events::{EventKind, EventModifier, SuspendPolicy};
        use std::time::{Duration, Instant};
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let cid = ClassId::new(0x00F1_0007);
        let method_id = crate::debug::jdwp_method_id("bpPark", "()I");
        let overload_id = crate::debug::jdwp_method_id("bpPark", "()J");
        assert_ne!(method_id, overload_id, "overloads have distinct ids");
        let at = |mid: u64| {
            vec![EventModifier::LocationOnly {
                class_id: u64::from(cid.as_u32()),
                method_id: mid,
                offset: 22,
            }]
        };
        let req = {
            let mut ds = shared.debug.debug_state.lock();
            let _ = ds.events.set_event_request(
                EventKind::Breakpoint,
                SuspendPolicy::None,
                at(overload_id),
            );
            ds.events.set_event_request(
                EventKind::Breakpoint,
                SuspendPolicy::EventThread,
                at(method_id),
            )
        };
        crate::debug::publish_debugger_gates(&shared, &shared.debug.debug_state.lock());
        let (tx, rx) = std::sync::mpsc::channel();
        *shared.debug.debug_event_tx.lock().unwrap() = Some(tx);
        let code = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        let (r, observed) = std::thread::scope(|s| {
            // The debugger: wait for the stop, read the published state,
            // resume. A missed stop still resumes at the deadline, so a
            // failure cannot hang the test.
            let resumer = s.spawn(|| {
                let deadline = Instant::now() + Duration::from_secs(30);
                loop {
                    {
                        let mut ds = shared.debug.debug_state.lock();
                        if ds.is_thread_suspended(0) {
                            let top = ds
                                .thread_frames
                                .get(&0)
                                .and_then(|f| f.first())
                                .map(|e| (e.frame_id, e.method_id, e.offset));
                            let sum = ds
                                .get_frame_locals(crate::debug::ids::ThreadId(0), 0)
                                .and_then(|l| l.get(1))
                                .and_then(|v| v.as_int());
                            ds.resume_thread(0);
                            return Some((top, sum));
                        }
                        if Instant::now() > deadline {
                            ds.resume_all();
                            return None;
                        }
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
            });
            let r = run_on(&shared, cid, "bpPark", "()I", code, 2, 3, |_| {});
            (r, resumer.join().expect("the resumer thread"))
        });
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "answer: {r:?}");
        assert_eq!(
            observed,
            Some((Some((0, method_id, 22)), Some(45))),
            "the thread stopped at pc 22 with s = 45 published"
        );
        let hits: Vec<_> = rx.try_iter().collect();
        assert_eq!(
            hits.len(),
            1,
            "one stop, and the resumed bytecode is not re-reported"
        );
        assert_eq!(hits[0].request_id, req);
        assert_eq!(hits[0].suspend_policy, SuspendPolicy::EventThread);
        assert!(
            shared.debug.debug_state.lock().thread_frames.is_empty(),
            "the snapshot is withdrawn on resume"
        );
    }

    /// Wave 8: the JDWP server's work (invocations, heap commands) runs on
    /// the thread parked at a suspend point (`debug::run_on_parked_thread`):
    /// on the thread named, above its parked frame, with the suspend point
    /// suppressed, able to allocate and export what it allocated; it is
    /// refused for a thread that is not parked. The parked frame is intact
    /// afterwards (the method's answer is unchanged) and the thread leaves
    /// the parked set when resumed.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn debugger_work_runs_on_the_parked_thread() {
        use crate::debug::events::{EventKind, EventModifier, SuspendPolicy};
        use crate::debug::ParkedError;
        use std::time::{Duration, Instant};
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let cid = ClassId::new(0x00F1_0009);
        let method_id = crate::debug::jdwp_method_id("bpWork", "()I");
        {
            let mut ds = shared.debug.debug_state.lock();
            let _ = ds.events.set_event_request(
                EventKind::Breakpoint,
                SuspendPolicy::EventThread,
                vec![EventModifier::LocationOnly {
                    class_id: u64::from(cid.as_u32()),
                    method_id,
                    offset: 22,
                }],
            );
        }
        crate::debug::publish_debugger_gates(&shared, &shared.debug.debug_state.lock());
        let code = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        let (r, observed) = std::thread::scope(|s| {
            // The debugger: wait for the park, hand the thread work, resume.
            // A missed park still resumes at the deadline.
            let debugger = s.spawn(|| {
                let deadline = Instant::now() + Duration::from_secs(30);
                loop {
                    if shared.debug.debug_state.lock().is_parked(0) {
                        break;
                    }
                    if Instant::now() > deadline {
                        shared.debug.debug_state.lock().resume_all();
                        return None;
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
                let not_parked = crate::debug::run_on_parked_thread(&shared, Some(7), |_, _| ());
                let seen =
                    crate::debug::run_on_parked_thread(&shared, Some(0), |shared, thread| {
                        let suppressed = crate::debug::debugger_hooks_suppressed();
                        let array = gc_alloc_array(
                            shared,
                            thread,
                            ClassId::new(0),
                            crate::memory::heap::ArrayElementType::Int,
                            8,
                        )
                        .ok();
                        let id = array.map(|a| {
                            let mut ds = shared.debug.debug_state.lock();
                            crate::debug::export_object(
                                shared,
                                &mut ds,
                                a,
                                crate::debug::ids::ObjectExport::Sent,
                            )
                        });
                        (thread.thread_id.0, thread.frames.len(), suppressed, id)
                    });
                let any = crate::debug::run_on_parked_thread(&shared, None, |_, thread| {
                    thread.thread_id.0
                });
                shared.debug.debug_state.lock().resume_thread(0);
                Some((not_parked.err(), seen.ok(), any.ok()))
            });
            let r = run_on(&shared, cid, "bpWork", "()I", code, 2, 3, |_| {});
            (r, debugger.join().expect("the debugger thread"))
        });
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "answer: {r:?}");
        let Some((not_parked, seen, any)) = observed else {
            panic!("the thread never parked");
        };
        assert_eq!(not_parked, Some(ParkedError::NotParked));
        let Some((tid, depth, suppressed, id)) = seen else {
            panic!("the parked thread never answered");
        };
        assert_eq!(
            (tid, depth),
            (0, 1),
            "on the parked thread, above its frame"
        );
        assert!(suppressed, "no suspend point inside the debugger's work");
        if let Some(id) = id {
            let ds = shared.debug.debug_state.lock();
            assert!(
                crate::debug::object_for_id(&shared, &ds, id).is_some(),
                "what the parked thread allocated and exported resolves"
            );
        }
        assert_eq!(any, Some(0), "any parked thread");
        assert!(
            !shared.debug.debug_state.lock().is_parked(0),
            "left on resume"
        );
        assert!(!crate::debug::debugger_hooks_suppressed());
    }

    /// Wave 9: a breakpoint inside a debugger invocation is reported and
    /// stops the invoking thread again (it used to be dropped). The thread,
    /// parked at a breakpoint in `bpOuter`, is asked to run `bpInner`, which
    /// holds a `SUSPEND_EVENT_THREAD` breakpoint: the event follows the outer
    /// one, the published stack grows by `bpInner`'s frame, a resume lets it
    /// return, and the invocation answers with the thread suspended again
    /// and the outer stop's frames published — before the answer, so a
    /// debugger acting on it finds them.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn a_breakpoint_inside_a_debugger_invocation_stops_the_thread() {
        use crate::debug::events::{EventKind, EventModifier, SuspendPolicy};
        use std::time::{Duration, Instant};
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let sh: &SharedVm = &shared;
        let cid = ClassId::new(0x00F1_000B);
        let outer_id = crate::debug::jdwp_method_id("bpOuter", "()I");
        let inner_id = crate::debug::jdwp_method_id("bpInner", "()I");
        {
            let mut ds = sh.debug.debug_state.lock();
            for (method_id, offset) in [(outer_id, 22u64), (inner_id, 2u64)] {
                let _ = ds.events.set_event_request(
                    EventKind::Breakpoint,
                    SuspendPolicy::EventThread,
                    vec![EventModifier::LocationOnly {
                        class_id: u64::from(cid.as_u32()),
                        method_id,
                        offset,
                    }],
                );
            }
        }
        crate::debug::publish_debugger_gates(sh, &sh.debug.debug_state.lock());
        let (tx, rx) = std::sync::mpsc::channel();
        *sh.debug.debug_event_tx.lock().unwrap() = Some(tx);
        let outer = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        // bpInner: bipush 7; iconst_2; imul; ireturn. The breakpoint is on
        // the iconst_2 (pc 2).
        let inner = vec![0x10, 7, 0x05, 0x68, 0xac];
        // Thread 0 as the debugger sees it: suspended, and its published
        // frame count and top location.
        let top = |sh: &SharedVm| {
            let ds = sh.debug.debug_state.lock();
            (
                ds.is_thread_suspended(0),
                ds.thread_frames
                    .get(&0)
                    .map(|f| (f.len(), f.first().map(|e| (e.method_id, e.offset)))),
            )
        };
        let (r, (invoked, nested)) = std::thread::scope(|s| {
            // Waits for the outer stop and invokes `bpInner` on the thread.
            let debugger = s.spawn(move || {
                let deadline = Instant::now() + Duration::from_secs(30);
                while top(sh) != (true, Some((1, Some((outer_id, 22))))) {
                    if Instant::now() > deadline {
                        sh.debug.debug_state.lock().resume_all();
                        return None;
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
                let answer = crate::debug::run_invocation_on_parked_thread(
                    sh,
                    0,
                    false,
                    move |sh, thread| {
                        let frame = Frame::new(
                            cid,
                            "cratonvm/test/L1Dispatch".to_string(),
                            "bpInner".to_string(),
                            "()I".to_string(),
                            None,
                            inner,
                            Vec::new(),
                            2,
                            0,
                            &[],
                        );
                        match execute_prebuilt_frame(sh, thread, frame) {
                            Ok(Some(Value::Int(v))) => Some(v),
                            _ => None,
                        }
                    },
                );
                let after = top(sh);
                sh.debug.debug_state.lock().resume_thread(0);
                Some((answer, after))
            });
            // Waits for the stop inside the invocation and resumes it.
            let resumer = s.spawn(move || {
                let deadline = Instant::now() + Duration::from_secs(30);
                loop {
                    let now = top(sh);
                    if now.0 && matches!(now.1, Some((2, Some((m, 2)))) if m == inner_id) {
                        sh.debug.debug_state.lock().resume_thread(0);
                        return Some(now);
                    }
                    if Instant::now() > deadline {
                        sh.debug.debug_state.lock().resume_all();
                        return None;
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
            });
            let r = run_on(sh, cid, "bpOuter", "()I", outer, 2, 3, |_| {});
            let invoked = debugger.join().expect("the debugger thread");
            let nested = resumer.join().expect("the resumer thread");
            (r, (invoked, nested))
        });
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "answer: {r:?}");
        assert_eq!(
            nested,
            Some((true, Some((2, Some((inner_id, 2)))))),
            "stopped inside the invocation, its frame on top"
        );
        assert_eq!(
            invoked,
            Some((Ok(Some(14)), (true, Some((1, Some((outer_id, 22))))))),
            "the invocation answered; suspended again at the outer stop"
        );
        let hits: Vec<_> = rx
            .try_iter()
            .map(|e| (e.method_id, e.offset, e.suspend_policy))
            .collect();
        assert_eq!(
            hits,
            vec![
                (outer_id, 22, SuspendPolicy::EventThread),
                (inner_id, 2, SuspendPolicy::EventThread),
            ]
        );
        assert!(sh.debug.debug_state.lock().thread_frames.is_empty());
    }

    /// Wave 9: `StackFrame.SetValues` writes a parked frame's local on its
    /// own thread (it answered `NOT_IMPLEMENTED`; before wave 8, success
    /// without a write): the summing loop, stopped before `iload_1; ireturn`,
    /// returns the value the debugger set, and `GetValues` reads it back
    /// first. Every check comes before any write: an unknown thread, a frame
    /// id the snapshot does not have, a slot out of range, a kind the slot
    /// does not hold, and — with a `LocalVariableTable` entry — the
    /// variable's declared kind.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn stack_frame_set_values_writes_the_parked_frame() {
        use crate::debug::commands::{
            CMD_SF_GET_VALUES, CMD_SF_SET_VALUES, CS_STACK_FRAME, ERR_INVALID_FRAMEID,
            ERR_INVALID_SLOT, ERR_INVALID_THREAD, ERR_TYPE_MISMATCH,
        };
        use crate::debug::events::{EventKind, EventModifier, SuspendPolicy};
        use crate::debug::inspect::run_heap_command;
        use crate::debug::protocol::PayloadWriter;
        use std::time::{Duration, Instant};
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let sh: &SharedVm = &shared;
        let cid = ClassId::new(0x00F1_000C);
        let method_id = crate::debug::jdwp_method_id("bpSet", "()I");
        {
            let mut ds = sh.debug.debug_state.lock();
            let _ = ds.events.set_event_request(
                EventKind::Breakpoint,
                SuspendPolicy::EventThread,
                vec![EventModifier::LocationOnly {
                    class_id: u64::from(cid.as_u32()),
                    method_id,
                    offset: 22,
                }],
            );
            // `i` (slot 2) declared a reference: the table's kind wins over
            // the int the slot holds. `s` (slot 1) is declared too
            // (interpreter round i4 wave 85, lane L1): a method with a table
            // answers `INVALID_SLOT` for a slot no entry covers, in
            // `GetValues` since wave 42 (`commands::local_read_refusal`, as
            // HotSpot's `check_slot_type_lvt`), so the read-back below
            // needs the entry.
            ds.method_variables.insert(
                (u64::from(cid.as_u32()), method_id),
                vec![
                    crate::debug::VariableInfo {
                        code_index: 0,
                        name: "s".to_string(),
                        signature: "I".to_string(),
                        length: 24,
                        slot: 1,
                    },
                    crate::debug::VariableInfo {
                        code_index: 0,
                        name: "i".to_string(),
                        signature: "Ljava/lang/Object;".to_string(),
                        length: 24,
                        slot: 2,
                    },
                ],
            );
        }
        crate::debug::publish_debugger_gates(sh, &sh.debug.debug_state.lock());
        let code = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        let set = |thread: u64, frame: u64, slot: u32, tagged: &[u8]| {
            let mut pw = PayloadWriter::new();
            pw.put_u64_be(thread);
            pw.put_u64_be(frame);
            pw.put_u32_be(1);
            pw.put_u32_be(slot);
            pw.put_bytes(tagged);
            run_heap_command(sh, CS_STACK_FRAME, CMD_SF_SET_VALUES, &pw.into_bytes()).error_code
        };
        let int = |v: i32| {
            let mut t = vec![b'I'];
            t.extend_from_slice(&v.to_be_bytes());
            t
        };
        let long_one = [b'J', 0, 0, 0, 0, 0, 0, 0, 1];
        let (r, observed) = std::thread::scope(|s| {
            let debugger = s.spawn(move || {
                let deadline = Instant::now() + Duration::from_secs(30);
                while !sh.debug.debug_state.lock().is_parked(0) {
                    if Instant::now() > deadline {
                        sh.debug.debug_state.lock().resume_all();
                        return None;
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
                let codes = [
                    set(7, 0, 1, &int(100)),
                    set(0, 5, 1, &int(100)),
                    set(0, 0, 9, &int(100)),
                    set(0, 0, 1, &long_one),
                    set(0, 0, 2, &int(3)),
                    set(0, 0, 1, &int(100)),
                ];
                let mut get = PayloadWriter::new();
                get.put_u64_be(0);
                get.put_u64_be(0);
                get.put_u32_be(1);
                get.put_u32_be(1);
                get.put_u8(b'I');
                let read =
                    run_heap_command(sh, CS_STACK_FRAME, CMD_SF_GET_VALUES, &get.into_bytes());
                sh.debug.debug_state.lock().resume_thread(0);
                Some((codes, read.data))
            });
            let r = run_on(sh, cid, "bpSet", "()I", code, 2, 3, |_| {});
            (r, debugger.join().expect("the debugger thread"))
        });
        assert!(
            matches!(r, Ok(Some(Value::Int(100)))),
            "the method returns the value the debugger set: {r:?}"
        );
        let Some((codes, read)) = observed else {
            panic!("the thread never parked");
        };
        assert_eq!(
            codes,
            [
                ERR_INVALID_THREAD,
                ERR_INVALID_FRAMEID,
                ERR_INVALID_SLOT,
                ERR_TYPE_MISMATCH,
                ERR_TYPE_MISMATCH,
                0,
            ]
        );
        assert_eq!(
            read,
            vec![0, 0, 0, 1, b'I', 0, 0, 0, 100],
            "GetValues sees it"
        );
        assert!(sh.debug.debug_state.lock().thread_frames.is_empty());
    }

    /// Wave 8: the OSR and first-call gates stand down for a method the JDWP
    /// requests concern, not for every method while any breakpoint is set.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn the_osr_and_first_call_gates_stand_down_per_method() {
        use crate::debug::events::{EventKind, EventModifier, SuspendPolicy};
        let shared = SharedVm::new(crate::config::VmConfig::default());
        if crate::runtime::jvmti::interp_only_events_active_for_vm(shared.vm_identity) {
            return; // a JVMTI listener already keeps everything interpreted
        }
        let cid = ClassId::new(0x00F1_000A);
        assert!(!jvmti_requires_interpreter_for_method(
            &shared, cid, "hot", "()V"
        ));
        let mut ds = crate::debug::DebugState::new();
        let _ = ds.events.set_event_request(
            EventKind::Breakpoint,
            SuspendPolicy::None,
            vec![EventModifier::LocationOnly {
                class_id: u64::from(cid.as_u32()),
                method_id: crate::debug::jdwp_method_id("hot", "()V"),
                offset: 0,
            }],
        );
        crate::debug::publish_debugger_gates(&shared, &ds);
        assert!(jvmti_requires_interpreter_for_method(
            &shared, cid, "hot", "()V"
        ));
        assert!(!jvmti_requires_interpreter_for_method(
            &shared, cid, "cold", "()V"
        ));
        ds.suspend_all();
        crate::debug::publish_debugger_gates(&shared, &ds);
        assert!(
            jvmti_requires_interpreter_for_method(&shared, cid, "cold", "()V"),
            "a suspension concerns every method"
        );
    }

    // ── Interpreter round i1, wave 5 (lane L1) ──────────────────────────

    /// Every raw-bytecode arm's error goes through
    /// `classify_fastpath_invoke_error`, which settles a thrown exception the
    /// way the decoded path does: `native_pending_return` is drained, a live
    /// thrown object wins, and the rooted copy stands in only when the thrown
    /// address is no longer an object. A `RuntimeError` is converted (and
    /// settled) at the loop top, so the classifier leaves the slot alone.
    #[test]
    fn the_fast_path_classifier_settles_every_thrown_exception() {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let mut thread = JvmThread::new(ThreadId(0), "l1-settle");
        let thrown = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        let leftover = shared.mem.heap.alloc_object(ClassId::new(0), 0);
        // Cast: address probe
        if shared
            .mem
            .heap
            .is_object_address(thrown.as_ptr() as usize)
            .is_none()
        {
            return; // a backend that cannot answer the liveness probe
        }
        thread.native_pending_return = Some(leftover);
        let live = classify_fastpath_invoke_error(
            &shared,
            &mut thread,
            MethodCallFailed::ExceptionThrown(thrown),
        );
        assert!(
            matches!(live, FastPathInvokeError::Java(e) if e.as_ptr() == thrown.as_ptr()),
            "a live throwable is the one routed"
        );
        assert!(
            thread.native_pending_return.is_none(),
            "the leftover is drained"
        );
        let stale =
            ref_local_object(unrecorded_ref(0x0000_5A5A_0009_0000)).expect("a plausible reference");
        thread.native_pending_return = Some(leftover);
        let moved = classify_fastpath_invoke_error(
            &shared,
            &mut thread,
            MethodCallFailed::ExceptionThrown(stale),
        );
        assert!(
            matches!(moved, FastPathInvokeError::Java(e) if e.as_ptr() == leftover.as_ptr()),
            "a thrown address that is no object falls back to the rooted copy"
        );
        assert!(thread.native_pending_return.is_none());
        thread.native_pending_return = Some(leftover);
        let runtime = classify_fastpath_invoke_error(
            &shared,
            &mut thread,
            MethodCallFailed::InternalError(VmError::Runtime(RuntimeError::StackOverflowError)),
        );
        assert!(matches!(runtime, FastPathInvokeError::Runtime(_)));
        assert_eq!(
            thread.native_pending_return.map(|r| r.as_ptr()),
            Some(leftover.as_ptr()),
            "the loop top settles a runtime error once it is a throwable"
        );
    }

    /// End to end: a `RuntimeError` a fast-path arm raises (`newarray` of a
    /// negative size) is thrown from the loop top with `native_pending_return`
    /// drained, as the decoded path's conversion drains it. It used to be left
    /// rooted past the throw.
    #[test]
    fn a_fast_path_runtime_throw_drains_native_pending_return() {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let mut thread = JvmThread::new(ThreadId(0), "l1-drain");
        if crate::runtime::exceptions::create_exception_object(
            &shared,
            &mut thread,
            "java/lang/NegativeArraySizeException",
            None,
        )
        .is_err()
        {
            return; // stripped VM: the throwable cannot be built
        }
        thread.native_pending_return = Some(shared.mem.heap.alloc_object(ClassId::new(0), 0));
        // iconst_m1; newarray int; arraylength; ireturn
        let frame = Frame::new(
            ClassId::new(0x00F1_0008),
            "cratonvm/test/L1Dispatch".to_string(),
            "negativeArray".to_string(),
            "()I".to_string(),
            None,
            vec![0x02, 0xbc, 10, 0xbe, 0xac],
            Vec::new(),
            1,
            0,
            &[],
        );
        let r = execute_prebuilt_frame(&shared, &mut thread, frame);
        assert!(
            matches!(r, Err(MethodCallFailed::ExceptionThrown(_))),
            "NegativeArraySizeException expected: {r:?}"
        );
        assert!(
            thread.native_pending_return.is_none(),
            "the throw drained the leftover"
        );
    }

    /// javac's array-loop test `iload i; aload a; arraylength; if_icmp<cond>`
    /// fuses as a compare-and-branch whose second operand is the array's
    /// length, for every condition and in the `iload n` / `aload n`
    /// spellings, and answers what the unfused bytecodes answer.
    #[test]
    fn array_length_compare_and_branch_fuses_for_every_condition() {
        let ops: [(u8, fn(i32, i32) -> bool); 6] = [
            (0x9f, |a: i32, b: i32| a == b),
            (0xa0, |a: i32, b: i32| a != b),
            (0xa1, |a: i32, b: i32| a < b),
            (0xa2, |a: i32, b: i32| a >= b),
            (0xa3, |a: i32, b: i32| a > b),
            (0xa4, |a: i32, b: i32| a <= b),
        ];
        for (op, pred) in ops {
            for len in [0u8, 3, 7] {
                for i in [-1i8, 0, 3, 7, 9] {
                    let want = pred(i32::from(i), i32::from(len)) as i32;
                    let ib = i as u8; // Cast: test operand bytes
                                      // bipush len; newarray int; astore_1; bipush i; istore_0
                    let p = [0x10, len, 0xbc, 10, 0x4c, 0x10, ib, 0x3b];
                    let got = branch_answer("iloadAloadLength", &p, &[0x1a, 0x2b, 0xbe], op, 2);
                    assert_eq!(got, want, "short op=0x{op:x} i={i} len={len}");
                    // bipush len; newarray int; astore 5; bipush i; istore 4
                    let p = [0x10, len, 0xbc, 10, 0x3a, 5, 0x10, ib, 0x36, 4];
                    let g = [0x15, 4, 0x19, 5, 0xbe];
                    let got = branch_answer("iloadNAloadNLength", &p, &g, op, 6);
                    assert_eq!(got, want, "wide op=0x{op:x} i={i} len={len}");
                }
            }
        }
    }

    /// javac's `for (int i = 0; i < a.length; i++) s += i;`, over low and
    /// high locals, fuses its length test and keeps its answer; the
    /// `aload n; arraylength` pair fuses too; and a null array still throws
    /// from the `arraylength` — never a branch, never a return.
    #[test]
    fn javac_array_loops_fuse_their_length_test() {
        let low = vec![
            0x10, 10, 0xbc, 10, 0x4b, // 0: bipush 10; newarray int; astore_0
            0x03, 0x3c, // 5: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 7: iconst_0; istore_2           i = 0
            0x1c, 0x2a, 0xbe, 0xa2, 0x00,
            13, // 9: iload_2; aload_0; arraylength; if_icmpge +13
            0x1b, 0x1c, 0x60, 0x3c, // 15: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 19: iinc 2 1
            0xa7, 0xff, 0xf3, // 22: goto -13 (-> 9)
            0x1b, 0xac, // 25: iload_1; ireturn
        ];
        assert_eq!(int("arrayLoopLowLocals", low, 2, 3), 45);
        let high = vec![
            0x10, 10, 0xbc, 10, 0x3a, 4, // 0: bipush 10; newarray int; astore 4
            0x03, 0x36, 6, // 6: iconst_0; istore 6          s = 0
            0x03, 0x36, 5, // 9: iconst_0; istore 5          i = 0
            0x15, 5, 0x19, 4, 0xbe, 0xa2, 0x00,
            16, // 12: iload 5; aload 4; arraylength; if_icmpge +16
            0x15, 6, 0x15, 5, 0x60, 0x36, 6, // 20: iload 6; iload 5; iadd; istore 6
            0x84, 5, 1, // 27: iinc 5 1
            0xa7, 0xff, 0xee, // 30: goto -18 (-> 12)
            0x15, 6, 0xac, // 33: iload 6; ireturn
        ];
        assert_eq!(int("arrayLoopHighLocals", high, 2, 7), 45);
        // bipush 7; newarray int; astore 4; aload 4; arraylength; ireturn
        let pair = vec![0x10, 7, 0xbc, 10, 0x3a, 4, 0x19, 4, 0xbe, 0xac];
        assert_eq!(int("aloadNArraylength", pair, 1, 5), 7);
        let nulls: [(&str, Vec<u8>, u16); 3] = [
            // iconst_0; istore_0; aconst_null; astore_1;
            // iload_0; aload_1; arraylength; if_icmpge +5; 0; 1
            (
                "nullLengthLow",
                vec![
                    0x03, 0x3b, 0x01, 0x4c, 0x1a, 0x2b, 0xbe, 0xa2, 0, 5, 0x03, 0xac, 0x04, 0xac,
                ],
                2,
            ),
            // the same over locals 4 and 5
            (
                "nullLengthHigh",
                vec![
                    0x03, 0x36, 4, 0x01, 0x3a, 5, 0x15, 4, 0x19, 5, 0xbe, 0xa2, 0, 5, 0x03, 0xac,
                    0x04, 0xac,
                ],
                6,
            ),
            // aconst_null; astore 4; aload 4; arraylength; ireturn
            ("nullPairHigh", vec![0x01, 0x3a, 4, 0x19, 4, 0xbe, 0xac], 5),
        ];
        for (name, code, locals) in nulls {
            let r = run_with(name, "()I", code, 2, locals, |_| {});
            assert!(r.is_err(), "{name}: arraylength of null must throw: {r:?}");
        }
        // The local reader declines every non-array shape.
        assert_eq!(
            field_fast::arraylength_of_local(CompactValue::null(), false),
            None
        );
        assert_eq!(
            field_fast::arraylength_of_local(CompactValue::int(5), false),
            None
        );
    }

    /// Wave 24 (L7): `aload_N; iload_M; <x>aload` (javac's `a[i]`) fuses and
    /// keeps the unfused answers -- an int loop sum, a long element -- and a
    /// null array, an out-of-range and a negative index still throw from the
    /// `*aload` (the fused group declines and pushes nothing).
    #[test]
    fn array_element_reads_fuse_and_keep_their_answers() {
        let sum = vec![
            0x10, 10, 0xbc, 10, 0x4b, // 0: bipush 10; newarray int; astore_0
            0x03, 0x3d, // 5: iconst_0; istore_2               i = 0
            0x1c, 0x2a, 0xbe, 0xa2, 0x00,
            13, // 7: iload_2; aload_0; arraylength; if_icmpge 23
            0x2a, 0x1c, 0x1c, 0x4f, // 13: aload_0; iload_2; iload_2; iastore   a[i] = i
            0x84, 2, 1, // 17: iinc 2 1
            0xa7, 0xff, 0xf3, // 20: goto 7
            0x03, 0x3c, // 23: iconst_0; istore_1              s = 0
            0x03, 0x3d, // 25: iconst_0; istore_2              i = 0
            0x1c, 0x2a, 0xbe, 0xa2, 0x00,
            15, // 27: iload_2; aload_0; arraylength; if_icmpge 45
            0x1b, 0x2a, 0x1c, 0x2e, 0x60,
            0x3c, // 33: iload_1; aload_0; iload_2; iaload; iadd; istore_1
            0x84, 2, 1, // 39: iinc 2 1
            0xa7, 0xff, 0xf1, // 42: goto 27
            0x1b, 0xac, // 45: iload_1; ireturn
        ];
        assert_eq!(int("fusedIntElementSum", sum, 4, 3), 45);
        // iconst_2; newarray long; astore_0; aload_0; iconst_1; lconst_1;
        // lastore; iconst_1; istore_1; aload_0; iload_1; laload; lreturn
        let long_elem = vec![
            0x05, 0xbc, 11, 0x4b, 0x2a, 0x04, 0x0a, 0x50, 0x04, 0x3c, 0x2a, 0x1b, 0x2f, 0xad,
        ];
        match run_with("fusedLongElement", "()J", long_elem, 5, 2, |_| {}) {
            Ok(Some(Value::Long(v))) => assert_eq!(v, 1),
            other => panic!("fusedLongElement: expected 1L, got {other:?}"),
        }
        let throwing: [(&str, Vec<u8>); 3] = [
            // aconst_null; astore_0; iconst_0; istore_1; aload_0; iload_1; iaload; ireturn
            (
                "nullArray",
                vec![0x01, 0x4b, 0x03, 0x3c, 0x2a, 0x1b, 0x2e, 0xac],
            ),
            // iconst_1; newarray int; astore_0; iconst_5; istore_1; aload_0; iload_1; iaload; ireturn
            (
                "indexTooLarge",
                vec![0x04, 0xbc, 10, 0x4b, 0x08, 0x3c, 0x2a, 0x1b, 0x2e, 0xac],
            ),
            // iconst_1; newarray int; astore_0; iconst_m1; istore_1; aload_0; iload_1; iaload; ireturn
            (
                "negativeIndex",
                vec![0x04, 0xbc, 10, 0x4b, 0x02, 0x3c, 0x2a, 0x1b, 0x2e, 0xac],
            ),
        ];
        for (name, code) in throwing {
            let r = run_with(name, "()I", code, 2, 2, |_| {});
            assert!(r.is_err(), "{name}: the iaload must throw: {r:?}");
        }
    }

    /// Wave 25 (L7): `iload{_N, n}; <x>aload` with the array already on the
    /// operand stack (the inner dimension of `m[i][k]`, `this.a[i]`) fuses and
    /// keeps the unfused answers; a null array, a negative and an
    /// out-of-range index still throw from the `*aload`.
    #[test]
    fn stacked_array_element_reads_fuse_and_keep_their_answers() {
        // bipush 10; newarray int; astore_0; aload_0; iconst_3; bipush 42;
        // iastore; iconst_3; istore_1; aload_0; dup; pop; iload_1; iaload;
        // ireturn -- `dup; pop` keeps the wave-24 `aload_N; iload_M` group
        // from matching, so the array reaches the `iload_1` on the stack.
        let short_index = vec![
            0x10, 10, 0xbc, 10, 0x4b, 0x2a, 0x06, 0x10, 42, 0x4f, 0x06, 0x3c, 0x2a, 0x59, 0x57,
            0x1b, 0x2e, 0xac,
        ];
        assert_eq!(int("stackedShortIndex", short_index, 4, 2), 42);
        // ... the same with the index in local 4: `iconst_3; istore 4;
        // aload_0; iload 4; iaload; ireturn`.
        let wide_index = vec![
            0x10, 10, 0xbc, 10, 0x4b, 0x2a, 0x06, 0x10, 42, 0x4f, 0x06, 0x36, 4, 0x2a, 0x15, 4,
            0x2e, 0xac,
        ];
        assert_eq!(int("stackedWideIndex", wide_index, 4, 5), 42);
        // iconst_2; newarray long; astore_0; aload_0; iconst_1; lconst_1;
        // lastore; iconst_1; istore_1; aload_0; dup; pop; iload_1; laload; lreturn
        let long_elem = vec![
            0x05, 0xbc, 11, 0x4b, 0x2a, 0x04, 0x0a, 0x50, 0x04, 0x3c, 0x2a, 0x59, 0x57, 0x1b, 0x2f,
            0xad,
        ];
        match run_with("stackedLongElement", "()J", long_elem, 5, 2, |_| {}) {
            Ok(Some(Value::Long(v))) => assert_eq!(v, 1),
            other => panic!("stackedLongElement: expected 1L, got {other:?}"),
        }
        let throwing: [(&str, Vec<u8>); 3] = [
            // aconst_null; iconst_0; istore_1; iload_1; iaload; ireturn
            ("stackedNull", vec![0x01, 0x03, 0x3c, 0x1b, 0x2e, 0xac]),
            // bipush 10; newarray int; iconst_m1; istore 4; iload 4; iaload; ireturn
            (
                "stackedNegative",
                vec![0x10, 10, 0xbc, 10, 0x02, 0x36, 4, 0x15, 4, 0x2e, 0xac],
            ),
            // iconst_1; newarray int; iconst_5; istore_1; iload_1; iaload; ireturn
            (
                "stackedTooLarge",
                vec![0x04, 0xbc, 10, 0x08, 0x3c, 0x1b, 0x2e, 0xac],
            ),
        ];
        for (name, code) in throwing {
            let r = run_with(name, "()I", code, 3, 5, |_| {});
            assert!(r.is_err(), "{name}: the iaload must throw: {r:?}");
        }
    }

    /// The suspend point delivers JDWP single steps (one `SingleStep` per
    /// bytecode for a MIN step, even inside a fusable group) and applies the
    /// request modifiers: a breakpoint with `Count(4)` reports only its
    /// fourth hit, and one restricted to another thread never reports.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn single_steps_and_breakpoint_modifiers_are_delivered() {
        use crate::debug::events::{EventKind, EventModifier, StepDepth, StepSize, SuspendPolicy};
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let cid = ClassId::new(0x00F1_0009);
        let method_id = crate::debug::jdwp_method_id("stepLoop", "()I");
        let at_9 = EventModifier::LocationOnly {
            class_id: u64::from(cid.as_u32()),
            method_id,
            offset: 9,
        };
        let (counted, _other_thread) = {
            let mut ds = shared.debug.debug_state.lock();
            let counted = ds.events.set_event_request(
                EventKind::Breakpoint,
                SuspendPolicy::None,
                vec![at_9.clone(), EventModifier::Count(4)],
            );
            let other = ds.events.set_event_request(
                EventKind::Breakpoint,
                SuspendPolicy::None,
                vec![at_9, EventModifier::ThreadOnly { thread_id: 77 }],
            );
            (counted, other)
        };
        crate::debug::publish_debugger_gates(&shared, &shared.debug.debug_state.lock());
        let (tx, rx) = std::sync::mpsc::channel();
        *shared.debug.debug_event_tx.lock().unwrap() = Some(tx);
        // The ten-trip javac loop of `a_breakpoint_inside_a_fused_group_fires_every_time`.
        let code = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        let r = run_on(&shared, cid, "stepLoop", "()I", code.clone(), 2, 3, |_| {});
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "answer: {r:?}");
        let hits: Vec<_> = rx.try_iter().collect();
        assert_eq!(hits.len(), 1, "Count(4) reports once: {hits:?}");
        assert_eq!(hits[0].request_id, counted);

        // A MIN step request on this thread: one event per executed bytecode.
        {
            let mut ds = shared.debug.debug_state.lock();
            ds.events.clear_all();
            ds.events.set_event_request(
                EventKind::SingleStep,
                SuspendPolicy::None,
                vec![EventModifier::Step {
                    thread_id: 0,
                    size: StepSize::Min,
                    depth: StepDepth::Into,
                }],
            );
            // A step concerns every method (wave 7), `stepStraight` included.
            crate::debug::publish_debugger_gates(&shared, &ds);
        }
        // iconst_1; iconst_2; iadd; ireturn
        let straight = vec![0x04, 0x05, 0x60, 0xac];
        let r = run_on(&shared, cid, "stepStraight", "()I", straight, 2, 0, |_| {});
        assert!(matches!(r, Ok(Some(Value::Int(3)))), "answer: {r:?}");
        let steps: Vec<u64> = rx
            .try_iter()
            .filter(|e| e.kind == EventKind::SingleStep)
            .map(|e| e.offset)
            .collect();
        assert_eq!(steps, vec![0, 1, 2, 3], "one step per bytecode");
        // The ten-trip loop steps through every bytecode it executes, the
        // fusable groups included (fusion is off while stepping): 6 set-up
        // bytecodes, 9 per trip, then the exiting test (3) and the return (2).
        let r = run_on(&shared, cid, "stepLoop", "()I", code, 2, 3, |_| {});
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "answer: {r:?}");
        let loop_steps = rx
            .try_iter()
            .filter(|e| e.kind == EventKind::SingleStep)
            .count();
        assert_eq!(loop_steps, 6 + 9 * 10 + 3 + 2, "bytecodes executed");
    }

    // ── Interpreter round i1, wave 7 (lane L1) ──────────────────────────

    /// A map-less method's operand-stack depth is proven (and memoized) in
    /// the admission walk when it fits `max_stack`; one that declares too
    /// small a `max_stack` is still admitted (its locals fit) but not proven,
    /// and a method whose code names a member it cannot resolve is not proven
    /// either.
    #[test]
    fn map_less_stack_depth_is_proven_in_the_admission_walk() {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        // Beyond the type-map store's addressable ids: no maps, no class.
        let cid = ClassId::new(0x00F1_000A);
        let frame = |name: &str, code: Vec<u8>, max_stack: u16| {
            Frame::new(
                cid,
                "cratonvm/test/L1Dispatch".to_string(),
                name.to_string(),
                "()I".to_string(),
                None,
                code,
                Vec::new(),
                max_stack,
                1,
                &[],
            )
        };
        // iconst_1; iconst_2; iadd; ireturn — two words deep.
        let sum = vec![0x04, 0x05, 0x60, 0xac];
        let fits = frame("stackFits", sum.clone(), 2);
        assert!(frame_fast_path_admitted(&shared, &fits));
        assert!(frame_stack_depth_proven(&shared, &fits));
        assert!(frame_stack_depth_proven(&shared, &fits), "memoized");
        let short = frame("stackShort", sum, 1);
        assert!(frame_fast_path_admitted(&shared, &short), "locals fit");
        assert!(!frame_stack_depth_proven(&shared, &short));
        // getstatic #1 of a class the store does not have; ireturn.
        let member = frame("stackMember", vec![0xb2, 0, 1, 0xac], 4);
        assert!(frame_fast_path_admitted(&shared, &member));
        assert!(!frame_stack_depth_proven(&shared, &member));
    }
}

/// Interpreter round i1 wave 11, lane L1: the JVMTI `Exception` event, posted
/// by the unwinder in both feature states (it had no producer).
#[cfg(test)]
mod i1w11_l1_jvmti_exception_tests {
    use super::*;
    use crate::runtime::jvmti::{self, EventCallbacks, EventMode, JvmtiEventKind};
    use crate::threading::jvm_thread::ThreadId;
    use cratonvm_reader::attribute::ExceptionTableEntry;

    fn frame(class_id: ClassId, name: &str, table: Vec<ExceptionTableEntry>) -> Frame {
        Frame::new(
            class_id,
            "cratonvm/test/W11Events".to_string(),
            name.to_string(),
            "()V".to_string(),
            None,
            vec![0xb1],
            table,
            4,
            2,
            &[],
        )
    }

    /// An agent enabled for `Exception` on the VM's manager gets one event
    /// per throw, with the throw location, the exception and the handler
    /// that will catch it (method 0 / location -1 when none does); the same
    /// exception reaching an outer interpreter entry of the same thread is
    /// not posted again, a rethrow after a catch is. Nothing is posted or
    /// remembered while the event is disabled.
    #[test]
    fn a_jvmti_exception_event_is_posted_once_per_throw() {
        let _lock = jvmti::jvmti_registry_test_lock();
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let vm = shared.vm_identity;
        jvmti::install_manager_for_vm(vm, Arc::new(jvmti::JvmtiEventManager::new_for_vm(vm)));
        let mgr = jvmti::manager_for_vm(vm).expect("row was just installed");
        let exc_class = shared
            .classes
            .class_manager
            .write()
            .try_ensure_synthetic_class("cratonvm/test/W11Thrown", 0)
            .expect("Compatible mode fabricates");
        let exc = shared.mem.heap.alloc_object(exc_class, 0);
        let owner = ClassId::new(0x00F1_0B01);
        let catch_all = ExceptionTableEntry {
            start_pc: 0,
            end_pc: 10,
            handler_pc: 7,
            catch_type: 0,
        };

        let events = Arc::new(std::sync::Mutex::new(Vec::new()));
        let seen = Arc::clone(&events);
        mgr.set_event_callbacks(EventCallbacks {
            exception: Some(Box::new(
                move |_, method, location, exception, catch_method, catch_location| {
                    seen.lock().expect("event list").push((
                        method,
                        location,
                        exception != 0,
                        catch_method,
                        catch_location,
                    ));
                },
            )),
            ..Default::default()
        })
        .expect("install callbacks");

        // Not enabled: nothing posted, nothing remembered.
        let mut t = JvmThread::new(ThreadId(0), "w11-jvmti-exceptions");
        t.frames.push(frame(owner, "thrower", vec![catch_all]));
        let mut idx = 0usize;
        unwind_to_handler(&shared, &mut t, &mut idx, 0, exc, 5).expect("caught");
        assert!(events.lock().expect("event list").is_empty());
        assert_eq!(t.reported_exception, 0);

        mgr.set_event_notification_mode(EventMode::Enable, JvmtiEventKind::Exception, None)
            .expect("enable Exception");
        assert!(jvmti::any_exception_listener_active());
        let thrower = jvmti_events::jvmti_method_id(vm, &t.frames[0]);

        // Caught at pc 5 by the catch-all [0, 10) -> 7.
        let mut idx = 0usize;
        unwind_to_handler(&shared, &mut t, &mut idx, 0, exc, 5).expect("caught");
        assert_eq!(
            *events.lock().expect("event list"),
            vec![(thrower, 5, true, thrower, 7)]
        );
        assert_eq!(t.reported_exception, 0, "caught: forgotten");
        // Caught, so a rethrow of the same object is a new throw.
        let mut idx = 0usize;
        unwind_to_handler(&shared, &mut t, &mut idx, 0, exc, 5).expect("caught again");
        assert_eq!(events.lock().expect("event list").len(), 2);

        // Uncaught, then the outer interpreter entry of the same thread.
        let mut u = JvmThread::new(ThreadId(1), "w11-jvmti-uncaught");
        u.frames.push(frame(owner, "thrower", Vec::new()));
        let mut idx = 0usize;
        assert!(unwind_to_handler(&shared, &mut u, &mut idx, 0, exc, 5).is_err());
        assert_ne!(u.reported_exception, 0);
        u.frames.push(frame(owner, "outer", Vec::new()));
        let mut idx = 1usize;
        assert!(unwind_to_handler(&shared, &mut u, &mut idx, 1, exc, 2).is_err());
        {
            let events = events.lock().expect("event list");
            assert_eq!(events.len(), 3, "reported once, where thrown");
            assert_eq!(events[2], (thrower, 5, true, 0, -1), "uncaught");
        }

        let _ =
            mgr.set_event_notification_mode(EventMode::Disable, JvmtiEventKind::Exception, None);
        jvmti::forget_vm_jvmti_state(vm);
        // Wave 12: the uncaught thread's exit frees the handle it kept.
        let kept = u.reported_exception;
        release_debugger_thread_state(&shared, &mut u);
        assert_eq!(u.reported_exception, 0);
        assert!(shared.natives.jni_global_refs.lock().kind(kept).is_none());
        // Nothing reported: the exit helper is a no-op.
        release_debugger_thread_state(&shared, &mut t);
        assert_eq!(t.reported_exception, 0);
    }
}

/// Interpreter round i1 wave 21, lane L2: the compiled catch doors post
/// `Exception` at the compiled throw site and `ExceptionCatch` at the handler
/// (`report_exception_caught_by_compiled_door`), and the compiled local
/// handler declines while this VM may have an exception client
/// (`exception_events_may_be_armed`). Proposal
/// `docs/feature-designs/jdk-only-mode.md`.
#[cfg(test)]
mod i1w21_l2_compiled_catch_event_tests {
    use super::*;
    use crate::runtime::jvmti::{self, EventCallbacks, EventMode, JvmtiEventKind};
    use crate::threading::jvm_thread::ThreadId;
    use cratonvm_reader::attribute::ExceptionTableEntry;

    /// Eleven `nop`s and a `return`, so bcis 0..=11 are real offsets.
    fn frame(class_id: ClassId, name: &str, table: Vec<ExceptionTableEntry>) -> Frame {
        let mut code = vec![0x00; 11];
        code.push(0xb1);
        Frame::new(
            class_id,
            "cratonvm/test/W21CompiledCatch".to_string(),
            name.to_string(),
            "()V".to_string(),
            None,
            code,
            table,
            4,
            2,
            &[],
        )
    }

    type ExceptionEvents = Arc<std::sync::Mutex<Vec<(u64, i64, u64, i64)>>>;
    type CatchEvents = Arc<std::sync::Mutex<Vec<(u64, i64)>>>;

    /// A VM whose manager listens for `Exception` and `ExceptionCatch`.
    fn listening_vm() -> (Arc<SharedVm>, ExceptionEvents, CatchEvents) {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let vm = shared.vm_identity;
        jvmti::install_manager_for_vm(vm, Arc::new(jvmti::JvmtiEventManager::new_for_vm(vm)));
        let mgr = jvmti::manager_for_vm(vm).expect("row was just installed");
        let thrown: ExceptionEvents = Arc::default();
        let caught: CatchEvents = Arc::default();
        let (t_sink, c_sink) = (Arc::clone(&thrown), Arc::clone(&caught));
        mgr.set_event_callbacks(EventCallbacks {
            exception: Some(Box::new(
                move |_, method, location, _exception, catch_method, catch_location| {
                    t_sink.lock().expect("events").push((
                        method,
                        location,
                        catch_method,
                        catch_location,
                    ));
                },
            )),
            exception_catch: Some(Box::new(move |_, method, location, _exception| {
                c_sink.lock().expect("events").push((method, location));
            })),
            ..Default::default()
        })
        .expect("install callbacks");
        for kind in [JvmtiEventKind::Exception, JvmtiEventKind::ExceptionCatch] {
            mgr.set_event_notification_mode(EventMode::Enable, kind, None)
                .expect("enable");
        }
        (shared, thrown, caught)
    }

    fn thrown_object(shared: &SharedVm) -> ObjectRef {
        let exc_class = shared
            .classes
            .class_manager
            .write()
            .try_ensure_synthetic_class("cratonvm/test/W21Thrown", 0)
            .expect("Compatible mode fabricates");
        shared.mem.heap.alloc_object(exc_class, 0)
    }

    /// A door's handler frame: `[2, 10) -> 7`, catch-all, the throwable on
    /// the operand stack and the pc at the handler, as every door leaves it.
    fn handler_frame(exc: ObjectRef) -> Frame {
        let row = ExceptionTableEntry {
            start_pc: 2,
            end_pc: 10,
            handler_pc: 7,
            catch_type: 0,
        };
        let mut f = frame(ClassId::new(0x00F1_2101), "catcher", vec![row]);
        f.stack.push(Value::Object(Some(exc))).expect("push");
        f.pc = 7;
        f
    }

    #[test]
    fn a_compiled_catch_posts_exception_then_exception_catch() {
        let _lock = jvmti::jvmti_registry_test_lock();
        let (shared, thrown, caught) = listening_vm();
        let vm = shared.vm_identity;
        let exc = thrown_object(&shared);
        assert!(exception_events_may_be_armed(&shared));

        let mut t = JvmThread::new(ThreadId(0), "w21-compiled-catch");
        t.frames.push(handler_frame(exc));
        let catcher = jvmti_events::jvmti_method_id(vm, &t.frames[0]);
        report_exception_caught_by_compiled_door(&shared, &mut t, 0, 5, 7);
        assert_eq!(
            *thrown.lock().expect("events"),
            vec![(catcher, 5, catcher, 7)],
            "Exception at the compiled throw bci, caught by this frame's handler"
        );
        assert_eq!(*caught.lock().expect("events"), vec![(catcher, 7)]);
        assert_eq!(t.reported_exception, 0, "caught: forgotten");

        // An unknown throw pc is reported at the start of the protected range
        // whose handler runs. A second catch of the same object is a new throw.
        report_exception_caught_by_compiled_door(&shared, &mut t, 0, usize::MAX, 7);
        assert_eq!(thrown.lock().expect("events")[1], (catcher, 2, catcher, 7));
        assert_eq!(caught.lock().expect("events").len(), 2);

        jvmti::forget_vm_jvmti_state(vm);
    }

    /// An exception an interpreted callee threw was reported by that callee's
    /// unwinder; the compiled door that catches it posts only `ExceptionCatch`.
    #[test]
    fn an_exception_reported_by_an_interpreted_callee_is_not_reported_again() {
        let _lock = jvmti::jvmti_registry_test_lock();
        let (shared, thrown, caught) = listening_vm();
        let vm = shared.vm_identity;
        let exc = thrown_object(&shared);

        let mut t = JvmThread::new(ThreadId(0), "w21-callee-reported");
        t.frames.push(handler_frame(exc));
        t.frames
            .push(frame(ClassId::new(0x00F1_2102), "callee", Vec::new()));
        let mut idx = 1usize;
        assert!(unwind_to_handler(&shared, &mut t, &mut idx, 1, exc, 3).is_err());
        assert_eq!(
            thrown.lock().expect("events").len(),
            1,
            "the callee's throw"
        );
        assert_ne!(t.reported_exception, 0);
        let _ = t.frames.pop();

        report_exception_caught_by_compiled_door(&shared, &mut t, 0, 5, 7);
        assert_eq!(thrown.lock().expect("events").len(), 1, "not again");
        let catcher = jvmti_events::jvmti_method_id(vm, &t.frames[0]);
        assert_eq!(*caught.lock().expect("events"), vec![(catcher, 7)]);
        assert_eq!(t.reported_exception, 0, "caught: forgotten");

        jvmti::forget_vm_jvmti_state(vm);
    }

    /// Another VM's listener neither arms this VM's decline nor reaches its
    /// doors' events; with no listener the door posts nothing.
    #[test]
    fn another_vms_listener_does_not_arm_this_vm() {
        let _lock = jvmti::jvmti_registry_test_lock();
        let (loud, thrown, caught) = listening_vm();
        let quiet = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        jvmti::install_manager_for_vm(
            quiet.vm_identity,
            Arc::new(jvmti::JvmtiEventManager::new_for_vm(quiet.vm_identity)),
        );
        assert!(jvmti::any_exception_listener_active(), "the union is up");
        assert!(exception_events_may_be_armed(&loud));
        assert!(!exception_events_may_be_armed(&quiet));

        let exc = thrown_object(&quiet);
        let mut t = JvmThread::new(ThreadId(0), "w21-quiet-vm");
        t.frames.push(handler_frame(exc));
        report_exception_caught_by_compiled_door(&quiet, &mut t, 0, 5, 7);
        assert!(thrown.lock().expect("events").is_empty());
        assert!(caught.lock().expect("events").is_empty());
        assert_eq!(t.reported_exception, 0);

        jvmti::forget_vm_jvmti_state(loud.vm_identity);
        jvmti::forget_vm_jvmti_state(quiet.vm_identity);
    }

    /// An agent listening for `ExceptionCatch` alone makes the compiled local
    /// handler decline too (the doors post the event), for its own VM only,
    /// and not the `Exception` post.
    #[test]
    fn an_exception_catch_listener_alone_arms_the_decline() {
        let _lock = jvmti::jvmti_registry_test_lock();
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let vm = shared.vm_identity;
        jvmti::install_manager_for_vm(vm, Arc::new(jvmti::JvmtiEventManager::new_for_vm(vm)));
        let other = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        jvmti::install_manager_for_vm(
            other.vm_identity,
            Arc::new(jvmti::JvmtiEventManager::new_for_vm(other.vm_identity)),
        );
        let mgr = jvmti::manager_for_vm(vm).expect("row was just installed");
        assert!(!compiled_catch_events_armed(&shared));
        mgr.set_event_notification_mode(EventMode::Enable, JvmtiEventKind::ExceptionCatch, None)
            .expect("enable ExceptionCatch");
        assert!(jvmti::any_exception_catch_listener_active());
        assert!(compiled_catch_events_armed(&shared));
        assert!(
            !exception_events_may_be_armed(&shared),
            "no Exception client"
        );
        assert!(!compiled_catch_events_armed(&other), "another VM's agent");
        let _ = mgr.set_event_notification_mode(
            EventMode::Disable,
            JvmtiEventKind::ExceptionCatch,
            None,
        );
        assert!(!compiled_catch_events_armed(&shared));
        jvmti::forget_vm_jvmti_state(vm);
        jvmti::forget_vm_jvmti_state(other.vm_identity);
    }

    /// The body of the first `fn` whose signature starts with `sig` in `src`,
    /// up to the first line that is a lone closing brace.
    fn body<'a>(src: &'a str, sig: &str) -> &'a str {
        let start = src.find(sig).unwrap_or_else(|| panic!("`{sig}` not found"));
        let rest = &src[start..];
        let end = rest.find("\n\x7d\n").map_or(rest.len(), |e| e + 3);
        &rest[..end]
    }

    /// Source witness: every compiled catch door posts through
    /// `report_exception_caught_by_compiled_door` (the doors of
    /// `helpers::every_compiled_catch_door_drains_the_leftover_native_return`
    /// plus the first-call door's `jit_early_exception` arm), and the local
    /// handler lookup declines while an exception client may be armed before
    /// either of its arms can catch. `jvmti::EXCEPTION_EVENTS_NEED_THE_INTERPRETER`
    /// may be turned off only while this holds and the remaining gap on the
    /// proposal page is closed.
    #[test]
    fn every_compiled_catch_door_reports_the_catch() {
        let lf = |s: &str| s.replace("\r\n", "\n");
        let interp = lf(include_str!("interpreter.rs"));
        let dispatch = lf(include_str!("interpreter/exception_dispatch.rs"));
        let resume = lf(include_str!("interpreter/deopt_resume.rs"));
        let bridge = lf(include_str!("interpreter/jit_bridge.rs"));
        let helpers = lf(crate::jit::helpers::HELPERS_SRC);
        const REPORT: &str = "report_exception_caught_by_compiled_door(";
        for (src, sig) in [
            (
                &dispatch,
                "pub(super) fn route_jit_exception_through_method(",
            ),
            (&resume, "pub(crate) fn execute_resumed_handler_frame("),
            (
                &bridge,
                "pub(super) fn route_osr_exception_out_of_artifact(",
            ),
        ] {
            assert!(body(src, sig).contains(REPORT), "`{sig}` does not report");
        }
        assert!(
            body(&dispatch, "pub(crate) fn run_jit_callee_handler(")
                .contains("execute_resumed_handler_frame("),
            "the callee handler must run through the reporting push"
        );
        // An escape the OSR door knows the precise bci of is reported there.
        assert!(
            body(
                &bridge,
                "pub(super) fn route_osr_exception_out_of_artifact("
            )
            .contains("deliver_exception_event_if_armed("),
            "the OSR door does not report an escape"
        );
        // The first-call door's arm, both outcomes.
        let arm_start = interp
            .find("if let Some(early_exc) = jit_early_exception \x7b")
            .expect("the jit_early_exception arm");
        let arm = &interp[arm_start..];
        let arm = &arm[..arm
            .find("// Execute (with panic protection")
            .expect("arm end")];
        assert!(
            arm.contains(REPORT),
            "the early arm does not report a catch"
        );
        assert!(
            arm.contains("deliver_exception_event_if_armed("),
            "the early arm does not report an escape"
        );
        // The decline precedes both local-handler arms.
        let lookup = body(&helpers, "unsafe fn jit_local_handler_lookup_body(");
        let decline = lookup
            .find("compiled_catch_events_armed(")
            .expect("the lookup declines while armed");
        let implicit = lookup
            .find("local_handler_enter_implicit(")
            .expect("the implicit arm");
        let dispatched = lookup
            .find("take_jit_pending_exception(")
            .expect("the dispatched arm");
        assert!(decline < implicit && decline < dispatched);
    }
}

/// Interpreter round i1 wave 10, lane L1: JDWP field watches and exception
/// events, reported by the field bytecodes' hook and the unwinder's.
/// Interpreter round i2 wave 58, lane L6 (`CRATONVM_HANDSHAKE_NATIVE_EXCUSE`).
#[cfg(test)]
mod i58_l6_native_excuse_tests {
    use super::*;
    use crate::threading::jvm_thread::{NativeExcuse, ThreadId, NX_EXCUSED};

    /// Java a native runs lowers the thread's native-excuse word while it
    /// runs (a nested entry finds it lowered and keeps nothing) and raises it
    /// again after; its lowering waits while a handshake pause holds the
    /// excusal.
    #[test]
    fn java_a_native_runs_lowers_the_native_excuse_while_it_runs() {
        let mut thread = JvmThread::new(ThreadId(0x0F58), "w58-native-excuse");
        let raised = NativeExcuse::raised(true, 3);
        thread.gc_block_state.native_excuse.raise(raised);
        thread.native_excuse_raised = raised;
        {
            let outer = NestedJavaAck::enter(&thread);
            assert_eq!(outer.excuse, raised);
            assert_eq!(
                thread.gc_block_state.native_excuse.load(),
                0,
                "its Java runs"
            );
            {
                let inner = NestedJavaAck::enter(&thread);
                assert_eq!(inner.excuse, 0, "already lowered");
                assert!(inner.state.is_none());
            }
            assert_eq!(thread.gc_block_state.native_excuse.load(), 0);
        }
        assert_eq!(
            thread.gc_block_state.native_excuse.load(),
            raised,
            "back in the native"
        );
        // Excused by a pause: the entry waits for the release.
        assert_eq!(
            thread.gc_block_state.native_excuse.try_excuse(true),
            Some(raised)
        );
        let state = std::sync::Arc::clone(&thread.gc_block_state);
        let releaser = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(30));
            assert_eq!(state.native_excuse.load(), raised | NX_EXCUSED);
            state.native_excuse.release();
        });
        let t0 = std::time::Instant::now();
        {
            let guard = NestedJavaAck::enter(&thread);
            assert!(
                t0.elapsed() >= std::time::Duration::from_millis(20),
                "waited"
            );
            assert_eq!(guard.excuse, raised);
        }
        releaser.join().unwrap();
        assert_eq!(thread.gc_block_state.native_excuse.load(), raised);
    }

    /// The frame stack's one relocation lowers the word around the move
    /// (waiting while a pause holds it), republishes the buffer's address,
    /// and raises the word again.
    #[test]
    fn a_relocating_frame_stack_republishes_its_buffer_to_the_excuse_word() {
        let cell = std::sync::Arc::new(NativeExcuse::new());
        let mut frames = crate::runtime::frame::FrameStack::new();
        frames.set_excuse_cell(&cell);
        frames.reserve_stable(1);
        let first = cell.frames();
        assert_eq!(first, frames.as_ptr() as usize);
        let raised = NativeExcuse::raised(true, 1);
        cell.raise(raised);
        assert_eq!(cell.try_excuse(true), Some(raised));
        let c = std::sync::Arc::clone(&cell);
        let releaser = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(30));
            c.release();
        });
        let t0 = std::time::Instant::now();
        // Far past the initial capacity: a relocation.
        frames.reserve_stable(1 << 12);
        assert!(
            t0.elapsed() >= std::time::Duration::from_millis(20),
            "waited"
        );
        releaser.join().unwrap();
        assert_eq!(cell.frames(), frames.as_ptr() as usize);
        assert_ne!(cell.frames(), first, "the buffer moved");
        assert_eq!(cell.load(), raised, "raised again after the move");
    }
}

#[cfg(all(test, feature = "experimental-debug"))]
mod i1w10_l1_debugger_event_tests {
    use super::*;
    use crate::classloading::{Class, ClassLoaderId, ClassState};
    use crate::debug::events::{EventKind, EventModifier, SuspendPolicy};
    use crate::threading::jvm_thread::ThreadId;
    use cratonvm_reader::attribute::ExceptionTableEntry;
    use cratonvm_reader::class_access_flags::{ClassAccessFlags, FieldAccessFlags};
    use cratonvm_reader::class_file_version::ClassFileVersion;
    use cratonvm_reader::constant_pool::{ConstantPool, ConstantPoolEntry};
    use cratonvm_reader::field::ClassFileField;
    use std::sync::mpsc::Receiver;

    fn field(name: &str, desc: &str, flags: FieldAccessFlags) -> ClassFileField {
        ClassFileField {
            access_flags: flags,
            name: Arc::from(name),
            descriptor: Arc::from(desc),
            attributes: vec![],
        }
    }

    /// A class `name` declaring `fields` (instance slots from
    /// `first_field_index`), with no superclass.
    fn add_class(
        shared: &SharedVm,
        name: &str,
        fields: Vec<ClassFileField>,
        first_field_index: usize,
    ) -> ClassId {
        let instance = fields.iter().filter(|f| !f.is_static()).count();
        let mut cm = shared.classes.class_manager.write();
        let id = cm.class_store.next_id();
        cm.class_store.add(Class {
            id,
            loader_id: ClassLoaderId::Application,
            name: cratonvm_types::intern_arc(name),
            source_file: None,
            version: ClassFileVersion::JAVA_8,
            state: ClassState::Initialized,
            initializing_thread: None,
            constant_pool: ConstantPool::new(vec![ConstantPoolEntry::Tombstone]),
            access_flags: ClassAccessFlags::empty(),
            superclass: None,
            interfaces: vec![],
            fields,
            methods: vec![],
            first_field_index,
            num_total_fields: first_field_index + instance,
            bootstrap_methods: vec![],
            signature: None,
            annotations: Vec::new(),
            nest_host: None,
            nest_members: Vec::new(),
            record_components: Vec::new(),
            permitted_subclasses: Vec::new(),
            inner_classes: Vec::new(),
            enclosing_method: None,
            hidden: false,
            module_name: None,
            origin: cratonvm_classloading::ClassOrigin::default(),
            has_finalizer: false,
            code_source: None,
            array_info: None,
            record_object_methods: std::sync::atomic::AtomicU8::new(0),
            init_state: Arc::new(std::sync::atomic::AtomicU8::new(0)),
        });
        cm.register_class_name(ClassLoaderId::Application, name, id);
        id
    }

    fn frame(class_id: ClassId, name: &str, table: Vec<ExceptionTableEntry>) -> Frame {
        Frame::new(
            class_id,
            "cratonvm/test/W10Events".to_string(),
            name.to_string(),
            "()V".to_string(),
            None,
            vec![0xb1],
            table,
            4,
            2,
            &[],
        )
    }

    /// Register one request, publish the gates and attach an event channel.
    fn arm(
        shared: &SharedVm,
        kind: EventKind,
        policy: SuspendPolicy,
        modifiers: Vec<EventModifier>,
    ) -> u32 {
        let mut ds = shared.debug.debug_state.lock();
        let id = ds.events.set_event_request(kind, policy, modifiers);
        crate::debug::publish_debugger_gates(shared, &ds);
        id
    }

    fn channel(shared: &SharedVm) -> Receiver<crate::debug::DebugEvent> {
        let (tx, rx) = std::sync::mpsc::channel();
        *shared.debug.debug_event_tx.lock().expect("event channel") = Some(tx);
        rx
    }

    fn disarm(shared: &SharedVm) {
        let mut ds = shared.debug.debug_state.lock();
        ds.events.clear_all();
        crate::debug::publish_debugger_gates(shared, &ds);
    }

    fn be64(bytes: &[u8]) -> u64 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&bytes[..8]);
        u64::from_be_bytes(b)
    }

    /// The `class.fields` position of a resolved field: statics counted
    /// among statics, instance fields from `first_field_index`.
    #[test]
    fn a_resolved_field_maps_to_its_declared_position() {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let inst = FieldAccessFlags::PRIVATE;
        let stat = FieldAccessFlags::PRIVATE | FieldAccessFlags::STATIC;
        let cid = add_class(
            &shared,
            "cratonvm/test/W10FieldPositions",
            vec![
                field("i", "I", inst),
                field("s", "J", stat),
                field("o", "Ljava/lang/Object;", inst),
            ],
            3,
        );
        let cm = shared.classes.class_manager.read();
        let class = cm.class_store.get(cid).expect("just added");
        assert_eq!(declared_field_position(class, false, 3), Some(0));
        assert_eq!(declared_field_position(class, false, 4), Some(2));
        assert_eq!(declared_field_position(class, true, 0), Some(1));
        assert_eq!(declared_field_position(class, false, 5), None);
        assert_eq!(
            declared_field_position(class, false, 2),
            None,
            "a superclass slot"
        );
        assert_eq!(declared_field_position(class, true, 1), None);
    }

    /// A JDWP `FieldModification` watch reports the field, the object and
    /// the new value read in place (the operands stay on the stack); a
    /// static's object is null; a watch on another field, or an access
    /// where only modifications are watched, reports nothing. Arming raises
    /// the process-wide field pre-filter, disarming lowers it.
    #[test]
    fn field_watches_report_the_field_object_and_new_value() {
        let _lock = crate::runtime::jvmti::jvmti_registry_test_lock();
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let inst = FieldAccessFlags::PRIVATE;
        let stat = FieldAccessFlags::PRIVATE | FieldAccessFlags::STATIC;
        let cid = add_class(
            &shared,
            "cratonvm/test/W10Watched",
            vec![
                field("x", "I", inst),
                field("s", "J", stat),
                field("y", "Ljava/lang/Object;", inst),
            ],
            0,
        );
        let class_wire = u64::from(cid.as_u32());
        let x_id = crate::debug::jdwp_field_id(cid, 0);
        let s_id = crate::debug::jdwp_field_id(cid, 1);
        let watch_x = arm(
            &shared,
            EventKind::FieldModification,
            SuspendPolicy::None,
            vec![EventModifier::FieldOnly {
                class_id: class_wire,
                field_id: x_id,
            }],
        );
        let watch_s = arm(
            &shared,
            EventKind::FieldModification,
            SuspendPolicy::None,
            vec![EventModifier::FieldOnly {
                class_id: class_wire,
                field_id: s_id,
            }],
        );
        assert!(shared.debug.debugger_gates.field_watch_armed());
        assert!(crate::runtime::jvmti::any_field_watchpoint_active());
        let rx = channel(&shared);
        let obj = shared.mem.heap.alloc_object(cid, 2);
        let resolved = |field_index: usize, is_static: bool, desc_byte: u8| ResolvedField {
            declaring_class_id: cid,
            field_index,
            is_static,
            is_volatile: false,
            is_final: false,
            is_reference: matches!(desc_byte, b'L' | b'['),
            desc_byte,
        };
        let mut thread = JvmThread::new(ThreadId(0), "w10-field-watch");
        let mut f = frame(cid, "watcher", Vec::new());
        f.last_instr_pc = 3;
        thread.frames.push(f);

        // putfield x = 7: [obj, 7].
        thread.frames[0]
            .stack
            .push(Value::Object(Some(obj)))
            .expect("push the receiver");
        thread.frames[0].stack.push(Value::Int(7)).expect("push 7");
        deliver_field_watch_if_armed(&shared, &mut thread, 0, &resolved(0, false, b'I'), true);
        assert_eq!(thread.frames[0].stack.len(), 2, "the operands stay");
        let evt = rx.try_recv().expect("one FieldModification event");
        assert_eq!(
            (evt.kind, evt.request_id, evt.offset),
            (EventKind::FieldModification, watch_x, 3)
        );
        let e = &evt.extra;
        assert_eq!(e.len(), 31, "tag, class, field, tagged object, tagged int");
        assert_eq!(e[0], 1, "refTypeTag CLASS");
        assert_eq!(be64(&e[1..]), class_wire);
        assert_eq!(be64(&e[9..]), x_id);
        assert_eq!(e[17], b'L');
        let object_id = be64(&e[18..]);
        {
            let ds = shared.debug.debug_state.lock();
            assert_eq!(
                crate::debug::object_for_id(&shared, &ds, object_id),
                Some(obj),
                "the object id names the receiver"
            );
        }
        assert_eq!(e[26], b'I');
        assert_eq!(&e[27..31], &7u32.to_be_bytes());
        assert!(rx.try_recv().is_err(), "one event");

        // getfield x: only modifications are watched.
        let _ = thread.frames[0].stack.pop();
        deliver_field_watch_if_armed(&shared, &mut thread, 0, &resolved(0, false, b'I'), false);
        // putfield y (unwatched): [obj, null].
        thread.frames[0]
            .stack
            .push(Value::Object(None))
            .expect("push null");
        deliver_field_watch_if_armed(&shared, &mut thread, 0, &resolved(1, false, b'L'), true);
        assert!(rx.try_recv().is_err(), "no access event, no event for y");

        // putstatic s = 9L: [9L]; the object is null.
        thread.frames[0].stack.clear();
        thread.frames[0]
            .stack
            .push(Value::Long(9))
            .expect("push 9L");
        deliver_field_watch_if_armed(&shared, &mut thread, 0, &resolved(0, true, b'J'), true);
        let evt = rx.try_recv().expect("the static's event");
        assert_eq!(evt.request_id, watch_s);
        let e = &evt.extra;
        assert_eq!(be64(&e[9..]), s_id);
        assert_eq!((e[17], be64(&e[18..])), (b'L', 0), "no object for a static");
        assert_eq!(e[26], b'J');
        assert_eq!(be64(&e[27..]), 9);

        disarm(&shared);
        assert!(!shared.debug.debugger_gates.field_watch_armed());
        assert!(
            !crate::runtime::jvmti::any_field_watchpoint_active(),
            "the pre-filter falls with the last watch"
        );
    }

    fn catch_all(start_pc: u16, end_pc: u16, handler_pc: u16) -> ExceptionTableEntry {
        ExceptionTableEntry {
            start_pc,
            end_pc,
            handler_pc,
            catch_type: 0,
        }
    }

    /// An exception is reported where it is thrown, with the handler that
    /// catches it as the catch location, or 0 when none does; it is not
    /// reported again at the next interpreter entry it unwinds into, but is
    /// after a handler caught it (a rethrow). `ExceptionOnly` filters by
    /// class and by caught / uncaught.
    #[test]
    fn exception_events_report_throw_and_catch_locations_once() {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let exc_class = shared
            .classes
            .class_manager
            .write()
            .try_ensure_synthetic_class("cratonvm/test/W10Thrown", 0)
            .expect("Compatible mode fabricates");
        let exc = shared.mem.heap.alloc_object(exc_class, 0);
        let owner = ClassId::new(0x00F1_0A01);
        let any = arm(
            &shared,
            EventKind::Exception,
            SuspendPolicy::None,
            vec![EventModifier::ExceptionOnly {
                class_id: 0,
                caught: true,
                uncaught: true,
            }],
        );
        let uncaught_only = arm(
            &shared,
            EventKind::Exception,
            SuspendPolicy::None,
            vec![EventModifier::ExceptionOnly {
                class_id: u64::from(exc_class.as_u32()),
                caught: false,
                uncaught: true,
            }],
        );
        assert!(shared.debug.debugger_gates.exception_events_armed());
        let rx = channel(&shared);
        let method_id = crate::debug::jdwp_method_id("thrower", "()V");

        // Caught at pc 5 by the catch-all [0, 10) -> 7.
        let mut t = JvmThread::new(ThreadId(0), "w10-exceptions");
        t.frames
            .push(frame(owner, "thrower", vec![catch_all(0, 10, 7)]));
        let mut idx = 0usize;
        unwind_to_handler(&shared, &mut t, &mut idx, 0, exc, 5).expect("caught");
        let events: Vec<_> = rx.try_iter().collect();
        assert_eq!(
            events.len(),
            1,
            "a caught exception: the unfiltered request only"
        );
        let evt = &events[0];
        assert_eq!(
            (evt.kind, evt.request_id, evt.offset, evt.method_id),
            (EventKind::Exception, any, 5, method_id)
        );
        let e = &evt.extra;
        assert_eq!(e.len(), 34, "tagged exception, then the catch location");
        assert_eq!(e[0], b'L');
        assert_ne!(be64(&e[1..]), 0);
        assert_eq!(e[9], 1, "catch location: CLASS");
        assert_eq!(be64(&e[10..]), u64::from(owner.as_u32()));
        assert_eq!(be64(&e[18..]), method_id);
        assert_eq!(be64(&e[26..]), 7, "the handler pc");

        // Caught, so a rethrow of the same object is a new throw.
        let mut t = JvmThread::new(ThreadId(0), "w10-exceptions");
        t.frames
            .push(frame(owner, "thrower", vec![catch_all(0, 10, 7)]));
        let mut idx = 0usize;
        unwind_to_handler(&shared, &mut t, &mut idx, 0, exc, 5).expect("caught again");
        assert_eq!(rx.try_iter().count(), 1, "the rethrow is reported");

        // Uncaught: no handler anywhere on the thread.
        let mut t = JvmThread::new(ThreadId(0), "w10-exceptions");
        t.frames.push(frame(owner, "thrower", Vec::new()));
        let mut idx = 0usize;
        assert!(unwind_to_handler(&shared, &mut t, &mut idx, 0, exc, 5).is_err());
        let events: Vec<_> = rx.try_iter().collect();
        let mut ids: Vec<u32> = events.iter().map(|e| e.request_id).collect();
        ids.sort_unstable();
        assert_eq!(ids, vec![any, uncaught_only], "both requests report it");
        assert!(
            events
                .iter()
                .all(|e| e.extra.len() == 34 && e.extra[10..].iter().all(|&b| b == 0)),
            "catch location 0: uncaught"
        );

        // The same exception reaching the unwinder of an outer interpreter
        // entry on the same thread is not a new throw (wave 11: the state is
        // the thread's own, `JvmThread::reported_exception`).
        assert_ne!(t.reported_exception, 0, "the thread remembers it");
        t.frames.push(frame(owner, "outer", Vec::new()));
        let mut idx = 1usize;
        assert!(unwind_to_handler(&shared, &mut t, &mut idx, 1, exc, 2).is_err());
        assert_eq!(rx.try_iter().count(), 0, "reported once, where thrown");

        disarm(&shared);
        assert!(!shared.debug.debugger_gates.exception_events_armed());
    }

    /// A JVMTI breakpoint arms the dispatch loop's per-method gate on its
    /// own, with no JDWP request in force, and the agent's `Breakpoint`
    /// callback runs once per execution of its pc — eleven times on the
    /// `if_icmpge` inside javac's fusable loop test for a ten-trip loop
    /// (fusion declines while the gate is armed). `DUPLICATE` / `NOT_FOUND`
    /// as the spec says, and clearing it disarms the method again.
    #[test]
    fn a_jvmti_breakpoint_fires_on_every_execution_of_its_pc() {
        use crate::runtime::jvmti::{self, EventCallbacks, EventMode, JvmtiError, JvmtiEventKind};
        let _lock = jvmti::jvmti_registry_test_lock();
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let vm = shared.vm_identity;
        jvmti::install_manager_for_vm(vm, Arc::new(jvmti::JvmtiEventManager::new_for_vm(vm)));
        let mgr = jvmti::manager_for_vm(vm).expect("row was just installed");
        mgr.set_event_notification_mode(EventMode::Enable, JvmtiEventKind::Breakpoint, None)
            .expect("enable Breakpoint");
        let hits = Arc::new(std::sync::Mutex::new(Vec::new()));
        let seen = Arc::clone(&hits);
        mgr.set_event_callbacks(EventCallbacks {
            breakpoint: Some(Box::new(move |_, _, location| {
                seen.lock().expect("hit list").push(location);
            })),
            ..Default::default()
        })
        .expect("install callbacks");
        let cid = ClassId::new(0x00F1_0A03);
        let class_wire = u64::from(cid.as_u32());
        let key = crate::debug::jdwp_method_id("jvmtiBpLoop", "()I");
        jvmti::add_breakpoint_key(&shared, class_wire, key, 9).expect("set");
        assert_eq!(
            jvmti::add_breakpoint_key(&shared, class_wire, key, 9),
            Err(JvmtiError::Duplicate)
        );
        assert!(shared
            .debug
            .debugger_gates
            .concerns_method(cid.as_u32(), "jvmtiBpLoop", "()I"));
        let code = vec![
            0x10, 10, 0x3b, // 0: bipush 10; istore_0      n = 10
            0x03, 0x3c, // 3: iconst_0; istore_1           s = 0
            0x03, 0x3d, // 5: iconst_0; istore_2           i = 0
            0x1c, 0x1a, 0xa2, 0x00, 13, // 7: iload_2; iload_0; if_icmpge +13 (-> 22)
            0x1b, 0x1c, 0x60, 0x3c, // 12: iload_1; iload_2; iadd; istore_1
            0x84, 2, 1, // 16: iinc 2 1
            0xa7, 0xff, 0xf4, // 19: goto -12 (-> 7)
            0x1b, 0xac, // 22: iload_1; ireturn
        ];
        let mut thread = JvmThread::new(ThreadId(0), "w10-jvmti-breakpoint");
        let frame = Frame::new(
            cid,
            "cratonvm/test/W10Events".to_string(),
            "jvmtiBpLoop".to_string(),
            "()I".to_string(),
            None,
            code,
            Vec::new(),
            2,
            3,
            &[],
        );
        let r = execute_prebuilt_frame(&shared, &mut thread, frame);
        assert!(matches!(r, Ok(Some(Value::Int(45)))), "answer: {r:?}");
        assert_eq!(
            *hits.lock().expect("hit list"),
            vec![9i64; 11],
            "one callback per execution of pc 9"
        );
        jvmti::remove_breakpoint_key(&shared, class_wire, key, 9).expect("clear");
        assert_eq!(
            jvmti::remove_breakpoint_key(&shared, class_wire, key, 9),
            Err(JvmtiError::NotFound)
        );
        assert!(!shared
            .debug
            .debugger_gates
            .concerns_method(cid.as_u32(), "jvmtiBpLoop", "()I"));
        // An id naming no method is refused before anything is stored.
        assert_eq!(
            jvmti::set_breakpoint_for_vm(&shared, u64::from(cid.as_u32()) << 32, 0),
            Err(JvmtiError::InvalidMethodId)
        );
        let _ =
            mgr.set_event_notification_mode(EventMode::Disable, JvmtiEventKind::Breakpoint, None);
        jvmti::forget_vm_jvmti_state(vm);
    }

    /// While a debugger is attached, a thread entering a blocking native
    /// region publishes its frames (top frame at the invoke of the native)
    /// and their locals if it is already suspended, and withdraws them when
    /// it leaves; a thread that is not suspended only opens its inspection
    /// window (wave 12: it published a snapshot on every blocking call).
    /// Without a debugger nothing happens.
    #[test]
    fn a_blocked_thread_publishes_its_frames_while_a_debugger_is_attached() {
        use std::sync::atomic::Ordering;
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let owner = ClassId::new(0x00F1_0A04);
        let mut thread = JvmThread::new(ThreadId(0), "w10-blocked");
        let mut f = frame(owner, "sleeper", Vec::new());
        f.last_instr_pc = 4;
        f.set_local(0, Value::Int(5));
        thread.frames.push(f);
        let window = || {
            thread
                .gc_block_state
                .debugger_inspect
                .load(Ordering::Acquire)
        };
        assert!(!publish_blocked_frames(&shared, &thread));
        open_blocked_inspection(&shared, &thread, false);
        assert_eq!(window(), 0, "no debugger: no window");
        assert!(
            shared.debug.debug_state.lock().thread_frames.is_empty(),
            "no debugger: nothing published"
        );

        // Attached, not suspended: a window naming the thread, no snapshot.
        shared.debug.debugger_gates.set_session_attached(true);
        assert!(!publish_blocked_frames(&shared, &thread));
        open_blocked_inspection(&shared, &thread, false);
        assert_eq!(window() & INSPECT_FLAGS, INSPECT_OPEN);
        // Cast: the window's address half
        assert_eq!(
            window() & !INSPECT_FLAGS,
            &thread as *const JvmThread as usize
        );
        assert!(
            shared.debug.debug_state.lock().thread_frames.is_empty(),
            "not suspended: nothing published"
        );
        close_blocked_inspection(&shared, &thread);
        assert_eq!(window(), 0, "the leave closes it");

        // Suspended before it blocks: published on entry, withdrawn on leave.
        {
            let mut ds = shared.debug.debug_state.lock();
            ds.suspend_thread(0);
            crate::debug::publish_debugger_gates(&shared, &ds);
        }
        assert!(shared.debug.debugger_gates.suspension_in_force());
        let published = publish_blocked_frames(&shared, &thread);
        assert!(published);
        open_blocked_inspection(&shared, &thread, published);
        assert_eq!(window() & INSPECT_FLAGS, INSPECT_OPEN | INSPECT_PUBLISHED);
        {
            let ds = shared.debug.debug_state.lock();
            let top = ds.thread_frames.get(&0).and_then(|f| f.first()).cloned();
            assert_eq!(
                top.map(|e| (e.frame_id, e.class_id, e.offset)),
                Some((0, u64::from(owner.as_u32()), 4))
            );
            assert_eq!(
                ds.get_frame_locals(crate::debug::ids::ThreadId(0), 0)
                    .and_then(|l| l.first())
                    .and_then(|v| v.as_int()),
                Some(5)
            );
        }
        close_blocked_inspection(&shared, &thread);
        assert_eq!(window(), 0);
        {
            let ds = shared.debug.debug_state.lock();
            assert!(ds.thread_frames.is_empty() && ds.frame_locals.is_empty());
        }

        // Wave 28: resumed and suspended again, the same frame is listed
        // under the thread's next frame generation, and the id of the first
        // listing is refused (`INVALID_FRAMEID`), as HotSpot refuses it.
        {
            let mut ds = shared.debug.debug_state.lock();
            ds.resume_thread(0);
            ds.suspend_thread(0);
            crate::debug::publish_debugger_gates(&shared, &ds);
        }
        let published = publish_blocked_frames(&shared, &thread);
        assert!(published);
        open_blocked_inspection(&shared, &thread, published);
        {
            use crate::debug::commands::{
                dispatch, CMD_SF_GET_VALUES, CS_STACK_FRAME, ERR_INVALID_FRAMEID, ERR_NONE,
            };
            let mut ds = shared.debug.debug_state.lock();
            let top = ds
                .thread_frames
                .get(&0)
                .and_then(|f| f.first())
                .map(|e| e.frame_id);
            assert_eq!(top, Some(1u64 << 32), "generation 1, position 0");
            let get = |ds: &mut crate::debug::DebugState, frame: u64| {
                let mut pw = crate::debug::protocol::PayloadWriter::new();
                pw.put_u64_be(0); // thread
                pw.put_u64_be(frame);
                pw.put_u32_be(1);
                pw.put_u32_be(0); // slot
                pw.put_u8(b'I');
                dispatch(CS_STACK_FRAME, CMD_SF_GET_VALUES, &pw.into_bytes(), ds)
            };
            assert_eq!(get(&mut *ds, 0).error_code, ERR_INVALID_FRAMEID, "stale id");
            let fresh = get(&mut *ds, 1u64 << 32);
            assert_eq!(fresh.error_code, ERR_NONE);
            assert_eq!(fresh.data, [0, 0, 0, 1, b'I', 0, 0, 0, 5]);
        }
        close_blocked_inspection(&shared, &thread);
        assert_eq!(window(), 0);
        let mut ds = shared.debug.debug_state.lock();
        assert!(ds.thread_frames.is_empty() && ds.frame_locals.is_empty());
        ds.resume_all();
        crate::debug::publish_debugger_gates(&shared, &ds);
        drop(ds);
        assert!(!shared.debug.debugger_gates.suspension_in_force());
        shared.debug.debugger_gates.set_session_attached(false);
    }

    /// Wave 12: a thread suspended while it is blocked has its frames read on
    /// demand through its inspection window, a reference local as the
    /// object's current address from the blocking deposit's per-slot record
    /// (a slot the deposit found dead as null), once; a reader holding the
    /// window keeps the thread's leave waiting, and the leave withdraws the
    /// snapshot.
    #[test]
    fn a_thread_suspended_while_blocked_has_its_frames_read_on_demand() {
        use crate::threading::jvm_thread::SlotOrigin;
        use std::sync::atomic::Ordering;
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let cid = shared
            .classes
            .class_manager
            .write()
            .try_ensure_synthetic_class("cratonvm/test/W12Held", 0)
            .expect("Compatible mode fabricates");
        let moved_from = shared.mem.heap.alloc_object(cid, 0);
        let moved_to = shared.mem.heap.alloc_object(cid, 0);
        let dead = shared.mem.heap.alloc_object(cid, 0);
        let tid = ThreadId(0x0C12);
        let t = tid.0;
        let owner = ClassId::new(0x00F1_0C01);
        let mut thread = JvmThread::new(tid, "w12-blocked");
        let mut f = Frame::new(
            owner,
            "cratonvm/test/W12Events".to_string(),
            "waiter".to_string(),
            "()V".to_string(),
            None,
            vec![0xb1],
            Vec::new(),
            2,
            3,
            &[],
        );
        f.last_instr_pc = 6;
        f.set_local(0, Value::Int(9));
        f.set_local(1, Value::Object(Some(moved_from)));
        f.set_local(2, Value::Object(Some(dead)));
        thread.frames.push(f);
        let registry = &shared.threads.thread_registry;
        registry.register(tid, "w12-blocked", None);
        registry.set_gc_block_state(tid, Arc::clone(&thread.gc_block_state));
        // What the blocking deposit recorded, after a collection moved the
        // object local 1 names.
        // Cast: addresses, the deposit's keys
        let (from, to, gone) = (
            moved_from.as_ptr() as usize,
            moved_to.as_ptr() as usize,
            dead.as_ptr() as usize,
        );
        *thread.gc_block_state.slot_origins.lock() = vec![
            SlotOrigin {
                frame: 0,
                idx: 1,
                is_stack: false,
                live: true,
                orig: from,
                cur: to,
            },
            SlotOrigin {
                frame: 0,
                idx: 2,
                is_stack: false,
                live: false,
                orig: gone,
                cur: gone,
            },
        ];
        thread
            .gc_block_state
            .in_blocked_region
            .store(true, Ordering::Release);
        shared.debug.debugger_gates.set_session_attached(true);

        // Blocked, not suspended: a window, nothing to read yet.
        assert!(!publish_blocked_frames(&shared, &thread));
        open_blocked_inspection(&shared, &thread, false);
        assert!(blocked_frames_readable(&shared, t));
        assert!(
            !publish_frames_of_blocked_thread(&shared, t),
            "not suspended"
        );
        assert!(blocked_frames_readable(&shared, t), "the window is kept");

        // A reader holding the window keeps the leave waiting.
        let word = &thread.gc_block_state.debugger_inspect;
        let open = word.fetch_or(INSPECT_READING, Ordering::AcqRel);
        std::thread::scope(|s| {
            let leaver = s.spawn(|| close_inspection_window(word));
            std::thread::sleep(std::time::Duration::from_millis(20));
            assert!(!leaver.is_finished(), "the leave waits for the reader");
            word.store(open, Ordering::Release);
            assert!(!leaver.join().expect("the leave"), "nothing was published");
        });
        assert_eq!(word.load(Ordering::Acquire), 0);
        open_blocked_inspection(&shared, &thread, false);

        // Suspended while blocked: read on demand, once.
        {
            let mut ds = shared.debug.debug_state.lock();
            ds.suspend_all();
            crate::debug::publish_debugger_gates(&shared, &ds);
        }
        assert!(publish_frames_of_blocked_thread(&shared, t));
        assert_ne!(word.load(Ordering::Acquire) & INSPECT_PUBLISHED, 0);
        assert!(
            !publish_frames_of_blocked_thread(&shared, t),
            "published once: the snapshot stands"
        );
        {
            let ds = shared.debug.debug_state.lock();
            let top = ds.thread_frames.get(&t).and_then(|f| f.first()).cloned();
            assert_eq!(
                top.map(|e| (e.frame_id, e.class_id, e.method_id, e.offset)),
                Some((
                    0,
                    u64::from(owner.as_u32()),
                    crate::debug::jdwp_method_id("waiter", "()V"),
                    6
                ))
            );
            let locals = ds
                .get_frame_locals(crate::debug::ids::ThreadId(t), 0)
                .cloned()
                .expect("locals published");
            assert_eq!(locals.len(), 3);
            assert_eq!(locals[0].as_int(), Some(9));
            // Wave 126 (lane L1, i47-L1, `CRATONVM_DEBUG_BLOCKED_DEAD_LOCALS`,
            // default on): a dead slot reads its object while the tracked
            // address is still an object start, as HotSpot's interpreter
            // keeps the local; `=0`: null, as before. Wave 130 (lane L1a):
            // also with `CRATONVM_DEBUG_BLOCKED_ROOTED_DEAD_LOCALS` (default
            // on) in a VM with a JDWP port, where every local is a root.
            if blocked_dead_slots_read(&shared) {
                let id = locals[2].as_object_id().expect("an object id");
                assert_ne!(id, 0, "a dead slot reads its object");
                assert_eq!(crate::debug::object_for_id(&shared, &ds, id), Some(dead));
            } else {
                assert_eq!(locals[2].as_object_id(), Some(0), "a dead slot reads null");
            }
            if shared.mem.heap.is_object_address(to).is_some() {
                let id = locals[1].as_object_id().expect("an object id");
                assert_ne!(id, 0);
                assert_eq!(
                    crate::debug::object_for_id(&shared, &ds, id),
                    Some(moved_to),
                    "the object's current address"
                );
            }
        }

        // Wave 28: resumed and suspended again while still blocked, the
        // standing listing belongs to the old suspension: it is read again,
        // under the thread's next frame generation, once.
        {
            let mut ds = shared.debug.debug_state.lock();
            let before = ds
                .thread_frames
                .get(&t)
                .and_then(|f| f.first())
                .map(|e| e.frame_id);
            assert_eq!(before, Some(0));
            ds.resume_vm();
            ds.suspend_all();
            crate::debug::publish_debugger_gates(&shared, &ds);
            assert!(!ds.has_current_frames(t));
        }
        assert!(
            publish_frames_of_blocked_thread(&shared, t),
            "a listing from before the resume is read again"
        );
        assert!(
            !publish_frames_of_blocked_thread(&shared, t),
            "once per suspension"
        );
        {
            let ds = shared.debug.debug_state.lock();
            assert!(ds.has_current_frames(t));
            let top = ds
                .thread_frames
                .get(&t)
                .and_then(|f| f.first())
                .map(|e| e.frame_id);
            assert_eq!(top, Some(1u64 << 32), "generation 1, position 0");
        }

        // The leave withdraws it.
        close_blocked_inspection(&shared, &thread);
        assert_eq!(word.load(Ordering::Acquire), 0);
        {
            let mut ds = shared.debug.debug_state.lock();
            assert!(!ds.thread_frames.contains_key(&t));
            assert!(ds.frame_locals.keys().all(|&(of, _)| of != t));
            ds.resume_all();
            crate::debug::publish_debugger_gates(&shared, &ds);
        }
        assert!(!publish_frames_of_blocked_thread(&shared, t), "closed");
        shared.debug.debugger_gates.set_session_attached(false);
        thread
            .gc_block_state
            .in_blocked_region
            .store(false, Ordering::Release);
        registry.mark_dead(tid);
    }

    /// A suspending `Exception` request parks the thread at the throw site
    /// with its frames published, before the unwind; after the resume the
    /// handler receives the (pinned) exception.
    #[test]
    fn a_suspending_exception_request_parks_at_the_throw() {
        use std::time::{Duration, Instant};
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let exc_class = shared
            .classes
            .class_manager
            .write()
            .try_ensure_synthetic_class("cratonvm/test/W10ParkThrown", 0)
            .expect("Compatible mode fabricates");
        let exc = shared.mem.heap.alloc_object(exc_class, 0);
        let owner = ClassId::new(0x00F1_0A02);
        let _ = arm(
            &shared,
            EventKind::Exception,
            SuspendPolicy::EventThread,
            vec![],
        );
        let rx = channel(&shared);
        let (caught, observed) = std::thread::scope(|s| {
            let resumer = s.spawn(|| {
                let deadline = Instant::now() + Duration::from_secs(30);
                loop {
                    {
                        let mut ds = shared.debug.debug_state.lock();
                        if ds.is_parked(0) {
                            let top = ds
                                .thread_frames
                                .get(&0)
                                .and_then(|f| f.first())
                                .map(|e| e.offset);
                            ds.resume_thread(0);
                            return top;
                        }
                        if Instant::now() > deadline {
                            ds.resume_all();
                            return None;
                        }
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
            });
            let mut t = JvmThread::new(ThreadId(0), "w10-exception-park");
            t.frames
                .push(frame(owner, "parker", vec![catch_all(0, 10, 8)]));
            let mut idx = 0usize;
            let r = unwind_to_handler(&shared, &mut t, &mut idx, 0, exc, 4);
            let pins_left = t.native_pin_roots.len();
            let top = t.frames[0].stack.pop().ok();
            (
                (r.is_ok(), pins_left, top, t.frames[0].pc),
                resumer.join().expect("the resumer thread"),
            )
        });
        assert_eq!(
            observed,
            Some(4),
            "parked at the throw pc, frames published"
        );
        assert_eq!(
            caught,
            (true, 0, Some(Value::Object(Some(exc))), 8),
            "the handler holds the exception; no pin is left"
        );
        assert_eq!(rx.try_iter().count(), 1);
        disarm(&shared);
    }

    /// A class `name` of the application loader declaring `methods` (each
    /// with no code) and `pool` as its constant pool (wave 15).
    fn class_with(
        shared: &SharedVm,
        name: &str,
        pool: Vec<ConstantPoolEntry>,
        methods: Vec<(
            &str,
            &str,
            cratonvm_reader::class_access_flags::MethodAccessFlags,
        )>,
    ) -> ClassId {
        let id = add_class(shared, name, Vec::new(), 0);
        let mut cm = shared.classes.class_manager.write();
        let class = cm.get_class_mut(id).expect("just added");
        class.constant_pool = ConstantPool::new(pool);
        class.methods = methods
            .into_iter()
            .map(
                |(name, desc, flags)| cratonvm_reader::method::ClassFileMethod {
                    access_flags: flags,
                    name: Arc::from(name),
                    descriptor: Arc::from(desc),
                    attributes: Vec::new(),
                },
            )
            .collect();
        id
    }

    /// Wave 15 (the suspension page's native-method frame): a thread
    /// suspended while blocked in a native method lists that method first,
    /// at location -1 — named from the invoke at its caller's
    /// `last_instr_pc`, only when no override can replace it — and its
    /// interpreter frames from id 1; `GetValues` on the native frame is
    /// `OPAQUE_FRAME`, and the caller's locals keep answering under its id.
    #[test]
    fn a_thread_blocked_in_a_native_method_lists_the_native_frame() {
        use crate::debug::commands::{
            dispatch, CMD_SF_GET_VALUES, CMD_TR_FRAMES, CS_STACK_FRAME, CS_THREAD_REF, ERR_NONE,
            ERR_OPAQUE_FRAME,
        };
        use crate::debug::protocol::PayloadWriter;
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let natives = class_with(
            &shared,
            "cratonvm/test/W15Natives",
            vec![ConstantPoolEntry::Tombstone],
            vec![
                ("sleep0", "(J)V", M::STATIC | M::NATIVE),
                ("virt", "()V", M::PUBLIC | M::NATIVE),
                ("spin", "()V", M::STATIC),
            ],
        );
        let caller = class_with(
            &shared,
            "cratonvm/test/W15NativeCaller",
            vec![
                ConstantPoolEntry::Tombstone,
                ConstantPoolEntry::Utf8("cratonvm/test/W15Natives".into()),
                ConstantPoolEntry::ClassReference { name_index: 1 },
                ConstantPoolEntry::Utf8("sleep0".into()),
                ConstantPoolEntry::Utf8("(J)V".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 3,
                    descriptor_index: 4,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 5,
                },
                ConstantPoolEntry::Utf8("virt".into()),
                ConstantPoolEntry::Utf8("()V".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 7,
                    descriptor_index: 8,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 9,
                },
                ConstantPoolEntry::Utf8("spin".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 11,
                    descriptor_index: 8,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 12,
                },
            ],
            vec![("run", "()V", M::STATIC)],
        );
        // invokestatic #6 (sleep0); invokevirtual #10 (virt);
        // invokespecial #10 (virt); invokestatic #13 (spin); return.
        let code = vec![0xb8, 0, 6, 0xb6, 0, 10, 0xb7, 0, 10, 0xb8, 0, 13, 0xb1];
        let mut top = Frame::new(
            caller,
            "cratonvm/test/W15NativeCaller".to_string(),
            "run".to_string(),
            "()V".to_string(),
            None,
            code,
            Vec::new(),
            4,
            1,
            &[],
        );
        let natives_wire = u64::from(natives.as_u32());
        let sleep0 = Some((natives_wire, crate::debug::jdwp_method_id("sleep0", "(J)V")));
        let at = |top: &mut Frame, pc: usize| {
            top.last_instr_pc = pc;
            blocked_native_method(&shared, top, 0)
        };
        assert_eq!(at(&mut top, 0), sleep0, "a static native");
        assert_eq!(at(&mut top, 3), None, "a virtual call an override may take");
        assert_eq!(
            at(&mut top, 6),
            Some((natives_wire, crate::debug::jdwp_method_id("virt", "()V"))),
            "invokespecial names its method"
        );
        assert_eq!(at(&mut top, 9), None, "not a native");
        assert_eq!(at(&mut top, 12), None, "not an invoke");

        // Suspended while it blocks in `sleep0`: published on entry.
        top.last_instr_pc = 0;
        top.set_local(0, Value::Int(3));
        let tid = 0x0F15;
        let mut thread = JvmThread::new(ThreadId(tid), "w15-native");
        thread.frames.push(top);
        shared.debug.debugger_gates.set_session_attached(true);
        {
            let mut ds = shared.debug.debug_state.lock();
            ds.thread_names.insert(tid, "w15-native".into());
            ds.suspend_thread(tid);
            crate::debug::publish_debugger_gates(&shared, &ds);
        }
        assert!(publish_blocked_frames(&shared, &thread));
        let mut ds = shared.debug.debug_state.lock();
        let listed: Vec<(u64, u64, u64)> = ds
            .thread_frames
            .get(&tid)
            .map(|frames| {
                frames
                    .iter()
                    .map(|f| (f.frame_id, f.class_id, f.offset))
                    .collect()
            })
            .unwrap_or_default();
        assert_eq!(
            listed,
            vec![
                (0, natives_wire, crate::debug::NATIVE_FRAME_LOCATION),
                (1, u64::from(caller.as_u32()), 0),
            ]
        );
        let mut frames = PayloadWriter::new();
        frames.put_u64_be(tid);
        frames.put_u32_be(0);
        frames.put_u32_be(u32::MAX); // -1: all
        let res = dispatch(CS_THREAD_REF, CMD_TR_FRAMES, &frames.into_bytes(), &mut ds);
        assert_eq!(res.error_code, ERR_NONE);
        assert_eq!(be64(&res.data[29..37]), u64::MAX, "location index -1");
        let get = |ds: &mut crate::debug::DebugState, frame: u64| {
            let mut pw = PayloadWriter::new();
            pw.put_u64_be(tid);
            pw.put_u64_be(frame);
            pw.put_u32_be(1);
            pw.put_u32_be(0);
            pw.put_u8(b'I');
            dispatch(CS_STACK_FRAME, CMD_SF_GET_VALUES, &pw.into_bytes(), ds)
        };
        assert_eq!(get(&mut ds, 0).error_code, ERR_OPAQUE_FRAME);
        let caller_locals = get(&mut ds, 1);
        assert_eq!(caller_locals.error_code, ERR_NONE);
        assert_eq!(caller_locals.data, vec![0, 0, 0, 1, b'I', 0, 0, 0, 3]);
        ds.resume_all();
        crate::debug::publish_debugger_gates(&shared, &ds);
        let stale = withdraw_debugger_frames(&mut ds, tid);
        for id in stale {
            ds.objects.unpin(id);
        }
        drop(ds);
        shared.debug.debugger_gates.set_session_attached(false);
    }

    /// Wave 17 (the running-native record): a virtual call to an overridable
    /// native is named from the callback the thread runs, as the resolved
    /// class's native or a loaded subclass's override, whichever registers
    /// that callback; with no record, or a callback no candidate registers,
    /// the caller stays the top.
    #[test]
    fn a_virtual_call_to_an_overridable_native_is_named_from_the_running_callback() {
        use cratonvm_native_api::NativeKind;
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        fn base_virt(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Int(17)))
        }
        fn sub_virt(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Int(1717)))
        }
        fn unrelated(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Long(17)))
        }
        const BASE: &str = "cratonvm/test/W17VirtBase";
        const SUB: &str = "cratonvm/test/W17VirtSub";
        let mut vm = SharedVm::new(crate::config::VmConfig::default());
        let registry = &mut vm.natives.native_methods;
        registry.register_with_kind(BASE, "virt", "()V", base_virt, NativeKind::Bridge);
        registry.register_with_kind(SUB, "virt", "()V", sub_virt, NativeKind::Bridge);
        let shared = Arc::new(vm);
        let native = vec![("virt", "()V", M::PUBLIC | M::NATIVE)];
        let base = class_with(
            &shared,
            BASE,
            vec![ConstantPoolEntry::Tombstone],
            native.clone(),
        );
        let sub = class_with(&shared, SUB, vec![ConstantPoolEntry::Tombstone], native);
        shared
            .classes
            .class_manager
            .write()
            .set_superclass(sub, Some(base));
        let caller = class_with(
            &shared,
            "cratonvm/test/W17VirtCaller",
            vec![
                ConstantPoolEntry::Tombstone,
                ConstantPoolEntry::Utf8(BASE.into()),
                ConstantPoolEntry::ClassReference { name_index: 1 },
                ConstantPoolEntry::Utf8("virt".into()),
                ConstantPoolEntry::Utf8("()V".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 3,
                    descriptor_index: 4,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 5,
                },
            ],
            vec![("run", "()V", M::STATIC)],
        );
        // invokevirtual #6 (virt); return.
        let mut top = Frame::new(
            caller,
            "cratonvm/test/W17VirtCaller".to_string(),
            "run".to_string(),
            "()V".to_string(),
            None,
            vec![0xb6, 0, 6, 0xb1],
            Vec::new(),
            4,
            1,
            &[],
        );
        top.last_instr_pc = 0;
        let virt = crate::debug::jdwp_method_id("virt", "()V");
        let named = |running: usize| blocked_native_method(&shared, &top, running);
        assert_eq!(named(0), None, "no record: an override may have been taken");
        assert_eq!(
            named(base_virt as usize), // Cast: fn address
            Some((u64::from(base.as_u32()), virt))
        );
        assert_eq!(
            named(sub_virt as usize), // Cast: fn address
            Some((u64::from(sub.as_u32()), virt)),
            "the subclass's override"
        );
        assert_eq!(named(unrelated as usize), None, "no candidate runs it"); // Cast: fn address
    }

    /// Wave 17: the native-call funnel records the running native only while
    /// a debugger is attached, and an upcall's native restores the outer one.
    #[test]
    fn the_running_native_is_recorded_only_while_a_debugger_is_attached() {
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let mut thread = JvmThread::new(ThreadId(0x0F17), "w17-running-native");
        assert_eq!(enter_running_native(&shared, &mut thread, 0x1000), None);
        assert_eq!(thread.running_native, 0);
        shared.debug.debugger_gates.set_session_attached(true);
        let outer = enter_running_native(&shared, &mut thread, 0x1000);
        let inner = enter_running_native(&shared, &mut thread, 0x2000);
        assert_eq!(thread.running_native, 0x2000);
        leave_running_native(&mut thread, inner);
        assert_eq!(thread.running_native, 0x1000, "the outer native again");
        leave_running_native(&mut thread, outer);
        assert_eq!(thread.running_native, 0);
        shared.debug.debugger_gates.set_session_attached(false);
    }

    /// Interpreter round i2 wave 61, lane L6: the funnel's callback record
    /// another thread reads (`GcBlockState::funnel_native_callback`) is kept
    /// only while the funnel records, nests, and is gone after the outer
    /// native's leave; the registry answers it.
    #[test]
    fn i61_l6_the_funnel_native_callback_is_recorded_and_restored() {
        use std::sync::atomic::Ordering;
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let mut thread = JvmThread::new(ThreadId(0x0F61), "i61-funnel-callback");
        let cell = |t: &JvmThread| {
            t.gc_block_state
                .funnel_native_callback
                .load(Ordering::Acquire)
        };
        assert!(!shared.debug.debugger_gates.running_native_armed());
        assert_eq!(enter_running_native(&shared, &mut thread, 0x1000), None);
        assert_eq!(cell(&thread), 0, "nothing recorded while nobody asks");
        shared.debug.debugger_gates.set_session_attached(true);
        assert!(shared.debug.debugger_gates.running_native_armed());
        let outer = enter_running_native(&shared, &mut thread, 0x1000);
        let inner = enter_running_native(&shared, &mut thread, 0x2000);
        assert_eq!(cell(&thread), 0x2000);
        leave_running_native(&mut thread, inner);
        assert_eq!(cell(&thread), 0x1000, "the outer native again");
        leave_running_native(&mut thread, outer);
        assert_eq!(cell(&thread), 0);
        shared.debug.debugger_gates.set_session_attached(false);
        assert!(!shared.debug.debugger_gates.running_native_armed());
        // No registration runs a made-up address.
        assert!(!funnel_callback_runs_a_native_method(&shared, 0x2000));
        assert!(!funnel_callback_runs_a_native_method(&shared, 0));
    }

    /// Interpreter round i2 wave 53, lane L6: the thread's acknowledgement of
    /// a JDWP suspension in a native (`GcBlockState::debugger_native_ack`) is
    /// lowered while Java the native runs executes and put back after; a
    /// thread under no native pays one load and keeps nothing; leaving a
    /// native restores what its caller had.
    #[test]
    fn java_a_native_runs_lowers_the_native_acknowledgement_while_it_runs() {
        use std::sync::atomic::Ordering;
        let mut thread = JvmThread::new(ThreadId(0x0F53), "w53-native-ack");
        let ack = |t: &JvmThread| t.gc_block_state.debugger_native_ack.load(Ordering::Acquire);
        {
            let guard = NestedJavaAck::enter(&thread);
            assert!(guard.state.is_none(), "under no native");
        }
        assert!(!ack(&thread));
        // In a native that acknowledged.
        thread.running_native = 0x1000;
        thread
            .gc_block_state
            .debugger_native_ack
            .store(true, Ordering::Release);
        {
            let _outer = NestedJavaAck::enter(&thread);
            assert!(!ack(&thread), "its Java runs");
            {
                let inner = NestedJavaAck::enter(&thread);
                assert!(inner.state.is_none(), "already lowered");
            }
            assert!(!ack(&thread));
        }
        assert!(ack(&thread), "back in the native");
        // Leaving the native puts back what its caller had.
        leave_running_native(
            &mut thread,
            Some(RunningNativePrior {
                callback: 0,
                ack: false,
                window: false,
                funnel: 0,
            }),
        );
        assert_eq!(thread.running_native, 0);
        assert!(!ack(&thread));
    }

    /// Interpreter round i2 wave 58, lane L1: the C JVMTI table's in-native
    /// mark (`GcBlockState::jvmti_in_native`) is lowered while Java a JNI
    /// native calls runs and put back after, nested upcalls included; the
    /// debugger's acknowledgement is left as it was.
    #[test]
    fn java_a_native_runs_lowers_the_jvmti_in_native_mark_while_it_runs() {
        use std::sync::atomic::Ordering;
        let mut thread = JvmThread::new(ThreadId(0x0F58), "w58-in-native");
        let mark = |t: &JvmThread| t.gc_block_state.jvmti_in_native.load(Ordering::Acquire);
        // What `jvmti::native_env::CInNativeMark` records for a JNI native.
        thread.running_native = 1;
        thread
            .gc_block_state
            .jvmti_in_native
            .store(true, Ordering::Release);
        {
            let outer = NestedJavaAck::enter(&thread);
            assert!(outer.state.is_some());
            assert!(!mark(&thread), "the upcall's Java is not in native");
            {
                let inner = NestedJavaAck::enter(&thread);
                assert!(inner.state.is_none(), "already lowered");
            }
            assert!(!mark(&thread));
        }
        assert!(mark(&thread), "back in the native");
        assert!(
            !thread
                .gc_block_state
                .debugger_native_ack
                .load(Ordering::Acquire),
            "the acknowledgement is not raised by the mark's restore"
        );
    }

    /// Interpreter round i2 wave 56, lane L6: the frame stack's one
    /// relocation shuts a native frames window -- no new reader -- keeping
    /// its published mark for the leave, and waits out a reader first.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn i56_l6_a_relocating_frame_stack_shuts_the_native_frames_window() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let word = std::sync::Arc::new(AtomicUsize::new(NW_OPEN | NW_PUBLISHED));
        let mut frames = crate::runtime::frame::FrameStack::new();
        frames.set_native_window(&*word as *const AtomicUsize as usize);
        frames.reserve_stable(1);
        assert_eq!(word.load(Ordering::Acquire), NW_PUBLISHED);
        // A reader holds it: the growth waits until it lets go.
        word.store(NW_OPEN | NW_READING, Ordering::Release);
        let reader = {
            let word = std::sync::Arc::clone(&word);
            std::thread::spawn(move || {
                std::thread::sleep(std::time::Duration::from_millis(50));
                word.fetch_and(!NW_READING, Ordering::AcqRel);
            })
        };
        frames.reserve_stable(frames.stable_headroom() + 1);
        reader.join().unwrap();
        assert_eq!(
            word.load(Ordering::Acquire),
            0,
            "shut once the reader let go"
        );
        frames.set_native_window(0);
    }

    /// Wave 56 (lane L6): Java a native runs shuts the native's frames
    /// window (the listing would not show that Java), keeping its published
    /// mark; the native's acknowledgement is lowered as before.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn i56_l6_java_a_native_runs_shuts_its_frames_window() {
        use std::sync::atomic::Ordering;
        let mut thread = JvmThread::new(ThreadId(0x0F56), "w56-native-window");
        thread.running_native = 0x1000;
        let state = std::sync::Arc::clone(&thread.gc_block_state);
        state.debugger_native_ack.store(true, Ordering::Release);
        state
            .debugger_native_window
            .store(NW_OPEN | NW_PUBLISHED, Ordering::Release);
        {
            let _java = NestedJavaAck::enter(&thread);
            assert_eq!(
                state.debugger_native_window.load(Ordering::Acquire),
                NW_PUBLISHED
            );
            assert!(!state.debugger_native_ack.load(Ordering::Acquire));
        }
        assert!(state.debugger_native_ack.load(Ordering::Acquire));
        assert_eq!(
            state.debugger_native_window.load(Ordering::Acquire),
            NW_PUBLISHED,
            "not reopened: the native's leave closes it"
        );
    }

    /// Interpreter round i2 wave 57, lane L6: a native frames window's frames
    /// stay current across pauses that move nothing (wave 56 refused every
    /// read after a loop-exit pause), go stale after a collection that moved
    /// objects, and are current again once the thread remapped them; a shut
    /// window is not refreshed.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn i57_l6_native_frames_stay_current_across_pauses_that_move_nothing() {
        use std::sync::atomic::Ordering;
        let shared = SharedVm::new(crate::config::VmConfig::default());
        let thread = JvmThread::new(ThreadId(0x0F57), "w57-frames-current");
        let state = std::sync::Arc::clone(&thread.gc_block_state);
        let barrier = &shared.mem.gc_barrier;
        let pause = |moved: bool| {
            assert!(barrier.request_stw(ThreadId(0), 1));
            barrier.wait_for_all();
            let mut pm = cratonvm_types::PointerMap::default();
            if moved {
                pm.insert(0x1000, 0x2000);
            }
            barrier.complete_gc(pm);
        };
        state
            .debugger_native_window
            .store(NW_OPEN, Ordering::Release);
        note_native_frames_current(&shared, &thread);
        assert!(!native_frames_stale(&shared, &state));
        pause(false);
        assert!(!native_frames_stale(&shared, &state), "nothing moved");
        pause(true);
        assert!(
            native_frames_stale(&shared, &state),
            "a collection moved objects"
        );
        note_native_frames_current(&shared, &thread);
        assert!(!native_frames_stale(&shared, &state), "remapped since");
        state.debugger_native_window.store(0, Ordering::Release);
        pause(true);
        note_native_frames_current(&shared, &thread);
        assert!(
            native_frames_stale(&shared, &state),
            "a shut window is not refreshed"
        );
    }

    /// The i53 retirement: the native frames window opens for a virtual
    /// thread, and for one with a JNI native's row or a reflective call below
    /// the native, whose rows it records for the reader (`NW_ROWS`); a later
    /// window with no rows carries no `NW_ROWS`. Before, each of the three
    /// refused it.
    #[cfg(feature = "experimental-debug")]
    #[test]
    fn i53_the_native_frames_window_records_the_rows_below_the_native() {
        use std::sync::atomic::Ordering;
        let shared = SharedVm::new(crate::config::VmConfig::default());
        if !shared.debug.debugger_gates.native_frames_window() {
            return; // `CRATONVM_DEBUG_NATIVE_FRAMES_WINDOW=0` in the environment.
        }
        let mut thread = JvmThread::new(ThreadId(0x0F53), "i53-native-window");
        thread.kind = crate::threading::ThreadKind::Virtual;
        thread.frames.push(Frame::new(
            ClassId::new(0),
            "T".to_string(),
            "m".to_string(),
            "()V".to_string(),
            None,
            vec![0xb8, 0, 1, 0xb1],
            vec![],
            8,
            4,
            &[],
        ));
        let row = (1usize, ClassId::new(53), 0x1000u64, 0u32);
        thread.jni_native_frames.push(row);
        let call = crate::runtime::stackwalker::ReflectiveCallRow {
            interp_depth: 1,
            jit_depth: 0,
            kind: cratonvm_native_api::ReflectiveCallKind::MethodInvoke,
            check: None,
            raised: None,
            door_save: None,
            adapter_pin: None,
        };
        thread.reflective_calls.push(call);
        let state = std::sync::Arc::clone(&thread.gc_block_state);
        assert!(open_native_frames_window(&shared, &mut thread, 0x2000));
        let w = state.debugger_native_window.load(Ordering::Acquire);
        assert_eq!(w & (NW_OPEN | NW_ROWS), NW_OPEN | NW_ROWS);
        {
            let rows = state.native_rows.lock();
            assert_eq!(rows.jni_rows, vec![row]);
            assert_eq!(rows.reflective_calls, vec![call]);
        }
        assert_eq!(state.debugger_native_depth.load(Ordering::Acquire), 1);
        close_native_frames_window(&shared, &mut thread);
        assert_eq!(state.debugger_native_window.load(Ordering::Acquire), 0);
        thread.jni_native_frames.clear();
        thread.reflective_calls.clear();
        assert!(open_native_frames_window(&shared, &mut thread, 0x2000));
        assert_eq!(
            state.debugger_native_window.load(Ordering::Acquire) & (NW_OPEN | NW_ROWS),
            NW_OPEN
        );
        close_native_frames_window(&shared, &mut thread);
    }

    /// Wave 26 (the native method events of
    /// `interpreter-L1-proposal-native-method-events-at-the-native-funnel-FIXED`): the real
    /// native-call funnel, and its leaf twin, report a JDWP `MethodEntry` and
    /// a `MethodExitWithReturnValue` at location -1 for the `ACC_NATIVE`
    /// method the caller's invoke names when the callback it runs is that
    /// method's — nothing without a request, for a callback the invoke does
    /// not name (a nested call), or for a registered stand-in of a method
    /// that is not `ACC_NATIVE`.
    #[test]
    fn the_native_funnel_reports_a_native_methods_entry_and_exit() {
        use cratonvm_native_api::NativeKind;
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        fn bits(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Int(1_069_547_520)))
        }
        fn stand_in(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Int(5)))
        }
        const NATIVES: &str = "cratonvm/test/W26Natives";
        let mut vm = SharedVm::new(crate::config::VmConfig::default());
        let registry = &mut vm.natives.native_methods;
        registry.register_with_kind(NATIVES, "bits", "(F)I", bits, NativeKind::Bridge);
        registry.register_with_kind(NATIVES, "java", "()I", stand_in, NativeKind::Bridge);
        let shared = Arc::new(vm);
        let natives = class_with(
            &shared,
            NATIVES,
            vec![ConstantPoolEntry::Tombstone],
            vec![
                ("bits", "(F)I", M::STATIC | M::NATIVE),
                ("java", "()I", M::STATIC),
            ],
        );
        let caller = class_with(
            &shared,
            "cratonvm/test/W26NativeCaller",
            vec![
                ConstantPoolEntry::Tombstone,
                ConstantPoolEntry::Utf8(NATIVES.into()),
                ConstantPoolEntry::ClassReference { name_index: 1 },
                ConstantPoolEntry::Utf8("bits".into()),
                ConstantPoolEntry::Utf8("(F)I".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 3,
                    descriptor_index: 4,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 5,
                },
                ConstantPoolEntry::Utf8("java".into()),
                ConstantPoolEntry::Utf8("()I".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 7,
                    descriptor_index: 8,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 9,
                },
            ],
            vec![("run", "()V", M::STATIC)],
        );
        // invokestatic #6 (bits); pop; invokestatic #10 (java); pop; return.
        let mut top = Frame::new(
            caller,
            "cratonvm/test/W26NativeCaller".to_string(),
            "run".to_string(),
            "()V".to_string(),
            None,
            vec![0xb8, 0, 6, 0x57, 0xb8, 0, 10, 0x57, 0xb1],
            Vec::new(),
            4,
            1,
            &[],
        );
        top.last_instr_pc = 0;
        let tid = 0x0F26;
        let mut thread = JvmThread::new(ThreadId(tid), "w26-native-events");
        thread.frames.push(top);
        shared.debug.debugger_gates.set_session_attached(true);
        let rx = channel(&shared);
        let args = [Value::Float(1.5)];
        let call = |thread: &mut JvmThread| {
            crate::vm::safe_native_call(&shared, thread, bits, &args)
                .ok()
                .flatten()
        };
        assert_eq!(call(&mut thread), Some(Value::Int(1_069_547_520)));
        assert!(rx.try_recv().is_err(), "no request, no event");
        assert!(!shared.debug.debugger_gates.method_events_armed());

        let entry = arm(
            &shared,
            EventKind::MethodEntry,
            SuspendPolicy::None,
            Vec::new(),
        );
        let exit = arm(
            &shared,
            EventKind::MethodExitWithReturnValue,
            SuspendPolicy::None,
            Vec::new(),
        );
        assert!(shared.debug.debugger_gates.method_events_armed());
        let natives_wire = u64::from(natives.as_u32());
        let bits_id = crate::debug::jdwp_method_id("bits", "(F)I");
        let reported = |rx: &Receiver<crate::debug::DebugEvent>| -> Vec<(EventKind, u32, u64, u64, u64, Vec<u8>)> {
            rx.try_iter()
                .map(|e| (e.kind, e.request_id, e.class_id, e.method_id, e.offset, e.extra))
                .collect()
        };
        let expected = vec![
            (
                EventKind::MethodEntry,
                entry,
                natives_wire,
                bits_id,
                crate::debug::NATIVE_FRAME_LOCATION,
                Vec::new(),
            ),
            (
                EventKind::MethodExitWithReturnValue,
                exit,
                natives_wire,
                bits_id,
                crate::debug::NATIVE_FRAME_LOCATION,
                // `I` and 1069547520 (0x3fc00000).
                vec![b'I', 0x3f, 0xc0, 0, 0],
            ),
        ];
        assert_eq!(call(&mut thread), Some(Value::Int(1_069_547_520)));
        assert_eq!(reported(&rx), expected, "the full funnel");
        let leaf = crate::vm::safe_native_call_leaf(&shared, &mut thread, bits, &args);
        assert_eq!(leaf.ok().flatten(), Some(Value::Int(1_069_547_520)));
        assert_eq!(reported(&rx), expected, "a leaf takes the full funnel");

        // A callback the invoke at pc 0 does not name: a nested call.
        let nested = crate::vm::safe_native_call(&shared, &mut thread, stand_in, &[]);
        assert_eq!(nested.ok().flatten(), Some(Value::Int(5)));
        assert!(reported(&rx).is_empty(), "a nested call reports nothing");
        // The registered stand-in of `java`, which is not `ACC_NATIVE`.
        if let Some(top) = thread.frames.last_mut() {
            top.last_instr_pc = 4;
        }
        let java = crate::vm::safe_native_call(&shared, &mut thread, stand_in, &[]);
        assert_eq!(java.ok().flatten(), Some(Value::Int(5)));
        assert!(reported(&rx).is_empty(), "a stand-in reports nothing");

        disarm(&shared);
        assert!(!shared.debug.debugger_gates.method_events_armed());
        *shared.debug.debug_event_tx.lock().expect("event channel") = None;
        shared.debug.debugger_gates.set_session_attached(false);
    }

    /// Wave 28 (stage 1 of
    /// `i27-L1-methods-served-without-a-frame-report-no-method-events`): a
    /// registered native standing in for a Java method with bytecode is not
    /// called while a breakpoint sits in that method — the funnel runs the
    /// bytecode, in a frame, where the breakpoint reports — and is called
    /// otherwise (no request, or a breakpoint elsewhere). A method HotSpot
    /// serves from a math entry keeps its native, and so (wave 28 follow-up)
    /// does a method whose native is a reviewed `NativeKind::Intrinsic`
    /// shadow outside the interpreter's intrinsic table — `Class.getName`,
    /// whose bytecode reads this VM's internal-name overlay.
    #[test]
    fn a_stood_in_java_method_runs_its_bytecode_under_a_breakpoint() {
        use cratonvm_native_api::NativeKind;
        use cratonvm_reader::attribute::{Attribute, CodeAttribute, LazyAttribute};
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        fn stand_in(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Int(5)))
        }
        const STANDIN: &str = "cratonvm/test/W28StandIn";
        // `--jdk-only`: a `Bridge` over bytecode may yield to it only there.
        let mut config = crate::config::VmConfig::default();
        config.compatibility_mode = cratonvm_types::compat::CompatibilityMode::JdkOnly;
        config.use_synthetic_jdk = false;
        let mut vm = SharedVm::new(config);
        vm.natives.native_methods.register_with_kind(
            STANDIN,
            "java",
            "()I",
            stand_in,
            NativeKind::Bridge,
        );
        // A reviewed shadow over bytecode the table does not serve.
        vm.natives.native_methods.register_with_kind(
            STANDIN,
            "shadowed",
            "()I",
            stand_in,
            NativeKind::Intrinsic,
        );
        vm.natives.native_methods.register_with_kind(
            "java/lang/Class",
            "getName",
            "()Ljava/lang/String;",
            stand_in,
            NativeKind::Intrinsic,
        );
        let shared = Arc::new(vm);
        let owner = class_with(
            &shared,
            STANDIN,
            vec![ConstantPoolEntry::Tombstone],
            vec![
                ("java", "()I", M::STATIC),
                ("other", "()V", M::STATIC),
                ("shadowed", "()I", M::STATIC),
            ],
        );
        // java: iconst_3; ireturn. shadowed: getstatic #1; ireturn, bytecode
        // that reads VM state (the `Class.getName` shape; wave 62, lane L1:
        // a shadow whose bytecode reads only its arguments runs it).
        for (method, code) in [(0, vec![0x06, 0xac]), (2, vec![0xb2, 0x00, 0x01, 0xac])] {
            shared
                .classes
                .class_manager
                .write()
                .get_class_mut(owner)
                .expect("just added")
                .methods[method]
                .attributes = vec![LazyAttribute::Decoded(Attribute::Code(Box::new(
                CodeAttribute {
                    max_stack: 1,
                    max_locals: 0,
                    code: cratonvm_reader::ByteView::from_vec(code),
                    exception_table: vec![],
                    attributes: vec![],
                },
            )))];
        }
        let caller = class_with(
            &shared,
            "cratonvm/test/W28StandInCaller",
            vec![
                ConstantPoolEntry::Tombstone,
                ConstantPoolEntry::Utf8(STANDIN.into()),
                ConstantPoolEntry::ClassReference { name_index: 1 },
                ConstantPoolEntry::Utf8("java".into()),
                ConstantPoolEntry::Utf8("()I".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 3,
                    descriptor_index: 4,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 5,
                },
                ConstantPoolEntry::Utf8("shadowed".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 7,
                    descriptor_index: 4,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 8,
                },
            ],
            vec![("run", "()V", M::STATIC)],
        );
        // invokestatic #6 (java); pop; invokestatic #9 (shadowed); pop; return.
        let mut top = Frame::new(
            caller,
            "cratonvm/test/W28StandInCaller".to_string(),
            "run".to_string(),
            "()V".to_string(),
            None,
            vec![0xb8, 0, 6, 0x57, 0xb8, 0, 9, 0x57, 0xb1],
            Vec::new(),
            4,
            1,
            &[],
        );
        top.last_instr_pc = 0;
        let mut thread = JvmThread::new(ThreadId(0x0F28), "w28-stand-in");
        thread.frames.push(top);
        shared.debug.debugger_gates.set_session_attached(true);
        let rx = channel(&shared);
        let call = |thread: &mut JvmThread| {
            crate::vm::safe_native_call(&shared, thread, stand_in, &[])
                .ok()
                .flatten()
        };
        assert_eq!(
            call(&mut thread),
            Some(Value::Int(5)),
            "no request: the native"
        );

        let wire = u64::from(owner.as_u32());
        let breakpoint_in = |method: &str, descriptor: &str| {
            arm(
                &shared,
                EventKind::Breakpoint,
                SuspendPolicy::None,
                vec![EventModifier::LocationOnly {
                    class_id: wire,
                    method_id: crate::debug::jdwp_method_id(method, descriptor),
                    offset: 0,
                }],
            )
        };
        let elsewhere = breakpoint_in("other", "()V");
        assert!(shared.debug.debugger_gates.java_frames_armed());
        assert!(shared.debug.debugger_gates.method_events_armed());
        assert_eq!(
            call(&mut thread),
            Some(Value::Int(5)),
            "a breakpoint in another method: the native"
        );
        assert!(rx.try_recv().is_err());
        let _ = elsewhere;

        let inside = breakpoint_in("java", "()I");
        assert_eq!(
            call(&mut thread),
            Some(Value::Int(3)),
            "a breakpoint in the method: its bytecode"
        );
        assert_eq!(thread.frames.len(), 1, "the method's frame is gone again");
        let hits: Vec<(EventKind, u32, u64, u64, u64)> = rx
            .try_iter()
            .map(|e| (e.kind, e.request_id, e.class_id, e.method_id, e.offset))
            .collect();
        assert_eq!(
            hits,
            vec![(
                EventKind::Breakpoint,
                inside,
                wire,
                crate::debug::jdwp_method_id("java", "()I"),
                0
            )],
            "the breakpoint reported from the method's frame"
        );

        // A breakpoint in a method whose native is a reviewed `Intrinsic`
        // shadow outside the intrinsic table: the native still answers.
        let _ = breakpoint_in("shadowed", "()I");
        if let Some(top) = thread.frames.last_mut() {
            top.last_instr_pc = 4;
        }
        assert_eq!(
            call(&mut thread),
            Some(Value::Int(5)),
            "a reviewed Intrinsic shadow: its native"
        );
        assert!(rx.try_recv().is_err(), "no frame, no breakpoint");
        {
            use super::jvmti_events::bytecode_reads_only_its_arguments as only_args;
            use super::jvmti_events::stood_in_bytecode_may_run as may_run;
            const CLASS: &str = "java/lang/Class";
            let get_name = "()Ljava/lang/String;";
            assert!(!may_run(&shared, CLASS, CLASS, "getName", get_name, false));
            assert!(!may_run(
                &shared, STANDIN, STANDIN, "shadowed", "()I", false
            ));
            assert!(
                may_run(&shared, STANDIN, STANDIN, "java", "()I", false),
                "a jdk-only Bridge"
            );
            // The interpreter's intrinsic table, whatever the registration.
            const STRING: &str = "java/lang/String";
            assert!(may_run(&shared, STRING, STRING, "length", "()I", false));
            assert!(may_run(
                &shared,
                "java/lang/Math",
                "java/lang/Math",
                "max",
                "(II)I",
                false
            ));
            // Wave 62 (lane L1): a reviewed shadow whose bytecode reads only
            // its arguments runs it (`Integer.numberOfLeadingZeros`).
            assert!(may_run(&shared, STANDIN, STANDIN, "shadowed", "()I", true));
            let cm = shared.classes.class_manager.read();
            assert!(only_args(&shared, &cm, owner, 0, 3), "iconst_3; ireturn");
            assert!(!only_args(&shared, &cm, owner, 2, 3), "a getstatic");
            assert!(!only_args(&shared, &cm, owner, 1, 3), "no Code attribute");
        }
        if let Some(top) = thread.frames.last_mut() {
            top.last_instr_pc = 0;
        }

        disarm(&shared);
        assert!(!shared.debug.debugger_gates.java_frames_armed());
        assert_eq!(
            call(&mut thread),
            Some(Value::Int(5)),
            "disarmed: the native"
        );
        assert!(super::jvmti_events::hotspot_serves_from_a_math_entry(
            "java/lang/Math",
            "sqrt",
            "(D)D"
        ));
        assert!(!super::jvmti_events::hotspot_serves_from_a_math_entry(
            "java/lang/Math",
            "abs",
            "(I)I"
        ));
        // Wave 130 (lane L1a, i40): the float16 conversions, and not their
        // neighbours.
        assert!(super::jvmti_events::hotspot_serves_from_a_float16_entry(
            "java/lang/Float",
            "float16ToFloat",
            "(S)F"
        ));
        assert!(super::jvmti_events::hotspot_serves_from_a_float16_entry(
            "java/lang/Float",
            "floatToFloat16",
            "(F)S"
        ));
        assert!(!super::jvmti_events::hotspot_serves_from_a_float16_entry(
            "java/lang/Float",
            "sum",
            "(FF)F"
        ));
        // Wave 134 (lane D, i40): several returns decline the frame-only
        // report; one return, or a return byte inside an operand, does not.
        assert!(super::shadow_has_several_returns(&[0x03, 0xac, 0x04, 0xac]));
        assert!(!super::shadow_has_several_returns(&[0x03, 0xac]));
        assert!(!super::shadow_has_several_returns(&[0x11, 0x00, 0xac, 0xac]));
        assert!(!super::shadow_has_several_returns(&[0x01, 0xbf]));
        *shared.debug.debug_event_tx.lock().expect("event channel") = None;
        shared.debug.debugger_gates.set_session_attached(false);
    }

    /// Wave 28 (`interpreter-L1-proposal-method-events-of-jni-bound-natives-FIXED`): a
    /// JNI-bound native (here bound as `RegisterNatives` binds one), which
    /// the general invocation path calls through `dispatch_jni_native` and
    /// never through the native-call funnel, reports its JDWP `MethodEntry`
    /// and `MethodExitWithReturnValue` at location -1 while requests for them
    /// are in force, and nothing otherwise.
    #[test]
    fn a_jni_bound_native_reports_its_method_entry_and_exit() {
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        extern "C" fn answer(
            _env: crate::native::jni::JNIEnv,
            _cls: crate::native::jni::JObject,
        ) -> u64 {
            42
        }
        const JNI: &str = "cratonvm/test/W28JniBound";
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        // The JNI arm reaches `SharedVm::get_arc`, which `Vm::new` would install.
        *shared.self_arc.write() = Some(Arc::downgrade(&shared));
        let owner = class_with(
            &shared,
            JNI,
            vec![ConstantPoolEntry::Tombstone],
            vec![("answer", "()I", M::STATIC | M::NATIVE)],
        );
        crate::native::jni::register_jni_native(
            &shared.natives,
            JNI,
            "answer",
            "()I",
            answer as *const () as usize, // Cast: fn address
        );
        let mut thread = JvmThread::new(ThreadId(0x0F29), "w28-jni-bound");
        shared.debug.debugger_gates.set_session_attached(true);
        let rx = channel(&shared);
        let call = |thread: &mut JvmThread| {
            crate::vm::invoke_on_class_shared(&shared, thread, owner, "answer", "()I", &[])
                .ok()
                .flatten()
        };
        assert_eq!(call(&mut thread), Some(Value::Int(42)));
        assert!(rx.try_recv().is_err(), "no request, no event");

        let entry = arm(
            &shared,
            EventKind::MethodEntry,
            SuspendPolicy::None,
            Vec::new(),
        );
        let exit = arm(
            &shared,
            EventKind::MethodExitWithReturnValue,
            SuspendPolicy::None,
            Vec::new(),
        );
        assert_eq!(call(&mut thread), Some(Value::Int(42)));
        let wire = u64::from(owner.as_u32());
        let id = crate::debug::jdwp_method_id("answer", "()I");
        let reported: Vec<(EventKind, u32, u64, u64, u64, Vec<u8>)> = rx
            .try_iter()
            .map(|e| {
                (
                    e.kind,
                    e.request_id,
                    e.class_id,
                    e.method_id,
                    e.offset,
                    e.extra,
                )
            })
            .collect();
        assert_eq!(
            reported,
            vec![
                (
                    EventKind::MethodEntry,
                    entry,
                    wire,
                    id,
                    crate::debug::NATIVE_FRAME_LOCATION,
                    Vec::new(),
                ),
                (
                    EventKind::MethodExitWithReturnValue,
                    exit,
                    wire,
                    id,
                    crate::debug::NATIVE_FRAME_LOCATION,
                    vec![b'I', 0, 0, 0, 42],
                ),
            ]
        );

        disarm(&shared);
        assert_eq!(call(&mut thread), Some(Value::Int(42)));
        assert!(rx.try_recv().is_err(), "disarmed: no event");
        *shared.debug.debug_event_tx.lock().expect("event channel") = None;
        shared.debug.debugger_gates.set_session_attached(false);
    }

    /// Wave 27 (the intrinsic item of
    /// `i24-L1-jdwp-method-events-and-stop-miss-native-and-compiled-code`):
    /// a native the interpreter's intrinsic table serves reaches the funnel
    /// with the intrinsic's trampoline, not its registered callback, and is
    /// named from either; `Thread.currentThread`, whose HotSpot interpreter
    /// entry posts no event, is the one native kept silent.
    #[test]
    fn an_intrinsic_trampoline_runs_the_native_it_serves() {
        use super::jvmti_events::{callback_runs_method, hotspot_posts_no_method_events};
        use cratonvm_native_api::InterpIntrinsic;
        use cratonvm_native_builtins::intrinsics::callback_for;
        fn other(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(None)
        }
        let shared = SharedVm::new(crate::config::VmConfig::default());
        const ARRAYCOPY: &str = "(Ljava/lang/Object;ILjava/lang/Object;II)V";
        let arraycopy = callback_for(InterpIntrinsic::SystemArraycopy) as usize; // Cast: fn address
        let hash = callback_for(InterpIntrinsic::ObjectHashCode) as usize; // Cast: fn address
        let runs = |class: &str, name: &str, desc: &str, running: usize| {
            callback_runs_method(&shared, class, name, desc, running)
        };
        assert!(runs("java/lang/System", "arraycopy", ARRAYCOPY, arraycopy));
        assert!(runs("java/lang/Object", "hashCode", "()I", hash));
        assert!(
            !runs("java/lang/Object", "hashCode", "()I", arraycopy),
            "another intrinsic's trampoline"
        );
        assert!(!runs("java/lang/Object", "hashCode", "()I", other as usize)); // Cast: fn address
        assert!(
            !runs("java/lang/Object", "hashCode", "()I", 0),
            "no running native"
        );
        assert!(hotspot_posts_no_method_events(
            "java/lang/Thread",
            "currentThread",
            "()Ljava/lang/Thread;"
        ));
        assert!(!hotspot_posts_no_method_events(
            "java/lang/System",
            "arraycopy",
            ARRAYCOPY
        ));
    }

    /// Wave 27 (stage 4 of
    /// `interpreter-L1-proposal-native-method-events-at-the-native-funnel-FIXED`): while
    /// the gate's JVMTI bit is up and an env of the VM listens, the real
    /// native-call funnel posts a JVMTI `MethodEntry` and a `MethodExit` (not
    /// popped by an exception, with the `jint` result) carrying the native
    /// method's real `jmethodID`; with the bit down it posts nothing, and the
    /// JDWP half of the gate stays down throughout.
    #[test]
    fn the_native_funnel_posts_jvmti_method_events_of_a_native() {
        use crate::runtime::jvmti::{
            self as rt, EventCallbacks, EventMode, JvmtiEventKind, JvmtiEventManager, LocalValue,
        };
        use cratonvm_native_api::NativeKind;
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        use std::sync::Mutex;
        fn bits(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Int(1_069_547_520)))
        }
        let _lock = rt::jvmti_registry_test_lock();
        const NATIVES: &str = "cratonvm/test/W27Natives";
        let mut vm = SharedVm::new(crate::config::VmConfig::default());
        vm.natives.native_methods.register_with_kind(
            NATIVES,
            "bits",
            "(F)I",
            bits,
            NativeKind::Bridge,
        );
        let shared = Arc::new(vm);
        *shared.self_arc.write() = Some(Arc::downgrade(&shared));
        let vm_id = shared.vm_identity;
        rt::install_manager_for_vm(vm_id, Arc::new(JvmtiEventManager::new_for_vm(vm_id)));
        // `resolve_method_id_for_vm` reaches the VM through its bridge.
        rt::install_real_agent_env_bridge(&shared);
        let natives = class_with(
            &shared,
            NATIVES,
            vec![ConstantPoolEntry::Tombstone],
            vec![("bits", "(F)I", M::STATIC | M::NATIVE)],
        );
        let caller = class_with(
            &shared,
            "cratonvm/test/W27NativeCaller",
            vec![
                ConstantPoolEntry::Tombstone,
                ConstantPoolEntry::Utf8(NATIVES.into()),
                ConstantPoolEntry::ClassReference { name_index: 1 },
                ConstantPoolEntry::Utf8("bits".into()),
                ConstantPoolEntry::Utf8("(F)I".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 3,
                    descriptor_index: 4,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 5,
                },
            ],
            vec![("run", "()V", M::STATIC)],
        );
        // invokestatic #6 (bits); pop; return.
        let mut top = Frame::new(
            caller,
            "cratonvm/test/W27NativeCaller".to_string(),
            "run".to_string(),
            "()V".to_string(),
            None,
            vec![0xb8, 0, 6, 0x57, 0xb1],
            Vec::new(),
            4,
            1,
            &[],
        );
        top.last_instr_pc = 0;
        let tid = 0x0F27;
        let mut thread = JvmThread::new(ThreadId(tid), "w27-jvmti-native-events");
        thread.frames.push(top);
        let seen: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
        let (on_entry, on_exit) = (Arc::clone(&seen), Arc::clone(&seen));
        let manager = rt::manager_for_vm(vm_id).expect("installed");
        for kind in [JvmtiEventKind::MethodEntry, JvmtiEventKind::MethodExit] {
            manager
                .set_event_notification_mode(EventMode::Enable, kind, None)
                .expect("enable");
        }
        manager
            .set_event_callbacks(EventCallbacks {
                method_entry: Some(Box::new(move |t, m| {
                    on_entry
                        .lock()
                        .expect("sink")
                        .push(format!("entry {t} {m:#x}"));
                })),
                method_exit: Some(Box::new(move |t, m, popped, v| {
                    on_exit
                        .lock()
                        .expect("sink")
                        .push(format!("exit {t} {m:#x} {popped} {v:?}"));
                })),
                ..Default::default()
            })
            .expect("callbacks");
        let args = [Value::Float(1.5)];
        let call = |thread: &mut JvmThread| {
            crate::vm::safe_native_call(&shared, thread, bits, &args)
                .ok()
                .flatten()
        };

        assert!(!shared.debug.debugger_gates.method_events_armed());
        assert_eq!(call(&mut thread), Some(Value::Int(1_069_547_520)));
        assert!(seen.lock().expect("sink").is_empty(), "the gate is down");

        shared.debug.debugger_gates.set_jvmti_method_events(true);
        assert!(shared.debug.debugger_gates.method_events_armed());
        assert!(!shared.debug.debugger_gates.jdwp_method_events_armed());
        assert_eq!(call(&mut thread), Some(Value::Int(1_069_547_520)));
        // `(class id << 32) | method index`; `bits` is method 0.
        let id = u64::from(natives.as_u32()) << 32;
        assert_eq!(
            *seen.lock().expect("sink"),
            vec![
                format!("entry {tid} {id:#x}"),
                format!(
                    "exit {tid} {id:#x} false {:?}",
                    LocalValue::Int(1_069_547_520)
                ),
            ]
        );
        assert!(thread.native_pin_roots.is_empty(), "no pin left behind");

        shared.debug.debugger_gates.set_jvmti_method_events(false);
        assert!(!shared.debug.debugger_gates.method_events_armed());
        rt::forget_vm_jvmti_state(vm_id);
    }

    /// Wave 21, lane L3
    /// (`i18-L3-proposal-jdwp-lists-the-compiled-activations-of-a-blocked-thread`,
    /// stages 1-3): the compiled activations a blocked thread recorded are
    /// listed at their places between its interpreter frames; a frame whose
    /// body runs compiled is listed at the compiled half's bytecode index;
    /// `GetValues` / `ThisObject` on either answer `OPAQUE_FRAME` instead of
    /// stale values, the other frames keep their locals, and no native frame
    /// is listed above a compiled one. Without compiled code the capture is
    /// empty, and the withdrawal forgets the opaque ids.
    /// Interpreter round i1 wave 47, lane L1: the one listing puts a stand-in's
    /// Java levels under the native on top, a JNI native's row right below the
    /// first interpreter frame its call pushed, and a reflective call's JDK
    /// frames right below the first compiled activation entered after it (an
    /// inlined callee is never such a place), as a stack trace places them.
    #[test]
    fn one_listing_places_standin_levels_and_splices() {
        use crate::threading::jvm_thread::{BlockedCompiledRow, BlockedCompiledView};
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let class = class_with(
            &shared,
            "cratonvm/test/W47Listing",
            vec![ConstantPoolEntry::Tombstone],
            vec![("run", "()V", M::STATIC)],
        );
        let frame = |pc: usize| {
            let mut f = Frame::new(
                class,
                "cratonvm/test/W47Listing".to_string(),
                "run".to_string(),
                "()V".to_string(),
                None,
                vec![0x00; 16],
                Vec::new(),
                4,
                1,
                &[],
            );
            f.last_instr_pc = pc;
            f
        };
        let frames = vec![frame(3), frame(5)];
        let wire = u64::from(class.as_u32());
        let run = crate::debug::jdwp_method_id("run", "()V");
        let compiled_row = |below: u32, method_id: u64, chain: Option<u32>| BlockedCompiledRow {
            below,
            class_id: class.as_u32(),
            method_id,
            bci: 4,
            chain,
        };
        let view = BlockedCompiledView {
            rows: vec![
                compiled_row(1, 0xA, Some(0)),
                compiled_row(2, 0xB, Some(1)),
                compiled_row(2, 0xC, None),
            ],
            stale: Vec::new(),
            homes: Vec::new(),
        };
        let splices = [
            ListingSplice {
                interp_depth: 1,
                jit_depth: 1,
                kind: 1,
                rows: vec![(7, 0x11, -1)],
                values: None,
            },
            ListingSplice {
                interp_depth: 2,
                jit_depth: 1,
                kind: 0,
                rows: vec![(8, 0x21, 102), (9, 0x22, 23)],
                values: None,
            },
        ];
        let head = NativeHead::from_standin_chain(&[
            crate::native::registry::StackTraceEntry {
                class_name: Arc::from("java/lang/Thread"),
                method_name: Arc::from("sleep"),
                method_descriptor: Some(Arc::from("(J)V")),
                source_file: None,
                line_number: 540,
                byte_code_index: 17,
                class_id: Some(ClassId::new(5)),
                method_index: Some(3),
            },
            crate::native::registry::StackTraceEntry {
                class_name: Arc::from("java/lang/Thread"),
                method_name: Arc::from("sleepNanos0"),
                method_descriptor: Some(Arc::from("(J)V")),
                source_file: None,
                line_number: -2,
                byte_code_index: -1,
                class_id: Some(ClassId::new(5)),
                method_index: Some(4),
            },
        ])
        .expect("a chain with its native leaf");
        assert_eq!(
            head.native(),
            (5, crate::debug::jdwp_method_id("sleepNanos0", "(J)V"))
        );
        assert_eq!(head.levels().len(), 1);
        let listing = build_frame_listing(&frames, 6, Some(&head), &view, &splices);
        let opaque = |class_id: u64, method_id: u64, location: i64| ListingRow::Opaque {
            class_id,
            method_id,
            location,
            chain: None,
        };
        // Wave 120 (lane L1): a compiled activation's row carries its chain
        // index; an inlined callee's (0xC) none.
        let compiled = |method_id: u64, chain: Option<u32>| ListingRow::Opaque {
            class_id: wire,
            method_id,
            location: 4,
            chain,
        };
        let interp = |index: usize, location: i64| ListingRow::Interp {
            index,
            class_id: wire,
            method_id: run,
            location,
            runs_compiled: false,
        };
        assert_eq!(
            listing,
            vec![
                ListingRow::Head {
                    class_id: 5,
                    method_id: crate::debug::jdwp_method_id("sleepNanos0", "(J)V"),
                },
                opaque(5, crate::debug::jdwp_method_id("sleep", "(J)V"), 17),
                opaque(wire, 0xC, 4),
                compiled(0xB, Some(1)),
                opaque(9, 0x22, 23),
                opaque(8, 0x21, 102),
                interp(1, 6),
                opaque(7, 0x11, -1),
                compiled(0xA, Some(0)),
                interp(0, 3),
            ]
        );
        // Without splices the listing is the wave-46 one.
        let plain = build_frame_listing(&frames, 6, None, &view, &[]);
        assert_eq!(
            plain,
            vec![
                opaque(wire, 0xC, 4),
                compiled(0xB, Some(1)),
                interp(1, 6),
                compiled(0xA, Some(0)),
                interp(0, 3),
            ]
        );
        // Wave 49: a continuation's head lists its levels, top first, over
        // the kept frames, and no native row.
        let level = |method_id: u64, bci: u64| StandinLevel {
            class_id: 6,
            method_id,
            method_index: 0,
            bci,
            locals: StandinLevelLocals::Unknown,
        };
        let continuation =
            NativeHead::continuation(&[level(0x31, 8), level(0x32, 62)]).expect("two levels fit");
        assert!(!continuation.has_native());
        assert!(NativeHead::continuation(&[]).is_none());
        let empty = BlockedCompiledView::default();
        assert_eq!(
            build_frame_listing(&frames, 6, Some(&continuation), &empty, &[]),
            vec![
                opaque(6, 0x31, 8),
                opaque(6, 0x32, 62),
                interp(1, 6),
                interp(0, 3)
            ]
        );
    }

    /// j27 wave 4 (lane TRACEROWS, TR16-3): the compiled indy bridge's
    /// synthetic `<jit-indy>.bridge` frame (class id 0, no method) is in no
    /// debugger listing, as it is in no stack trace, `StackWalker` walk or
    /// `Thread.getStackTrace()` (`stackwalker::frame_is_vm_bridge`); the C
    /// JVMTI table already dropped its row (`native_env::other_rows`: no
    /// method resolves), JDWP listed it with class id 0.
    #[test]
    fn the_indy_bridge_frame_is_in_no_listing() {
        use crate::threading::jvm_thread::BlockedCompiledView;
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let class = class_with(
            &shared,
            "cratonvm/test/J27Bridge",
            vec![ConstantPoolEntry::Tombstone],
            vec![("run", "()V", M::STATIC)],
        );
        let frame = |class_id: ClassId, name: &str, method: &str, pc: usize| {
            let mut f = Frame::new(
                class_id,
                name.to_string(),
                method.to_string(),
                "()V".to_string(),
                None,
                vec![0x00; 16],
                Vec::new(),
                4,
                1,
                &[],
            );
            f.last_instr_pc = pc;
            f
        };
        let frames = vec![
            frame(class, "cratonvm/test/J27Bridge", "run", 3),
            frame(ClassId::new(0), "<jit-indy>", "bridge", 0),
            frame(class, "cratonvm/test/J27Bridge", "run", 5),
        ];
        let wire = u64::from(class.as_u32());
        let run = crate::debug::jdwp_method_id("run", "()V");
        let interp = |index: usize, location: i64| ListingRow::Interp {
            index,
            class_id: wire,
            method_id: run,
            location,
            runs_compiled: false,
        };
        let listing = build_frame_listing(&frames, 6, None, &BlockedCompiledView::default(), &[]);
        assert_eq!(listing, vec![interp(2, 6), interp(0, 3)]);
    }

    #[test]
    fn a_blocked_threads_compiled_activations_are_listed_without_locals() {
        use crate::debug::commands::{
            dispatch, CMD_SF_GET_VALUES, CMD_SF_THIS_OBJECT, CS_STACK_FRAME, ERR_NONE,
            ERR_OPAQUE_FRAME,
        };
        use crate::debug::protocol::PayloadWriter;
        use crate::threading::jvm_thread::{BlockedCompiledRow, BlockedCompiledView};
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        let shared = Arc::new(SharedVm::new(crate::config::VmConfig::default()));
        let class = class_with(
            &shared,
            "cratonvm/test/W21Blocked",
            vec![ConstantPoolEntry::Tombstone],
            vec![("run", "()V", M::STATIC)],
        );
        let frame = |pc: usize, local: i32| {
            let mut f = Frame::new(
                class,
                "cratonvm/test/W21Blocked".to_string(),
                "run".to_string(),
                "()V".to_string(),
                None,
                vec![0x00; 16],
                Vec::new(),
                4,
                1,
                &[],
            );
            f.last_instr_pc = pc;
            f.set_local(0, Value::Int(local));
            f
        };
        let frames = vec![frame(3, 10), frame(5, 20)];
        assert_eq!(
            capture_blocked_compiled_view(&frames),
            BlockedCompiledView::default(),
            "no compiled code on this thread"
        );
        let wire = u64::from(class.as_u32());
        let hot = crate::debug::jdwp_method_id("hot", "()V");
        let leaf = crate::debug::jdwp_method_id("leaf", "(I)V");
        let view = BlockedCompiledView {
            rows: vec![
                BlockedCompiledRow {
                    below: 1,
                    class_id: class.as_u32(),
                    method_id: hot,
                    bci: 9,
                    chain: Some(0),
                },
                BlockedCompiledRow {
                    below: 2,
                    class_id: class.as_u32(),
                    method_id: leaf,
                    bci: -1,
                    chain: Some(1),
                },
            ],
            stale: vec![(0, 7)],
            homes: Vec::new(),
        };
        let tid = 0x0F21;
        // A compiled activation stands above the top interpreter frame, so the
        // native is named from ITS invoke (wave 22): `leaf` is not a method of
        // the class, so none is, whatever the top frame's invoke names.
        let native_top = blocked_native_top(&shared, &frames, &view, 0);
        assert_eq!(native_top, None);
        let _ = wire;
        let mut ds = shared.debug.debug_state.lock();
        ds.thread_names.insert(tid, "w21-blocked".into());
        ds.suspend_thread(tid);
        publish_frame_snapshot(
            &shared,
            &frames,
            &mut ds,
            tid,
            5,
            native_top,
            Some(&view),
            &[],
            |_, _, v| v,
        );
        let listed: Vec<(u64, u64, u64)> = ds
            .thread_frames
            .get(&tid)
            .map(|frames| {
                frames
                    .iter()
                    .map(|f| (f.frame_id, f.method_id, f.offset))
                    .collect()
            })
            .unwrap_or_default();
        let run = crate::debug::jdwp_method_id("run", "()V");
        assert_eq!(
            listed,
            vec![(0, leaf, 0), (1, run, 5), (2, hot, 9), (3, run, 7),],
            "no native frame the compiled one did not call; a compiled frame of \
             unknown bci at code index 0 (wave 22), never at the native -1; the \
             OSR'd frame at its compiled bci"
        );
        assert_eq!(ds.opaque_frames.get(&(tid, 0)), Some(&true));
        assert_eq!(ds.opaque_frames.get(&(tid, 1)), None);
        assert_eq!(ds.opaque_frames.get(&(tid, 2)), Some(&true));
        assert_eq!(ds.opaque_frames.get(&(tid, 3)), Some(&false));
        let get = |ds: &mut crate::debug::DebugState, frame: u64| {
            let mut pw = PayloadWriter::new();
            pw.put_u64_be(tid);
            pw.put_u64_be(frame);
            pw.put_u32_be(1);
            pw.put_u32_be(0);
            pw.put_u8(b'I');
            dispatch(CS_STACK_FRAME, CMD_SF_GET_VALUES, &pw.into_bytes(), ds)
        };
        assert_eq!(get(&mut ds, 0).error_code, ERR_OPAQUE_FRAME);
        let live = get(&mut ds, 1);
        assert_eq!(live.error_code, ERR_NONE);
        assert_eq!(live.data, vec![0, 0, 0, 1, b'I', 0, 0, 0, 20]);
        assert_eq!(get(&mut ds, 2).error_code, ERR_OPAQUE_FRAME);
        assert_eq!(
            get(&mut ds, 3).error_code,
            ERR_OPAQUE_FRAME,
            "the OSR'd frame's locals are the values at entry"
        );
        let mut this = PayloadWriter::new();
        this.put_u64_be(tid);
        this.put_u64_be(2);
        assert_eq!(
            dispatch(
                CS_STACK_FRAME,
                CMD_SF_THIS_OBJECT,
                &this.into_bytes(),
                &mut ds
            )
            .error_code,
            ERR_OPAQUE_FRAME
        );
        let stale = withdraw_debugger_frames(&mut ds, tid);
        for id in stale {
            ds.objects.unpin(id);
        }
        assert!(ds.opaque_frames.is_empty());
        ds.resume_all();
    }

    /// Wave 22, lane L1 (`i9-L1-jdwp-suspension-does-not-reach-compiled-or-native-code`,
    /// item 3; `i15-L1-proposal-record-the-running-native-on-the-thread`,
    /// stage 3): a thread blocked in a native it called from COMPILED code
    /// lists that native first, named from the innermost compiled
    /// activation's invoke, and only while its running-native record is that
    /// native's registered callback (the activation's bci is the last
    /// safepoint it published, so the callback is what says the invoke there
    /// is the running one). No record, another callback, a bci that is not an
    /// invoke or is unknown, or a compiled row below the top interpreter
    /// frame: no native frame from the row.
    #[test]
    fn a_native_called_from_compiled_code_is_listed_above_it() {
        use crate::threading::jvm_thread::{BlockedCompiledRow, BlockedCompiledView};
        use cratonvm_native_api::NativeKind;
        use cratonvm_reader::attribute::{Attribute, CodeAttribute, LazyAttribute};
        use cratonvm_reader::class_access_flags::MethodAccessFlags as M;
        fn sleep0(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(None)
        }
        fn other(
            _: &mut dyn cratonvm_native_api::NativeContext,
            _: &[Value],
        ) -> cratonvm_types::error::MethodCallResult {
            Ok(Some(Value::Int(22)))
        }
        const NATIVES: &str = "cratonvm/test/W22Natives";
        const HOT: &str = "cratonvm/test/W22Hot";
        let mut vm = SharedVm::new(crate::config::VmConfig::default());
        vm.natives.native_methods.register_with_kind(
            NATIVES,
            "sleep0",
            "(J)V",
            sleep0,
            NativeKind::Bridge,
        );
        let shared = Arc::new(vm);
        let natives = class_with(
            &shared,
            NATIVES,
            vec![ConstantPoolEntry::Tombstone],
            vec![("sleep0", "(J)V", M::STATIC | M::NATIVE)],
        );
        let hot = class_with(
            &shared,
            HOT,
            vec![
                ConstantPoolEntry::Tombstone,
                ConstantPoolEntry::Utf8(NATIVES.into()),
                ConstantPoolEntry::ClassReference { name_index: 1 },
                ConstantPoolEntry::Utf8("sleep0".into()),
                ConstantPoolEntry::Utf8("(J)V".into()),
                ConstantPoolEntry::NameAndType {
                    name_index: 3,
                    descriptor_index: 4,
                },
                ConstantPoolEntry::MethodReference {
                    class_index: 2,
                    name_and_type_index: 5,
                },
            ],
            vec![("hot", "()V", M::STATIC)],
        );
        // hot: lconst_0; invokestatic #6 (sleep0); return.
        shared
            .classes
            .class_manager
            .write()
            .get_class_mut(hot)
            .expect("just added")
            .methods[0]
            .attributes = vec![LazyAttribute::Decoded(Attribute::Code(Box::new(
            CodeAttribute {
                max_stack: 2,
                max_locals: 0,
                code: cratonvm_reader::ByteView::from_vec(vec![0x09, 0xb8, 0, 6, 0xb1]),
                exception_table: vec![],
                attributes: vec![],
            },
        )))];
        // The interpreter frame the compiled `hot` was entered from.
        let mut main = Frame::new(
            hot,
            HOT.to_string(),
            "main".to_string(),
            "()V".to_string(),
            None,
            vec![0xb8, 0, 1, 0xb1],
            Vec::new(),
            2,
            1,
            &[],
        );
        main.last_instr_pc = 0;
        let frames = vec![main];
        let hot_id = crate::debug::jdwp_method_id("hot", "()V");
        let row = |below: u32, bci: i64| BlockedCompiledRow {
            below,
            class_id: hot.as_u32(),
            method_id: hot_id,
            bci,
            chain: Some(0),
        };
        let view = |below: u32, bci: i64| BlockedCompiledView {
            rows: vec![row(below, bci)],
            stale: Vec::new(),
            homes: Vec::new(),
        };
        let running = sleep0 as usize; // Cast: fn address
        let named = Some((
            u64::from(natives.as_u32()),
            crate::debug::jdwp_method_id("sleep0", "(J)V"),
        ));
        assert_eq!(
            blocked_native_top(&shared, &frames, &view(1, 1), running).map(|head| head.native()),
            named
        );
        assert_eq!(
            blocked_native_top(&shared, &frames, &view(1, 1), 0),
            None,
            "no running-native record"
        );
        assert_eq!(
            blocked_native_top(&shared, &frames, &view(1, 1), other as usize), // Cast: fn address
            None,
            "another native runs"
        );
        assert_eq!(
            blocked_native_top(&shared, &frames, &view(1, 0), running),
            None,
            "the bci is not an invoke"
        );
        assert_eq!(
            blocked_native_top(&shared, &frames, &view(1, -1), running),
            None,
            "the bci is unknown"
        );
        assert_eq!(
            blocked_native_top(&shared, &frames, &view(0, 1), running),
            None,
            "below the top frame: the top frame's own invoke decides"
        );

        let tid = 0x0F22;
        let mut ds = shared.debug.debug_state.lock();
        ds.thread_names
            .insert(tid, "w22-native-under-compiled".into());
        ds.suspend_thread(tid);
        publish_frame_snapshot(
            &shared,
            &frames,
            &mut ds,
            tid,
            0,
            named.map(|(class_id, method_id)| NativeHead::leaf(class_id, method_id)),
            Some(&view(1, 1)),
            &[],
            |_, _, v| v,
        );
        let listed: Vec<(u64, u64, u64)> = ds
            .thread_frames
            .get(&tid)
            .map(|frames| {
                frames
                    .iter()
                    .map(|f| (f.frame_id, f.method_id, f.offset))
                    .collect()
            })
            .unwrap_or_default();
        assert_eq!(
            listed,
            vec![
                (
                    0,
                    crate::debug::jdwp_method_id("sleep0", "(J)V"),
                    crate::debug::NATIVE_FRAME_LOCATION
                ),
                (1, hot_id, 1),
                (2, crate::debug::jdwp_method_id("main", "()V"), 0),
            ],
            "the native, then the compiled caller at its invoke, then main"
        );
        assert_eq!(ds.opaque_frames.get(&(tid, 1)), Some(&true));
        let stale = withdraw_debugger_frames(&mut ds, tid);
        for id in stale {
            ds.objects.unpin(id);
        }
        ds.resume_all();
    }
}

#[cfg(test)]
mod wave1_adoption_tests;

#[cfg(test)]
mod tests;

// JIT round 22 wave 6b (lane loops): HotSpot 25's NaN-operand table for the
// arithmetic ops (`docs/feature-designs/jdk-only-mode.md`;
// `FpNaN2` cold row: HotSpot's INTERPRETER; C2 answers value1's NaN for an
// add / mul of two NaNs, so only the interpreter follows these cells). Operands
// (row-major, value1 x value2): +NaN 7ff8.., -NaN(0x123), sNaN(1), 1.5; each
// cell is add, sub, mul, div, rem raw bits.
#[cfg(test)]
mod r22_loops_nan_payload_tests {
    use super::{
        java_dadd, java_ddiv, java_dmul, java_drem, java_dsub, java_fadd, java_fdiv, java_fmul,
        java_frem, java_fsub,
    };

    const DOUBLES: [u64; 4] = [
        0x7ff8_0000_0000_0000,
        0xfff8_0000_0000_0123,
        0x7ff0_0000_0000_0001,
        0x3ff8_0000_0000_0000,
    ];
    const FLOATS: [u32; 4] = [0x7fc0_0000, 0xffc0_0123, 0x7f80_0001, 0x3fc0_0000];

    const HOTSPOT_DOUBLE: [&str; 16] = [
            "7ff8000000000000,7ff8000000000000,7ff8000000000000,7ff8000000000000,7ff8000000000000",
            "fff8000000000123,7ff8000000000000,fff8000000000123,7ff8000000000000,7ff8000000000123",
            "7ff8000000000001,7ff8000000000000,7ff8000000000001,7ff8000000000000,7ff8000000000001",
            "7ff8000000000000,7ff8000000000000,7ff8000000000000,7ff8000000000000,7ff8000000000000",
            "7ff8000000000000,fff8000000000123,7ff8000000000000,fff8000000000123,7ff8000000000000",
            "fff8000000000123,fff8000000000123,fff8000000000123,fff8000000000123,7ff8000000000123",
            "7ff8000000000001,fff8000000000123,7ff8000000000001,fff8000000000123,7ff8000000000001",
            "fff8000000000123,fff8000000000123,fff8000000000123,fff8000000000123,7ff8000000000123",
            "7ff8000000000000,7ff8000000000001,7ff8000000000000,7ff8000000000001,7ff8000000000000",
            "fff8000000000123,7ff8000000000001,fff8000000000123,7ff8000000000001,7ff8000000000123",
            "7ff8000000000001,7ff8000000000001,7ff8000000000001,7ff8000000000001,7ff8000000000001",
            "7ff8000000000001,7ff8000000000001,7ff8000000000001,7ff8000000000001,7ff8000000000001",
            "7ff8000000000000,7ff8000000000000,7ff8000000000000,7ff8000000000000,7ff8000000000000",
            "fff8000000000123,fff8000000000123,fff8000000000123,fff8000000000123,fff8000000000123",
            "7ff8000000000001,7ff8000000000001,7ff8000000000001,7ff8000000000001,7ff8000000000001",
            "4008000000000000,0,4002000000000000,3ff0000000000000,0",
    ];

    const HOTSPOT_FLOAT: [&str; 16] = [
            "7fc00000,7fc00000,7fc00000,7fc00000,7fc00000",
            "ffc00123,7fc00000,ffc00123,7fc00000,7fc00123",
            "7fc00001,7fc00000,7fc00001,7fc00000,7fc00001",
            "7fc00000,7fc00000,7fc00000,7fc00000,7fc00000",
            "7fc00000,ffc00123,7fc00000,ffc00123,7fc00000",
            "ffc00123,ffc00123,ffc00123,ffc00123,7fc00123",
            "7fc00001,ffc00123,7fc00001,ffc00123,7fc00001",
            "ffc00123,ffc00123,ffc00123,ffc00123,7fc00123",
            "7fc00000,7fc00001,7fc00000,7fc00001,7fc00000",
            "ffc00123,7fc00001,ffc00123,7fc00001,7fc00123",
            "7fc00001,7fc00001,7fc00001,7fc00001,7fc00001",
            "7fc00001,7fc00001,7fc00001,7fc00001,7fc00001",
            "7fc00000,7fc00000,7fc00000,7fc00000,7fc00000",
            "ffc00123,ffc00123,ffc00123,ffc00123,ffc00123",
            "7fc00001,7fc00001,7fc00001,7fc00001,7fc00001",
            "40400000,0,40100000,3f800000,0",
    ];

    fn hex_cells(cell: &str) -> Vec<u64> {
        cell.split(',')
            .map(|c| u64::from_str_radix(c, 16).expect("a hex cell"))
            .collect()
    }

    #[test]
    fn the_double_ops_answer_hotspots_nan_table() {
        let mut k = 0;
        for &x in &DOUBLES {
            for &y in &DOUBLES {
                let (a, b) = (f64::from_bits(x), f64::from_bits(y));
                let got = [
                    java_dadd(a, b).to_bits(),
                    java_dsub(a, b).to_bits(),
                    java_dmul(a, b).to_bits(),
                    java_ddiv(a, b).to_bits(),
                    java_drem(a, b).to_bits(),
                ];
                assert_eq!(got.to_vec(), hex_cells(HOTSPOT_DOUBLE[k]), "{x:#x} op {y:#x}");
                k += 1;
            }
        }
    }

    #[test]
    fn the_float_ops_answer_hotspots_nan_table() {
        let mut k = 0;
        for &x in &FLOATS {
            for &y in &FLOATS {
                let (a, b) = (f32::from_bits(x), f32::from_bits(y));
                let got = [
                    u64::from(java_fadd(a, b).to_bits()),
                    u64::from(java_fsub(a, b).to_bits()),
                    u64::from(java_fmul(a, b).to_bits()),
                    u64::from(java_fdiv(a, b).to_bits()),
                    u64::from(java_frem(a, b).to_bits()),
                ];
                assert_eq!(got.to_vec(), hex_cells(HOTSPOT_FLOAT[k]), "{x:#x} op {y:#x}");
                k += 1;
            }
        }
    }
    /// Wave 7 (HotSpot 25.0.3, every tier, `R22LoopsNaNPayload` rows d4 / f4):
    /// a NaN divisor keeps its sign only over a FINITE dividend; an infinite
    /// one clears it like a NaN dividend does.
    #[test]
    fn a_nan_divisor_keeps_its_sign_only_over_a_finite_dividend() {
        let neg = f64::from_bits(0xfff8_0000_0000_0123);
        for (x, want) in [
            (f64::INFINITY, 0x7ff8_0000_0000_0123u64),
            (f64::NEG_INFINITY, 0x7ff8_0000_0000_0123),
            (-0.0, 0xfff8_0000_0000_0123),
            (1.5, 0xfff8_0000_0000_0123),
        ] {
            assert_eq!(java_drem(x, neg).to_bits(), want, "{x} % -NaN");
        }
        let negf = f32::from_bits(0xffc0_0123);
        for (x, want) in [
            (f32::INFINITY, 0x7fc0_0123u32),
            (f32::NEG_INFINITY, 0x7fc0_0123),
            (-0.0, 0xffc0_0123),
            (1.5, 0xffc0_0123),
        ] {
            assert_eq!(java_frem(x, negf).to_bits(), want, "{x} % -NaN");
        }
    }
}

/// JIT round 21 (lane osrreentry): the early OSR entry's tier-up credit
/// (`CRATONVM_JIT_OSR_EARLY_REENTRY_CREDIT`) and the loop-work retry crossing
/// (`CRATONVM_JIT_LOOP_WORK_RETRY_CROSSING`);
/// `docs/internal/fixed-bugs/jr21-osr-early-reentry-request-rows-FIXED-20261026.md`.
#[cfg(test)]
mod jr21_osrreentry_tests {
    use super::{loop_work_retry_boundary_crossed, osr_early_reentry_credit_enabled};
    use crate::jit::profile::LOOP_WORK_PER_INVOCATION;

    /// A credit that carries the counter across a multiple of 64 re-nominates;
    /// one that stays inside a stride, a credit of zero, and a landing exactly
    /// on the multiple (the old test's own case) do not answer here.
    #[test]
    fn the_retry_fires_on_a_crossing_not_only_on_a_landing() {
        let key = "CRATONVM_JIT_LOOP_WORK_RETRY_CROSSING";
        let full = LOOP_WORK_PER_INVOCATION * 31;
        cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            // 97 -> 128 lands: the exact-multiple test owns it.
            assert!(!loop_work_retry_boundary_crossed(128, full));
            // 100 -> 131 crosses 128.
            assert!(loop_work_retry_boundary_crossed(131, full));
            // 140 -> 171 stays inside [128, 192).
            assert!(!loop_work_retry_boundary_crossed(171, full));
            // No credit, no crossing.
            assert!(!loop_work_retry_boundary_crossed(129, LOOP_WORK_PER_INVOCATION - 1));
            // 64 -> 65 stays inside [64, 128).
            assert!(!loop_work_retry_boundary_crossed(65, LOOP_WORK_PER_INVOCATION));
        });
        cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
            assert!(!loop_work_retry_boundary_crossed(131, full));
        });
    }

    /// The early-entry credit is default ON with `=0` as its kill word.
    #[test]
    fn the_early_entry_credit_defaults_on() {
        let key = "CRATONVM_JIT_OSR_EARLY_REENTRY_CREDIT";
        cratonvm_types::flags::with_thread_overrides(&[(key, None)], || {
            assert!(osr_early_reentry_credit_enabled());
        });
        cratonvm_types::flags::with_thread_overrides(&[(key, Some("0"))], || {
            assert!(!osr_early_reentry_credit_enabled());
        });
    }

    /// Text pin: only an EARLY entry that ENDS the activation (a return or a
    /// throw out) raises the frame's count, to the schedule's threshold, and
    /// it does so before both credits read the count (the entry credit in
    /// this function and the frame pop's after it).
    #[test]
    fn only_an_activation_ending_early_entry_is_credited_before_the_credits() {
        let src = include_str!("interpreter.rs").replace("\r\n", "\n");
        let body_at = src.find("\nfn try_osr_offer(").expect("try_osr_offer");
        let body = &src[body_at..];
        let body = &body[..body.find("\n}\n").expect("its end")];
        let flat = body.split_whitespace().collect::<Vec<_>>().join(" ");
        let gate = flat
            .find(
                "if early_entry && (osr_throw.is_some() || osr_result.is_some()) \
                 && osr_early_reentry_credit_enabled() {",
            )
            .expect("the early credit's gate");
        let raise = flat[gate..]
            .find("f.backward_count = f.backward_count.max(osr_backedge_threshold);")
            .expect("the raise")
            + gate;
        let entry_credit = flat
            .find("if (osr_throw.is_some() || osr_result.is_some()) && osr_entry_tierup_armed() {")
            .expect("the entry credit");
        let pop = flat
            .find("pop_and_recycle_frame(shared, thread);")
            .expect("the pop");
        assert!(raise < entry_credit);
        assert!(raise < pop);
    }
}
